window.ATLAS_SRC = {"contracts/myapp/message.contract.mln":"namespace app_transport;\n\n// Shared request/event envelope. Domain-specific operations live in\n// ui.contract.mln and lifecycle.contract.mln. Transport implementation is\n// deliberately outside the contract.\n\nexport enum RequestDomain {\n    NONE,\n    UI,\n    APP,\n}\n\n/** Outcome of dispatching one request envelope to its owning service. */\nexport enum RequestStatus {\n    OK,\n    INVALID_DOMAIN,\n    INVALID_OPERATION,\n    MISSING_RESULT,\n}\n\nexport struct Request {\n    RequestDomain domain;\n    i32 op;\n    i32 owner;\n    i32 a0;\n    i32 a1;\n    i32 a2;\n    i32 a3;\n    i32 a4;\n    i32 a5;\n    char *s0;\n    char *s1;\n    // Optional typed result destination. The gateway replaces this user\n    // pointer with a kernel staging buffer and copies result_size bytes back\n    // with the reply. This is operation-independent.\n    i32 result_out;\n    i32 result_size;\n    // Byte lengths of s0 and s1: strings cross as views, not NUL-terminated.\n    i32 s0_len;\n    i32 s1_len;\n};\n\n// Sticky wake reasons used by the application transport. A failed nonblocking\n// operation arms its bit before returning; WAIT_NOTIFICATION then consumes the\n// bit or blocks, so a producer cannot signal in the check-to-sleep gap.\nexport enum TransportSignal {\n    REQUEST_SPACE = 1,\n    REPLY = 2,\n    EVENT = 4,\n}\n\nexport enum EventKind {\n    NONE,\n    CLICK,\n    CHANGE,\n    ACTIVATE,\n    TIMER,\n    KEY,\n    CLOSE,\n    OPEN,\n    CARET,    // a TextArea's caret moved: arg = line << 16 | column, both from 1\n}\n\n// All asynchronous notifications delivered to the application runtime.\nexport struct Event {\n    i32 owner;\n    i32 id;           // the node as a word: NodeId in the runtime\n    EventKind kind;\n    i32 arg;\n    i32 token;\n    // Inline storage gives each dequeued event its own text lifetime. It also\n    // keeps a queued OPEN path independent from the shell's scratch buffer.\n    char text[64];\n};\n","contracts/myapp/ui.contract.mln":"namespace ui_protocol;\n\n// Operations owned by the UI service. The request/event envelope is\n// message.contract.mln; app lifecycle operations are lifecycle.contract.mln.\n\nexport enum UiOp {\n    NONE,\n    // ui.mln --- text\n    SET_TEXT,          // (id, s0)\n    TEXT_COPY,         // (id, a1 = out, a2 = cap, result_out = Result<i32, UiError>*)\n    // ui.mln --- widgets\n    SET_CHECKED,       // (id, a1 = on)\n    INPUT_SET,         // (id, s0)\n    AREA_APPEND,       // (id, s0) -- a TextArea, or a Terminal as if a process wrote it\n    LIST_SET_ITEMS,    // (id, s0 = \"\\n\"-joined) -- a List's rows, or a MenuButton's items\n    LIST_SELECT,       // (id, a1 = row, or -1 for none)\n    GRAPH_SET,         // (id, a1 = series 0 or 1, s0 = percentages apart by spaces)\n    ADD_STYLE,         // (id, a1 = NodeStyle bits: GROW_W, GROW_H, PIN_BOTTOM, WRAP, REPORT_CARET)\n    TEXT_EDIT,         // (id, a1 = TextEdit) -- what Ctrl+X, C, V and A do, for an Edit menu\n    // ui.mln --- focus and windows\n    FOCUS,             // (id)\n    SEND_KEY,          // (a0 = type, a1 = code, a2 = mods)\n    // elements.mln --- creation writes Result<NodeId, UiError> to result_out\n    CREATE_WINDOW,     // (s0 = title, w, h, s1 = testId) -- the shell places it\n    CREATE_BUTTON,     // (s0 = text, x, y, w, h, s1)\n    CREATE_PRIMARY_BUTTON,\n    CREATE_TEXT,       // (s0 = text, x, y, s1)\n    CREATE_LABEL,      // (s0 = text, x, y, color, bold, s1)\n    CREATE_BOX,        // (x, y, w, h, background, border)\n    CREATE_PANEL,      // (x, y, w, h, radius)\n    CREATE_COLUMN,     // (x, y, w, h, padding, gap)\n    CREATE_ROW,        // (x, y, w, h, padding, gap)\n    CREATE_TEXT_INPUT, // (s0 = placeholder, x, y, w, h, capacity, s1)\n    CREATE_CHECKBOX,   // (s0 = text, x, y, checked, s1)\n    CREATE_SEPARATOR,  // (x, y, w)\n    CREATE_TIMER,      // (a0 = interval) -- ticks are TIMER events\n    CREATE_TEXT_AREA,  // (s0 = name, x, y, w, h, capacity, readonly, s1)\n    CREATE_LIST,       // (s0 = name, x, y, w, h, capacity, s1)\n    CREATE_GRAPH,      // (x, y, w, h, a4 = samples across, s1)\n    CREATE_TERMINAL,   // (s0 = name, x, y, w, h, capacity, s1)\n    CREATE_MENU_BUTTON, // (s0 = title, x, y, w, h, s1) -- its items come with LIST_SET_ITEMS\n    APPEND_CHILD,      // (a0 = parent, a1 = child) -> the child\n};\n\n/**\n * What TEXT_EDIT does to a TextInput or TextArea: the same as its keys. The\n * clipboard stays in the OS; a paste is the only way its text reaches an app.\n */\nexport enum TextEdit {\n    CUT = 1,         // Ctrl+X: the selection goes to the clipboard and out of the text\n    COPY = 2,        // Ctrl+C: the selection goes to the clipboard\n    PASTE = 3,       // Ctrl+V: the clipboard's text replaces the selection\n    SELECT_ALL = 4,  // Ctrl+A\n}\n","contracts/myos/process-args.contract.mln":"namespace myos_process_args;\n\nimport { Text } from \"@std/text/text.mln\";\n\n// OS_CALL argument records for the hosted process API.\n// Output types are supplied by the client as Result<_, ProcessControlError>\n// or Result<Pid, SpawnError>; their pointers address caller memory. A process\n// crosses here as a word.\n\nexport struct ProcSpawnArgs<Out> {\n    char *path;\n    i32 path_length;\n    char *args;        // what it is started with after its name: the rest of a command line\n    i32 args_length;   // at most ARGS_MAX bytes are kept\n    i32 stdout_node;   // the Terminal or TextArea it writes to; 0: wherever the caller writes\n    Out *result_out;\n};\n\n/** The longest arguments a process is started with, in bytes; more are cut. */\nexport const i32 ARGS_MAX = 127;\n\n/** PROC_ARGS: the caller's own arguments, copied to `out`; r2 is their length. */\nexport struct ProcArgsArgs {\n    char *out;\n    i32 capacity;\n};\n\nexport struct ProcExitedArgs<Out> {\n    i32 pid;\n    Out *result_out;\n};\n\nexport struct ProcReapArgs<Out> {\n    i32 pid;\n    Out *result_out;\n};\n\nexport struct ProcFeedArgs {\n    i32 pid;\n    char *line;\n    i32 line_length;\n};\n\nexport struct ProcBindArgs {\n    i32 pid;\n    i32 output_node;\n};\n\nexport struct ProcUnbindArgs {\n    i32 pid;\n};\n\n// --- PROC_STATS: what is running and what it costs ---------------------------\n// Unlike the services above it controls nothing, so any process may ask, about\n// every process. Times are timer ticks: each tick is charged to whatever it\n// interrupted, so they are samples, and only their ratios mean anything.\n\n/**\n * What a process is doing.\n * @property Starting Its program is still being loaded.\n * @property Running One of its threads is running or ready to run.\n * @property Waiting Every thread is blocked: on input, a timer, a reply.\n * @property Exiting It is being taken down.\n * @property Ended Only its exit status is left, for its parent to collect.\n */\nexport enum ProcActivity {\n    Starting,\n    Running,\n    Waiting,\n    Exiting,\n    Ended,\n}\n\n/**\n * One process.\n * @property pid The process.\n * @property parent The process that started it; zero when the OS did.\n * @property activity What it is doing.\n * @property threads Threads that have not ended.\n * @property cpu_time Time its threads have run since it started, in timer\n *           clock units (256 a tick; it wraps, so read differences).\n * @property pages 4 KiB pages its program, heap and stacks have mapped.\n * @property name Its executable's name, without directory or extension.\n */\nexport struct ProcInfo {\n    i32 pid;\n    i32 parent;\n    ProcActivity activity;\n    i32 threads;\n    i32 cpu_time;\n    i32 pages;\n    Text<16> name;\n};\n\n/**\n * Where the CPU's time went since boot, in timer clock units: 256 a tick, read\n * as the scheduler switches threads. The counts wrap, so read differences.\n * @property total All of it.\n * @property idle Time with nothing to run, or only an OS thread waiting.\n * @property kernel Time in the OS's own threads: the desktop, the filesystem,\n *           and the work they do for applications.\n * @property kernel_threads The OS's own threads.\n */\nexport struct CpuTimes {\n    i32 total;\n    i32 idle;\n    i32 kernel;\n    i32 kernel_threads;\n};\n\n/**\n * Every process, in process-table order, the CPU's time and physical memory.\n * @property cpu Where the CPU's time went.\n * @property total_pages 4 KiB pages of RAM for processes and page tables.\n * @property free_pages Those not in use.\n * @property count Entries of `procs` in use.\n * @property procs The processes: 16, one per process slot (MAX_PROCS).\n */\nexport struct ProcStats {\n    CpuTimes cpu;\n    i32 total_pages;\n    i32 free_pages;\n    i32 count;\n    ProcInfo procs[16];\n};\n\nexport struct ProcStatsArgs {\n    ProcStats *result_out;\n};\n","contracts/myos/services.contract.mln":"namespace os_services;\n\n// MyOS's hosted-program ABI. Client libraries send these service numbers\n// through OS_CALL; MyOS implements them. This file defines wire constants\n// only -- no kernel, filesystem, UI, or application policy belongs here.\n\nexport enum OsService {\n    NONE,\n    // Application request/event transport.\n    REQUEST,        // (Request*) -> 1 queued, 0 if full (retry)\n    REPLY,          // (i32 *out) -> 1 with the request result, else 0\n    POLL,           // (Event*) -> 1 with an event (inline text), else 0\n    // Filesystem. Each service is bound to its Fs*Args record by an\n    // `impl OsCall` in myos/fs-args.contract.mln; Result values are written\n    // through result_out in caller memory. FS_CLOSE is fire-and-forget.\n    FS_OPEN,        // FsOpenArgs<Out>\n    FS_CREATE,      // FsCreateArgs<Out>\n    FS_READ,        // FsReadArgs<Out>\n    FS_WRITE,       // FsWriteArgs<Out>\n    FS_SEEK,        // FsSeekArgs<Out>\n    FS_CLOSE,       // FsCloseArgs\n    FS_REMOVE,      // FsRemoveArgs<Out>\n    FS_ENTRY_SIZE,  // FsEntrySizeArgs<Out>\n    FS_MKDIR,       // FsMkdirArgs<Out>\n    FS_DIR_NEXT_AT, // FsDirNextArgs<Out>\n    FS_IS_DIR,      // FsIsDirArgs<Out>\n    // Processes. Argument pointers refer to the corresponding Proc*Args\n    // records in myos/process-args.contract.mln. Spawn's stdout_node is zero\n    // for no TextArea binding; typed results are written through result_out.\n    PROC_SPAWN,     // ProcSpawnArgs<Out>\n    PROC_BIND,      // ProcBindArgs\n    PROC_UNBIND,    // ProcUnbindArgs\n    PROC_EXITED,    // ProcExitedArgs<Out>\n    PROC_REAP,      // ProcReapArgs<Out>\n    PROC_FEED,      // ProcFeedArgs\n    PROC_STATS,     // ProcStatsArgs: every process and the CPU's time, for anyone\n    PROC_ARGS,      // ProcArgsArgs: what the caller was started with\n    // Diagnostics.\n    LOG,\n};\n\n/**\n * Binds an OS_CALL argument record to the one service that accepts it.\n *\n * Each record is followed by `impl OsCall for Record = OsService::X;`, so a\n * client sends the record's own service number and the provider accepts the\n * record only for that number. The reply type is the record's `result_out`\n * field, not a trait parameter.\n */\nexport trait OsCall {\n    OsService service();\n}\n\n/** OS_CALL LOG argument: a message as a view into caller memory. */\nexport struct LogArgs {\n    char *text;\n    i32 length;\n};\n\n// Internal OS_CALL routing failure. The kernel maps it to the common\n// SyscallStatus plus r2 payload at the user/kernel ABI boundary.\nexport enum OsServiceError {\n    UnknownService(i32),\n}\n","runtime/MyEmulator/src/machine/timer.rs":"use std::time::{Duration, Instant};\n\n// Real-time timer. Fires (returns true from `service`) once at least `period`\n// of wall-clock time has elapsed since the last fire, independent of how many\n// instructions the CPU executed. This lets the guest use WFI/halt to idle the\n// CPU without stalling the timer: real time keeps advancing and the next tick\n// still arrives to wake the scheduler.\n//\n// A purely wall-clock timer has one failure mode: if the handler takes longer\n// than a period, the next tick is already due the moment it returns, and the\n// guest never runs anything else. How much guest work fits in a period depends\n// on how fast this emulator happens to run, so the same image starves on one\n// host and not another.\n//\n// MIN_INSTRS_PER_TICK is the floor that removes that. A tick also waits for the\n// guest to retire this many instructions since the last one, so forward\n// progress is guaranteed no matter how slow the host is; a tick is delayed,\n// never denied. It costs nothing when the guest is keeping up, because a period\n// normally buys far more instructions than this.\n//\n// The floor applies only while the CPU is executing. A guest parked in WFI\n// retires nothing by definition, and the tick is what wakes it, so holding the\n// tick back there would deadlock the machine -- the very thing the wall-clock\n// timer was introduced to avoid.\n//\n// The value is set from the cost of one handler invocation with headroom: the\n// kernel's scheduler.mln budgets its tick handler at \"a few hundred\n// instructions\", and this leaves room for that plus the trampoline, the\n// dispatcher and the serial/mouse drains.\nconst MIN_INSTRS_PER_TICK: u64 = 200_000;\n\n// The guest reads the timer as a clock of CLOCK_UNITS_PER_TICK units a tick:\n// the ticks so far in the high bits, how far the current tick has got in the\n// low ones. So the 32 bits hold 2^24 ticks before they wrap, and the tick\n// count wraps with them.\npub const CLOCK_SHIFT: u32 = 8;\npub const CLOCK_UNITS_PER_TICK: u32 = 1 << CLOCK_SHIFT;\nconst TICK_MASK: u32 = u32::MAX >> CLOCK_SHIFT;\n\npub struct TimerDevice {\n    // Microseconds between ticks. None disables the timer.\n    period: Option<Duration>,\n    last_fire: Instant,\n    instrs_at_last_fire: u64,\n    // Ticks so far, whether they interrupted or were held back, modulo 2^24:\n    // the high bits of the clock read at TIMER_ADDR.\n    count: u32,\n    // From TIMER_ADDR's write: the ticks before this one pass without an\n    // interrupt, and this one raises it. None: every tick interrupts.\n    hold_until: Option<u32>,\n}\n\nimpl TimerDevice {\n    pub fn new() -> Self {\n        Self {\n            period: Some(Duration::from_micros(1000)),\n            last_fire: Instant::now(),\n            instrs_at_last_fire: 0,\n            count: 0,\n            hold_until: None,\n        }\n    }\n\n    // Set the tick period from a microsecond count (the CLI's --timer-interval).\n    pub fn set_period_micros(&mut self, micros: u64) {\n        if micros == 0 {\n            self.period = None;\n        } else {\n            self.period = Some(Duration::from_micros(micros));\n        }\n        self.last_fire = Instant::now();\n    }\n\n    // The configured tick period, or None when the timer is disabled.\n    pub fn period(&self) -> Option<Duration> {\n        self.period\n    }\n\n    // Fire if a full period has elapsed. Still delivers at most one tick per\n    // call, but advances last_fire by exactly one period rather than resetting\n    // it to `now`: late servicing (batch granularity, a long-running handler)\n    // then yields catch-up ticks on subsequent calls instead of silently\n    // stretching every period, so the average rate stays wall-clock accurate\n    // and guest tick counts don't drift. If we fall hopelessly behind (host\n    // suspend, debugger pause), resync to `now` so the guest doesn't receive a\n    // burst of stale ticks.\n    pub fn service(&mut self, instrs_retired: u64, cpu_idle: bool) -> bool {\n        if let Some(period) = self.period {\n            let now = Instant::now();\n            if now.duration_since(self.last_fire) >= period {\n                if let Some(until) = self.hold_until {\n                    return self.service_held(until, period, now, instrs_retired);\n                }\n                // Hold the tick back until the guest has actually run. Without\n                // this a handler that outlasts its period starves everything\n                // else; see MIN_INSTRS_PER_TICK.\n                if !cpu_idle\n                    && instrs_retired.saturating_sub(self.instrs_at_last_fire) < MIN_INSTRS_PER_TICK\n                {\n                    return false;\n                }\n                self.last_fire += period;\n                if now.duration_since(self.last_fire) > period * 32 {\n                    self.last_fire = now;\n                }\n                self.instrs_at_last_fire = instrs_retired;\n                self.count = self.count.wrapping_add(1) & TICK_MASK;\n                return true;\n            }\n        }\n        false\n    }\n\n    // While held, no interrupt is due before the wake tick, so the periods\n    // that passed are counted together rather than one per call. A gap of\n    // more than 32 periods means the emulator itself stood still (a debugger\n    // pause, a control-stdio client between requests); as in the periodic\n    // resync, it counts as a single tick. The wake tick interrupts even if\n    // the guest has not run its MIN_INSTRS_PER_TICK: one interrupt cannot\n    // starve it.\n    fn service_held(\n        &mut self,\n        until: u32,\n        period: Duration,\n        now: Instant,\n        instrs_retired: u64,\n    ) -> bool {\n        let passed = now.duration_since(self.last_fire).as_nanos() / period.as_nanos();\n        let stood_still = passed > 32;\n        let passed = if stood_still { 1 } else { passed as u32 };\n        let ticks = passed.min(until.wrapping_sub(self.count) & TICK_MASK);\n        self.count = self.count.wrapping_add(ticks) & TICK_MASK;\n        if stood_still {\n            self.last_fire = now;\n        } else {\n            self.last_fire += period * ticks;\n        }\n        if self.count != until {\n            return false;\n        }\n        self.hold_until = None;\n        self.instrs_at_last_fire = instrs_retired;\n        true\n    }\n\n    // TIMER_ADDR read: the clock, the ticks so far and how far the current\n    // tick has got, CLOCK_UNITS_PER_TICK units a tick. A tick that is due but\n    // not yet counted (the instruction floor, a service still to come) holds\n    // the clock at the last unit before it, so it never runs backwards.\n    pub fn clock(&self) -> u32 {\n        let within = self.period.map_or(0, |period| {\n            let elapsed = Instant::now().duration_since(self.last_fire);\n            let units = elapsed.as_nanos() * u128::from(CLOCK_UNITS_PER_TICK) / period.as_nanos();\n            units.min(u128::from(CLOCK_UNITS_PER_TICK - 1)) as u32\n        });\n        (self.count << CLOCK_SHIFT) | within\n    }\n\n    // TIMER_ADDR write: interrupt next at the first tick at or after clock\n    // `at`. 0, or a time no later than the next tick, interrupts at every\n    // tick. The tick is compared within the clock's 2^24, so a hold reaches\n    // at most 2^23 ticks ahead.\n    pub fn hold(&mut self, at: u32) {\n        let until = ((u64::from(at) + u64::from(CLOCK_UNITS_PER_TICK - 1)) >> CLOCK_SHIFT) as u32\n            & TICK_MASK;\n        let ahead = until.wrapping_sub(self.count) & TICK_MASK;\n        self.hold_until = if at != 0 && ahead > 1 && ahead <= TICK_MASK >> 1 {\n            Some(until)\n        } else {\n            None\n        };\n    }\n\n    // How long until the next tick is due, or None when the timer is disabled.\n    // Used to sleep the host thread while the guest is idle (WFI) instead of\n    // busy-spinning.\n    pub fn time_until_next(&self) -> Option<Duration> {\n        self.period.map(|period| {\n            let ticks = self.hold_until.map_or(1, |until| {\n                (until.wrapping_sub(self.count) & TICK_MASK).max(1)\n            });\n            let elapsed = self.last_fire.elapsed();\n            (period * ticks)\n                .checked_sub(elapsed)\n                .unwrap_or(Duration::ZERO)\n        })\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::{CLOCK_SHIFT, CLOCK_UNITS_PER_TICK, MIN_INSTRS_PER_TICK, TICK_MASK, TimerDevice};\n    use std::time::Duration;\n\n    // The ticks the clock shows.\n    fn ticks(t: &TimerDevice) -> u32 {\n        t.clock() >> CLOCK_SHIFT\n    }\n\n    // The clock at the start of tick `n`.\n    fn at(n: u32) -> u32 {\n        n << CLOCK_SHIFT\n    }\n\n    // Enough retired instructions that the floor never gets in the way; each\n    // call advances the count by another whole quota.\n    fn plenty(n: u64) -> u64 {\n        n * MIN_INSTRS_PER_TICK\n    }\n\n    #[test]\n    fn late_service_catches_up_instead_of_stretching_the_period() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(10_000); // 10 ms\n        std::thread::sleep(Duration::from_millis(25));\n        assert!(t.service(plenty(1), false), \"first tick after a late poll\");\n        assert!(\n            t.service(plenty(2), false),\n            \"the missed tick is delivered as an immediate catch-up tick\"\n        );\n    }\n\n    // A guest in WFI retires nothing; the tick has to fire anyway or it never\n    // wakes up.\n    #[test]\n    fn an_idle_cpu_is_exempt_from_the_floor() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        std::thread::sleep(Duration::from_millis(5));\n        assert!(t.service(0, true), \"idle CPU still gets its tick\");\n    }\n\n    #[test]\n    fn disabled_timer_never_fires() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(0);\n        assert!(!t.service(plenty(1), false));\n        assert!(t.time_until_next().is_none());\n    }\n\n    // The floor is what stops a handler that outlasts its period from starving\n    // the guest: the period alone is not enough to fire.\n    #[test]\n    fn every_tick_counts() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        std::thread::sleep(Duration::from_millis(3));\n        assert!(t.service(plenty(1), false));\n        assert_eq!(ticks(&t), 1, \"a tick that interrupts counts\");\n    }\n\n    // A held timer counts the ticks before the wake tick without\n    // interrupting, all at once, and interrupts at the wake tick.\n    #[test]\n    fn held_ticks_count_without_interrupting_until_the_wake_tick() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.hold(at(ticks(&t) + 1_000));\n        std::thread::sleep(Duration::from_millis(4));\n        assert!(!t.service(0, true), \"no interrupt before the wake tick\");\n        let counted = ticks(&t);\n        assert!(\n            counted >= 3,\n            \"the ticks that passed are counted at once: {counted}\"\n        );\n        let wake = counted + 3;\n        t.hold(at(wake));\n        std::thread::sleep(Duration::from_millis(5));\n        assert!(t.service(0, true), \"the wake tick interrupts\");\n        assert_eq!(ticks(&t), wake, \"and is the tick written\");\n        std::thread::sleep(Duration::from_millis(2));\n        assert!(t.service(0, true), \"every tick interrupts after it\");\n        assert_eq!(ticks(&t), wake + 1);\n    }\n\n    #[test]\n    fn writing_zero_or_the_next_tick_interrupts_at_every_tick() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.hold(at(ticks(&t) + 50));\n        t.hold(0);\n        std::thread::sleep(Duration::from_millis(2));\n        assert!(t.service(0, true), \"0 cancels the hold\");\n        t.hold(at(ticks(&t) + 1));\n        std::thread::sleep(Duration::from_millis(2));\n        assert!(t.service(0, true), \"the next tick is every tick anyway\");\n    }\n\n    // A long gap between services means the emulator stood still; like the\n    // periodic resync, it is one tick, not a jump in the guest's clock.\n    #[test]\n    fn a_held_timer_counts_a_standstill_as_one_tick() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.hold(at(ticks(&t) + 1_000));\n        std::thread::sleep(Duration::from_millis(40));\n        assert!(!t.service(0, true));\n        assert_eq!(ticks(&t), 1);\n    }\n\n    #[test]\n    fn a_held_timer_sleeps_until_its_wake_tick() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.hold(at(ticks(&t) + 20));\n        let wait = t.time_until_next().unwrap();\n        assert!(\n            wait > Duration::from_millis(15),\n            \"the host may sleep past the held ticks: {wait:?}\"\n        );\n    }\n\n    // The clock shows how far the current tick has got, and never runs\n    // backwards: not while a due tick waits to be counted, nor when it is.\n    #[test]\n    fn the_clock_shows_a_tick_in_progress() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(10_000); // 10 ms\n        std::thread::sleep(Duration::from_millis(5));\n        let half = t.clock();\n        assert_eq!(half >> CLOCK_SHIFT, 0, \"still the first tick\");\n        assert!(\n            (64..CLOCK_UNITS_PER_TICK).contains(&half),\n            \"about half of it has gone: {half}\"\n        );\n        std::thread::sleep(Duration::from_millis(10));\n        let due = t.clock();\n        assert_eq!(\n            due,\n            CLOCK_UNITS_PER_TICK - 1,\n            \"a due tick holds the clock at its last unit\"\n        );\n        assert!(t.service(plenty(1), false));\n        assert!(\n            t.clock() >= due,\n            \"counting it moves the clock on: {}\",\n            t.clock()\n        );\n        assert_eq!(ticks(&t), 1);\n    }\n\n    // The ticks wrap at 2^24 with the clock, and a hold across the wrap still\n    // wakes at its tick.\n    #[test]\n    fn a_hold_across_the_wrap_wakes_at_its_tick() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.count = TICK_MASK - 1;\n        t.hold(at(TICK_MASK - 1).wrapping_add(at(10)));\n        std::thread::sleep(Duration::from_millis(3));\n        assert!(!t.service(0, true), \"short of the wake tick\");\n        std::thread::sleep(Duration::from_millis(12));\n        assert!(t.service(0, true), \"the wake tick, past the wrap\");\n        assert_eq!(ticks(&t), 8, \"TICK_MASK - 1 + 10 wraps to 8\");\n    }\n\n    // A wake time too far ahead to tell from one in the past is no hold.\n    #[test]\n    fn a_hold_more_than_half_the_clock_ahead_is_ignored() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000);\n        t.hold(at(TICK_MASK / 2 + 10));\n        std::thread::sleep(Duration::from_millis(2));\n        assert!(t.service(0, true), \"every tick interrupts\");\n    }\n\n    #[test]\n    fn a_tick_waits_for_the_guest_to_make_progress() {\n        let mut t = TimerDevice::new();\n        t.set_period_micros(1_000); // 1 ms\n        std::thread::sleep(Duration::from_millis(5));\n        assert!(\n            !t.service(MIN_INSTRS_PER_TICK - 1, false),\n            \"period elapsed, but the guest has not run its quota yet\"\n        );\n        assert!(\n            t.service(MIN_INSTRS_PER_TICK, false),\n            \"fires once the quota is met\"\n        );\n    }\n}\n","system/MyAppFramework/src/elements.mln":"namespace elements;\n\nimport runtime from \"runtime/runtime.mln\";\nimport { UiOp } from \"@contracts/myapp/ui.contract.mln\";\nimport { Request, EventKind } from \"@contracts/myapp/message.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport { NodeId, UiError } from \"@contracts/ui/widget.contract.mln\";\nimport ui from \"ui.mln\";\nimport { TextField, Screen } from \"ui.mln\";\nimport { Text } from \"@std/text/text.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport str from \"@std/text/str.mln\";\n\n// NodeStyle bits the elements set themselves (contracts' ADD_STYLE).\nconst i32 WRAP = 256;\nconst i32 REPORT_CARET = 512;\n\n// The markup vocabulary. `<Window title=\"A\" x={0} w={400}>...<\/Window>` in a\n// .dom.mln source lowers to a call of the function of the same name, with\n// each property handed to the parameter of the same name and children passed\n// to append_child. The vocabulary therefore lives here rather than in the\n// compiler: adding an element means adding a function, and its parameters\n// are its properties.\n//\n// A parameter with a default is an optional property, and the defaults are\n// these -- position defaults to the parent's origin (what a child of a\n// Column or Row wants, since the container places it), sizes to something\n// sensible, handlers to none. `testId` names the node for automation.\n//\n// Each element is one CREATE_* request of the UI contract, answered by the UI server\n// (system/MyOS/src/ui/protocol_elements.mln) with the new node's id. Handler\n// parameters (on*) never leave the app: they go into the runtime's handler\n// table against that id, and the server's CLICK / CHANGE / ACTIVATE / TIMER\n// events come back to them with the value the parameter's type says, and never\n// the node's id. Since apps run as processes, the request becomes a syscall and\n// no markup changes.\n\n// Children of an element are attached with the `append_child` in scope.\nResult<NodeId, UiError> create(Request request) {\n    Result<NodeId, UiError> result = Err(UiError::UnknownOperation(request.op));\n    runtime.ask_node(&request, &result);\n    return result;\n}\n\nvoid register_handler(Result<NodeId, UiError> result, EventKind kind, fn(i32 owner) -> void callback) {\n    case result of {\n        Ok(id) -> ({ runtime.on_event((i32)id, kind, callback); });\n        Err(_) -> _;\n    };\n}\n\n// Compiler hooks used only by `.dom.mln` lowering. Programmatic callers keep\n// the Result-returning APIs above/below; markup chooses the framework's\n// fail-the-instance policy for a tree that could not be constructed.\nexport NodeId unwrap_node(Result<NodeId, UiError> result) {\n    return case result of {\n        Ok(id) -> id;\n        Err(e) -> ({ runtime.fail_ui(e); (NodeId)0; });\n    };\n}\n\nexport void unwrap_append(Result<_, UiError> result) {\n    case result of {\n        Ok(_) -> _;\n        Err(e) -> ({ runtime.fail_ui(e); });\n    };\n}\n\nexport Result<_, UiError> append_child(NodeId parent, NodeId child) {\n    Request request = runtime.ui_request(UiOp::APPEND_CHILD);\n    request.a0 = (i32)parent;\n    request.a1 = (i32)child;\n    return case create(request) of {\n        Ok(ignored) -> Ok(_);\n        Err(e) -> Err(e);\n    };\n}\n\n/**\n * Lowers JSX `<Window title=\"...\" w={...} h={...} testId=\"...\" />`. The shell\n * decides where it goes.\n * @param title Window title text.\n * @param w Logical width (default 400).\n * @param h Logical height (default 300).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Window(str title, i32 w = 400, i32 h = 300, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_WINDOW);\n    request.a2 = w; request.a3 = h;\n    runtime.put_s0(&request, title); runtime.put_s1(&request, testId);\n    return create(request);\n}\n\n/**\n * Lowers JSX `<Button text=\"...\" x={...} y={...} w={...} h={...} onClick={...} testId=\"...\" />`.\n * @param text Button label text.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 90).\n * @param h Logical height (default 34).\n * @param onClick Click handler function pointer (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Button(str text, i32 x = 0, i32 y = 0, i32 w = 90, i32 h = 34, fn(i32 owner) -> void onClick = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_BUTTON);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    runtime.put_s0(&request, text); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    register_handler(result, EventKind::CLICK, onClick);\n    return result;\n}\n\n/**\n * Lowers JSX `<PrimaryButton text=\"...\" x={...} y={...} w={...} h={...} onClick={...} testId=\"...\" />`.\n * Accent-coloured call to action.\n * @param text Button label text.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 90).\n * @param h Logical height (default 34).\n * @param onClick Click handler function pointer (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> PrimaryButton(str text, i32 x = 0, i32 y = 0, i32 w = 90, i32 h = 34, fn(i32 owner) -> void onClick = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_PRIMARY_BUTTON);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    runtime.put_s0(&request, text); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    register_handler(result, EventKind::CLICK, onClick);\n    return result;\n}\n\n/**\n * Lowers JSX `<Text text=\"...\" x={...} y={...} testId=\"...\" />`.\n * @param text Text content string.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Text(str text, i32 x = 0, i32 y = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_TEXT);\n    request.a0 = x; request.a1 = y;\n    runtime.put_s0(&request, text); runtime.put_s1(&request, testId);\n    return create(request);\n}\n\n/**\n * Lowers JSX `<Label text=\"...\" x={...} y={...} color={...} bold={...} testId=\"...\" />`.\n * Text with an explicit colour (graphics.rgb(); 0 = theme default) and weight.\n * @param text Label text string.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param color Text color (RGB, 0 for default).\n * @param bold Non-zero for bold styling.\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Label(str text, i32 x = 0, i32 y = 0, i32 color = 0, i32 bold = 0, i32 anchor = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_LABEL);\n    request.a0 = x; request.a1 = y; request.a2 = color; request.a3 = bold;\n    runtime.put_s0(&request, text); runtime.put_s1(&request, testId);\n    return anchored(create(request), anchor);\n}\n\n// A created node, given the NodeStyle bits of how it follows its window's size.\nResult<NodeId, UiError> anchored(Result<NodeId, UiError> created, i32 anchor) {\n    case created of {\n        Ok(id) -> runtime.add_style(id, anchor);\n        Err(_) -> _;\n    };\n    return created;\n}\n\n/**\n * Lowers JSX `<Box x={...} y={...} w={...} h={...} background={...} border={...} />`.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 100).\n * @param h Logical height (default 100).\n * @param background Background color (RGB, default 0).\n * @param border Border color (RGB, default 0).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Box(i32 x = 0, i32 y = 0, i32 w = 100, i32 h = 100,\n               i32 background = 0, i32 border = 0, i32 anchor = 0) {\n    Request request = runtime.ui_request(UiOp::CREATE_BOX);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    request.a4 = background; request.a5 = border;\n    return anchored(create(request), anchor);\n}\n\n/**\n * Lowers JSX `<Panel x={...} y={...} w={...} h={...} radius={...} />`.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 100).\n * @param h Logical height (default 100).\n * @param radius Corner radius in logical pixels (default 0).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Panel(i32 x = 0, i32 y = 0, i32 w = 100, i32 h = 100, i32 radius = 0) {\n    Request request = runtime.ui_request(UiOp::CREATE_PANEL);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h; request.a4 = radius;\n    return create(request);\n}\n\n/**\n * Lowers JSX `<Column x={...} y={...} w={...} h={...} padding={...} gap={...} />`.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 100).\n * @param h Logical height (default 100).\n * @param padding Inset padding in logical pixels (default 0).\n * @param gap Gap between children in logical pixels (default 0).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Column(i32 x = 0, i32 y = 0, i32 w = 100, i32 h = 100,\n                  i32 padding = 0, i32 gap = 0, i32 anchor = 0) {\n    Request request = runtime.ui_request(UiOp::CREATE_COLUMN);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    request.a4 = padding; request.a5 = gap;\n    return anchored(create(request), anchor);\n}\n\n/**\n * Lowers JSX `<Row x={...} y={...} w={...} h={...} padding={...} gap={...} />`.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 100).\n * @param h Logical height (default 34).\n * @param padding Inset padding in logical pixels (default 0).\n * @param gap Gap between children in logical pixels (default 0).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Row(i32 x = 0, i32 y = 0, i32 w = 100, i32 h = 34,\n               i32 padding = 0, i32 gap = 0, i32 anchor = 0) {\n    Request request = runtime.ui_request(UiOp::CREATE_ROW);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    request.a4 = padding; request.a5 = gap;\n    return anchored(create(request), anchor);\n}\n\n/**\n * Lowers JSX `<TextInput placeholder=\"...\" field={...} x={...} y={...} w={...} h={...} capacity={...} focus={...} onChange={...} testId=\"...\" />`.\n * @param placeholder Placeholder text string.\n * @param field The part that reads and writes the text (default none).\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 200).\n * @param h Logical height (default 34).\n * @param capacity Buffer capacity in bytes (default 64).\n * @param focus Whether the keyboard starts here (default false).\n * @param onChange Called with the text when the user changes it (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> TextInput(str placeholder, TextField field = 0, i32 x = 0, i32 y = 0, i32 w = 200, i32 h = 34, i32 capacity = 64, bool focus = false, fn(i32 owner, str text) -> void onChange = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_TEXT_INPUT);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h; request.a4 = capacity;\n    runtime.put_s0(&request, placeholder); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            runtime.attach((i32)field, id);\n            runtime.on_text((i32)id, EventKind::CHANGE, onChange);\n            if (focus) { runtime.focus(id); }\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Checkbox text=\"...\" x={...} y={...} checked={...} onChange={...} testId=\"...\" />`.\n * @param text Checkbox label text.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param checked Checked state (default false).\n * @param onChange Called with the new state when the user toggles it (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Checkbox(str text, i32 x = 0, i32 y = 0, bool checked = false, fn(i32 owner, bool on) -> void onChange = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_CHECKBOX);\n    request.a0 = x; request.a1 = y; request.a2 = checked ? 1 : 0;\n    runtime.put_s0(&request, text); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({ runtime.on_flag((i32)id, EventKind::CHANGE, onChange); });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Separator x={...} y={...} w={...} />`.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 100).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Separator(i32 x = 0, i32 y = 0, i32 w = 100) {\n    Request request = runtime.ui_request(UiOp::CREATE_SEPARATOR);\n    request.a0 = x; request.a1 = y; request.a2 = w;\n    return create(request);\n}\n\n/**\n * Lowers JSX `<Timer interval={...} onTick={...} />`.\n * @param interval Timer tick interval in system ticks.\n * @param onTick Timer callback function pointer.\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Timer(i32 interval, fn(i32 owner) -> void onTick) {\n    Request request = runtime.ui_request(UiOp::CREATE_TIMER);\n    request.a0 = interval;\n    Result<NodeId, UiError> result = create(request);\n    register_handler(result, EventKind::TIMER, onTick);\n    return result;\n}\n\n/**\n * Lowers JSX `<TextArea name=\"...\" field={...} text=\"...\" x={...} y={...} w={...} h={...} capacity={...} readonly={...} onChange={...} testId=\"...\" />`.\n * @param name Node name identifier.\n * @param field The part that reads, writes and adds to the text (default none).\n * @param text The text it starts with (default none).\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 300).\n * @param h Logical height (default 200).\n * @param capacity Buffer capacity in bytes (default 1024).\n * @param readonly Non-zero for read-only / display console mode (default 0).\n * @param wrap Whether long lines break to fit its width (default false).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @param onChange Called with the text when the user changes it (default none).\n * @param onEdit Called when the user changes the text, without it: cheaper for a long text (default none).\n * @param onCaret Called with the caret's line and column, from 1, when it moves (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> TextArea(str name, TextField field = 0, str text = \"\", i32 x = 0, i32 y = 0, i32 w = 300, i32 h = 200, i32 capacity = 1024, i32 readonly = 0, bool wrap = false, i32 anchor = 0, fn(i32 owner, str text) -> void onChange = 0, fn(i32 owner) -> void onEdit = 0, fn(i32 owner, i32 line, i32 column) -> void onCaret = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_TEXT_AREA);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    request.a4 = capacity; request.a5 = readonly;\n    runtime.put_s0(&request, name); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            runtime.attach((i32)field, id);\n            if (!text.is_empty()) { runtime.area_append(id, text); }\n            i32 style = anchor;\n            if (wrap) { style = style | WRAP; }\n            if (onCaret != 0) { style = style | REPORT_CARET; }\n            runtime.add_style(id, style);\n            runtime.on_text((i32)id, EventKind::CHANGE, onChange);\n            runtime.on_event((i32)id, EventKind::CHANGE, onEdit);\n            runtime.on_caret((i32)id, onCaret);\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Terminal screen={...} x={...} y={...} w={...} h={...} capacity={...} focus={...} testId=\"...\" />`.\n * A grid of fixed-width cells: the processes started on its screen write to\n * it, and a line typed on it goes to the one started last\n * (`terminal.spawn_bound`).\n * @param screen The part processes are started on (default none).\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 560).\n * @param h Logical height (default 360).\n * @param capacity Bytes of text it keeps; the oldest lines go first (default 8192).\n * @param focus Whether the keyboard starts here (default false).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Terminal(Screen screen = 0, i32 x = 0, i32 y = 0, i32 w = 560, i32 h = 360, i32 capacity = 8192, bool focus = false, i32 anchor = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_TERMINAL);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h; request.a4 = capacity;\n    runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            runtime.attach((i32)screen, id);\n            runtime.add_style(id, anchor);\n            if (focus) { runtime.focus(id); }\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Menu title=\"...\" items=\"...\" x={...} y={...} w={...} h={...} onSelect={...} testId=\"...\" />`.\n * A button in a window's menu bar that opens a menu of its items below it.\n * Picking one calls onSelect with its index. An item's tabs line shortcuts up\n * in a column, as in a List.\n * @param title The button's text.\n * @param items The items, joined by newlines.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 60).\n * @param h Logical height (default 26).\n * @param onSelect Called with the index of the item picked (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Menu(str title, str items = \"\", i32 x = 0, i32 y = 0, i32 w = 60, i32 h = 26, fn(i32 owner, i32 index) -> void onSelect = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_MENU_BUTTON);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h;\n    runtime.put_s0(&request, title); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            send_items(id, items);\n            runtime.on_row((i32)id, EventKind::CHANGE, onSelect);\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<List name=\"...\" items={...} selected={...} x={...} y={...} w={...} h={...} capacity={...} focus={...} onChange={...} onActivate={...} testId=\"...\" />`.\n * onChange fires when the user selects a row, onActivate when a row is clicked\n * again or Enter is pressed.\n * @param name Node name identifier.\n * @param items The rows, joined by newlines (default none).\n * @param selected The selected row (default none).\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 300).\n * @param h Logical height (default 200).\n * @param capacity Buffer capacity in bytes (default 1024).\n * @param focus Whether the keyboard starts here (default false).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @param onChange Called with the row the user selected (default none).\n * @param onActivate Called with the row the user activated (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> List(str name, str items = \"\", Option<i32> selected = None, i32 x = 0, i32 y = 0, i32 w = 300, i32 h = 200, i32 capacity = 1024, bool focus = false, i32 anchor = 0, fn(i32 owner, i32 row) -> void onChange = 0, fn(i32 owner, i32 row) -> void onActivate = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_LIST);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h; request.a4 = capacity;\n    runtime.put_s0(&request, name); runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            runtime.add_style(id, anchor);\n            runtime.on_row((i32)id, EventKind::CHANGE, onChange);\n            runtime.on_row((i32)id, EventKind::ACTIVATE, onActivate);\n            if (!items.is_empty()) { send_items(id, items); }\n            case selected of {\n                Some(row) -> ({ send_selected(id, row); });\n                None -> _;\n            };\n            if (focus) { runtime.focus(id); }\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Graph fill={...} line={...} samples={60} />`.\n * Percentages over time, newest at the right: `fill` is drawn filled under an\n * accent line, `line` as a second line over it. Each is decimal numbers from\n * 0 to 100 apart by spaces, oldest first; past `samples` the oldest drop off.\n * @param x Logical X coordinate (default 0).\n * @param y Logical Y coordinate (default 0).\n * @param w Logical width (default 300).\n * @param h Logical height (default 120).\n * @param samples How many samples span the width, 2 to 120 (default 60).\n * @param fill The filled series (default none).\n * @param line The second series (default none).\n * @param anchor How it follows the window's size: ui.GROW_W, ui.GROW_H, ui.PIN_BOTTOM (default none).\n * @param testId Stable automation locator id (default none).\n * @return DOM Node ID.\n */\nexport Result<NodeId, UiError> Graph(i32 x = 0, i32 y = 0, i32 w = 300, i32 h = 120, i32 samples = 60, str fill = \"\", str line = \"\", i32 anchor = 0, str testId = \"\") {\n    Request request = runtime.ui_request(UiOp::CREATE_GRAPH);\n    request.a0 = x; request.a1 = y; request.a2 = w; request.a3 = h; request.a4 = samples;\n    runtime.put_s1(&request, testId);\n    Result<NodeId, UiError> result = create(request);\n    case result of {\n        Ok(id) -> ({\n            runtime.add_style(id, anchor);\n            if (!fill.is_empty()) { send_series(id, 0, fill); }\n            if (!line.is_empty()) { send_series(id, 1, line); }\n        });\n        Err(_) -> _;\n    };\n    return result;\n}\n\n/**\n * Lowers JSX `<Dialog when={...} title=\"...\" text=\"...\" confirm=\"...\" cancel=\"...\" other=\"...\" w={...} h={...} onConfirm={...} onCancel={...} onOther={...}>...<\/Dialog>`.\n * A question in a window of its own, up while `when` is true. A handler ends\n * it by changing that state. Closing its window, or Esc, is cancelling, and\n * Enter is confirming. Elements inside it go in its window, between the\n * question at the top and the buttons along the bottom.\n * @param when Whether the dialog is up.\n * @param title Window title text.\n * @param text The question.\n * @param confirm Label of the button that answers yes (default \"OK\").\n * @param cancel Label of the button that answers no (default \"Cancel\").\n * @param other Label of a third answer between them, say \"Don't Save\" (default none).\n * @param w Logical width (default 340).\n * @param h Logical height, title bar included (default 140).\n * @param onConfirm Called when the user answers yes (default none).\n * @param onCancel Called when the user answers no (default none).\n * @param onOther Called when the user gives the third answer (default none).\n * @return DOM Node ID of its window.\n */\nexport Result<NodeId, UiError> Dialog(bool when, str title, str text, str confirm = \"OK\", str cancel = \"Cancel\", str other = \"\", i32 w = 340, i32 h = 140, fn(i32 owner) -> void onConfirm = 0, fn(i32 owner) -> void onCancel = 0, fn(i32 owner) -> void onOther = 0) {\n    NodeId window = Window(title, w, h, \"\")?;\n    NodeId label = Label(text, 20, 16, 0, 0, 0, \"\")?;\n    append_child(window, label)?;\n    // The buttons sit along the bottom: the window's h includes its title bar.\n    NodeId row = Row(20, h - 80, w - 40, 34, 0, 10)?;\n    append_child(window, row)?;\n    NodeId yes = PrimaryButton(confirm, 0, 0, 100, 34, 0, \"\")?;\n    append_child(row, yes)?;\n    if (!other.is_empty()) {\n        NodeId third = Button(other, 0, 0, 100, 34, 0, \"\")?;\n        append_child(row, third)?;\n        runtime.on_event((i32)third, EventKind::CLICK, onOther);\n    }\n    NodeId no = Button(cancel, 0, 0, 100, 34, 0, \"\")?;\n    append_child(row, no)?;\n    runtime.on_event((i32)yes, EventKind::CLICK, onConfirm);\n    runtime.on_event((i32)no, EventKind::CLICK, onCancel);\n    runtime.on_event((i32)window, EventKind::CLOSE, onCancel);\n    runtime.add_dialog(window, label);\n    return Ok(window);\n}\n\n// `.dom.mln` adapters. JSX has an atomic tree-construction policy: it invokes\n// the same typed functions above, but a failed node aborts the application\n// instead of leaving a partial tree. These adapters preserve UiError all the\n// way to that terminal policy; they do not translate it to a sentinel.\nexport void dom_append_child(NodeId parent, NodeId child) {\n    if (runtime.is_dialog(child)) { return; }\n    unwrap_append(append_child(parent, child));\n}\nexport NodeId dom_Window(str title, i32 w, i32 h, str testId) { return unwrap_node(Window(title, w, h, testId)); }\nexport NodeId dom_Button(str text, i32 x, i32 y, i32 w, i32 h, fn(i32 owner) -> void onClick, str testId) { return unwrap_node(Button(text, x, y, w, h, onClick, testId)); }\nexport NodeId dom_PrimaryButton(str text, i32 x, i32 y, i32 w, i32 h, fn(i32 owner) -> void onClick, str testId) { return unwrap_node(PrimaryButton(text, x, y, w, h, onClick, testId)); }\nexport NodeId dom_Text(str text, i32 x, i32 y, str testId) { return unwrap_node(Text(text, x, y, testId)); }\nexport NodeId dom_Label(str text, i32 x, i32 y, i32 color, i32 bold, i32 anchor, str testId) { return unwrap_node(Label(text, x, y, color, bold, anchor, testId)); }\nexport NodeId dom_Box(i32 x, i32 y, i32 w, i32 h, i32 background, i32 border, i32 anchor) { return unwrap_node(Box(x, y, w, h, background, border, anchor)); }\nexport NodeId dom_Panel(i32 x, i32 y, i32 w, i32 h, i32 radius) { return unwrap_node(Panel(x, y, w, h, radius)); }\nexport NodeId dom_Column(i32 x, i32 y, i32 w, i32 h, i32 padding, i32 gap, i32 anchor) { return unwrap_node(Column(x, y, w, h, padding, gap, anchor)); }\nexport NodeId dom_Row(i32 x, i32 y, i32 w, i32 h, i32 padding, i32 gap, i32 anchor) { return unwrap_node(Row(x, y, w, h, padding, gap, anchor)); }\nexport NodeId dom_TextInput(str placeholder, TextField field, i32 x, i32 y, i32 w, i32 h, i32 capacity, bool focus, fn(i32 owner, str text) -> void onChange, str testId) { return unwrap_node(TextInput(placeholder, field, x, y, w, h, capacity, focus, onChange, testId)); }\nexport NodeId dom_Checkbox(str text, i32 x, i32 y, bool checked, fn(i32 owner, bool on) -> void onChange, str testId) { return unwrap_node(Checkbox(text, x, y, checked, onChange, testId)); }\nexport NodeId dom_Separator(i32 x, i32 y, i32 w) { return unwrap_node(Separator(x, y, w)); }\nexport NodeId dom_Timer(i32 interval, fn(i32 owner) -> void onTick) { return unwrap_node(Timer(interval, onTick)); }\nexport NodeId dom_TextArea(str name, TextField field, str text, i32 x, i32 y, i32 w, i32 h, i32 capacity, i32 readonly, bool wrap, i32 anchor, fn(i32 owner, str text) -> void onChange, fn(i32 owner) -> void onEdit, fn(i32 owner, i32 line, i32 column) -> void onCaret, str testId) { return unwrap_node(TextArea(name, field, text, x, y, w, h, capacity, readonly, wrap, anchor, onChange, onEdit, onCaret, testId)); }\nexport NodeId dom_Terminal(Screen screen, i32 x, i32 y, i32 w, i32 h, i32 capacity, bool focus, i32 anchor, str testId) { return unwrap_node(Terminal(screen, x, y, w, h, capacity, focus, anchor, testId)); }\nexport NodeId dom_Menu(str title, str items, i32 x, i32 y, i32 w, i32 h, fn(i32 owner, i32 index) -> void onSelect, str testId) { return unwrap_node(Menu(title, items, x, y, w, h, onSelect, testId)); }\nexport NodeId dom_List(str name, str items, Option<i32> selected, i32 x, i32 y, i32 w, i32 h, i32 capacity, bool focus, i32 anchor, fn(i32 owner, i32 row) -> void onChange, fn(i32 owner, i32 row) -> void onActivate, str testId) { return unwrap_node(List(name, items, selected, x, y, w, h, capacity, focus, anchor, onChange, onActivate, testId)); }\nexport NodeId dom_Graph(i32 x, i32 y, i32 w, i32 h, i32 samples, str fill, str line, i32 anchor, str testId) { return unwrap_node(Graph(x, y, w, h, samples, fill, line, anchor, testId)); }\nexport NodeId dom_Dialog(bool when, str title, str text, str confirm, str cancel, str other, i32 w, i32 h, fn(i32 owner) -> void onConfirm, fn(i32 owner) -> void onCancel, fn(i32 owner) -> void onOther) { return unwrap_node(Dialog(when, title, text, confirm, cancel, other, w, h, onConfirm, onCancel, onOther)); }\n\n// --- what follows the state ------------------------------------------------------------\n\n// `.dom.mln` lowering calls these. A property of `view` that reads the state is\n// recorded with bind, and its hook, `<Tag>_<property>`, is called with the\n// value after every event. A hook sends only what changed.\n\nexport void bind(i32 slot, NodeId node) { runtime.bind(slot, (i32)node); }\n\nvoid send_text(NodeId id, str value) {\n    Request request = runtime.ui_request(UiOp::SET_TEXT);\n    request.a0 = (i32)id;\n    runtime.put_s0(&request, value);\n    runtime.send(&request);\n}\n\nexport void Window_title(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_text(runtime.bound(slot), value); }\n}\n\nexport void Label_text(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_text(runtime.bound(slot), value); }\n}\n\nvoid send_items(NodeId id, str items) {\n    Request request = runtime.ui_request(UiOp::LIST_SET_ITEMS);\n    request.a0 = (i32)id;\n    runtime.put_s0(&request, items);\n    runtime.send(&request);\n}\n\nvoid send_selected(NodeId id, i32 row) {\n    Request request = runtime.ui_request(UiOp::LIST_SELECT);\n    request.a0 = (i32)id;\n    request.a1 = row;\n    runtime.send(&request);\n}\n\nexport void List_items(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_items(runtime.bound(slot), value); }\n}\n\nexport void List_selected(i32 slot, Option<i32> value) {\n    i32 row = case value of { Some(selected) -> selected; None -> -1; };\n    if (runtime.word_changed(slot, row)) { send_selected(runtime.bound(slot), row); }\n}\n\nvoid send_series(NodeId id, i32 series, str values) {\n    Request request = runtime.ui_request(UiOp::GRAPH_SET);\n    request.a0 = (i32)id;\n    request.a1 = series;\n    runtime.put_s0(&request, values);\n    runtime.send(&request);\n}\n\nexport void Graph_fill(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_series(runtime.bound(slot), 0, value); }\n}\n\nexport void Graph_line(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_series(runtime.bound(slot), 1, value); }\n}\n\n// A dialog starts off the desktop whatever `when` says, so its first pass counts.\nexport void Dialog_when(i32 slot, bool value) {\n    if (runtime.word_differs(slot, value ? 1 : 0)) { runtime.show_dialog(runtime.bound(slot), value); }\n}\n\nexport void Dialog_text(i32 slot, str value) {\n    if (runtime.text_changed(slot, value)) { send_text(runtime.dialog_text(runtime.bound(slot)), value); }\n}\n\nexport void Checkbox_checked(i32 slot, bool value) {\n    if (!runtime.word_changed(slot, value ? 1 : 0)) { return; }\n    Request request = runtime.ui_request(UiOp::SET_CHECKED);\n    request.a0 = (i32)runtime.bound(slot);\n    request.a1 = value ? 1 : 0;\n    runtime.send(&request);\n}\n\n// `{\"clicks: %d\", c.clicks}` lowers to format, then format_int or format_str\n// per value, then format_end. Each takes what is left of the format and copies\n// the text up to the next value. The text lives here until the next format.\nText<256> g_format;\n\n// Copies the literal text at the start of `left` and returns what follows the\n// next %d or %s.\nstr format_literal(str left) {\n    i32 i = 0;\n    while (i < left.length) {\n        i32 c = left.byte(i);\n        i32 spec = left.byte(i + 1);\n        if (c == '%' && spec == '%') {\n            g_format.push((u8)'%');\n            i = i + 2;\n        } else if (c == '%') {\n            return case left.slice(i + 2, left.length) of { Some(after) -> after; None -> \"\"; };\n        } else {\n            g_format.push((u8)c);\n            i++;\n        }\n    }\n    return \"\";\n}\n\nexport str format(str text) {\n    g_format.clear();\n    return format_literal(text);\n}\n\nexport str format_int(str left, i32 value) {\n    Text<12> decimal = value.to_string();\n    g_format.append(decimal.as_str());\n    return format_literal(left);\n}\n\nexport str format_str(str left, str value) {\n    g_format.append(value);\n    return format_literal(left);\n}\n\nexport str format_end(str left) { return g_format.as_str(); }\n","system/MyAppFramework/src/runtime/runtime.unsafe.mln":"namespace runtime;\n\n// The application side of the framework: what runs inside an app process to\n// turn its annotations and markup handlers into behaviour. The OS never calls\n// into it -- it only sends events (contracts/myapp/message.contract.mln); app.run\n// drives it.\n//\n// - The handler table: `onClick={c.click}` in markup and @timer / @key methods\n//   are registered here as (key, kind) -> function, and called from next() when\n//   the matching event arrives. The server holds no app function pointers.\n// - start_annotations(): creates the app's timers and claims its keys.\n// - next(): takes one event and runs its handler, or says what app.run has to do.\n//\n// A handler is called with the instance and the value its event carries, and a\n// method is passed as is, because a `borrow` receiver is an address underneath.\n\nimport app_transport from \"transport.mln\";\nimport app_allocator from \"allocator.mln\";\nimport { Request, RequestDomain, RequestStatus, Event, EventKind } from \"@contracts/myapp/message.contract.mln\";\nimport { UiOp } from \"@contracts/myapp/ui.contract.mln\";\nimport { AppOp, AppError, KeyClaimError } from \"@contracts/myapp/lifecycle.contract.mln\";\nimport hosted_log from \"@std/hosted/log.mln\";\nimport annotations from \"@std/meta/annotations.mln\";\nimport { Annotations, AnnotationError } from \"@std/meta/annotations.mln\";\nimport { NodeId, UiError } from \"@contracts/ui/widget.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { CodeAddress } from \"@std/core/address.mln\";\nimport { Text } from \"@std/text/text.mln\";\nimport str from \"@std/text/str.mln\";\n\n// The instance this process runs (one per process): handlers get it as\n// their receiver. Requests carry it as `owner` too, but the OS replaces\n// that with the pid -- to the server, the owner of everything this process\n// creates is the process -- and events name that pid, not this pointer.\ni32 current_owner = 0;\ni32 g_main_window = 0;\nText<64> g_open_path;\n\ni32 annotation_i32(Result<i32, AnnotationError> value) {\n    return case value of {\n        Ok(v) -> v;\n        Err(_) -> 0;\n    };\n}\n\nCodeAddress annotation_code(Result<CodeAddress, AnnotationError> value) {\n    return case value of {\n        Ok(v) -> v;\n        Err(_) -> CodeAddress(0);\n    };\n}\n\nstr annotation_text(Result<str, AnnotationError> value) {\n    return case value of {\n        Ok(v) -> v;\n        Err(_) -> \"\";\n    };\n}\n\n// A line on the OS's debug console, for an app's own diagnostics.\n@safe\nexport void log(str line) {\n    hosted_log.write(line);\n}\n\n// JSX construction is atomic from an application's point of view: a partial\n// tree is not useful. Typed element calls expose UiError to ordinary callers;\n// markup uses this terminal policy and ends the process on construction\n// failure instead of inventing node id 0.\n@safe\nexport void fail_ui(UiError error) {\n    log(\"UI construction failed\");\n    app_transport.exit();\n    while (1) { app_transport.idle(); }\n}\n\n// --- handler table ---------------------------------------------------------------------\n\ni32 HANDLERS_MAX = 256;\n\n// What a handler takes after its receiver, which is what its event carries.\nenum HandlerShape {\n    NONE,   // ()\n    FLAG,   // (bool on)\n    TEXT,   // (str text), read from the node\n    ROW,    // (i32 row)\n    CARET,  // (i32 line, i32 column), packed in the event as line << 16 | column\n}\n\nstruct Handler {\n    i32 key;           // node id, or KEY claim token\n    EventKind kind;\n    HandlerShape shape;\n    fn(i32 owner) -> void callback;\n};\nHandler handlers[256];\ni32 handler_count = 0;\n\n/** Registers a handler of an event that carries nothing. */\n@safe\nexport void on_event(i32 key, EventKind kind, fn(i32 owner) -> void callback) {\n    add_handler(key, kind, HandlerShape::NONE, callback);\n}\n\n/** Registers a handler of a change that carries an on or off. */\n@safe\nexport void on_flag(i32 key, EventKind kind, fn(i32 owner, bool on) -> void callback) {\n    add_handler(key, kind, HandlerShape::FLAG, (fn(i32 owner) -> void)callback);\n}\n\n/** Registers a handler of a change that carries the node's text. */\n@safe\nexport void on_text(i32 key, EventKind kind, fn(i32 owner, str text) -> void callback) {\n    add_handler(key, kind, HandlerShape::TEXT, (fn(i32 owner) -> void)callback);\n}\n\n/** Registers a handler of an event that carries a row. */\n@safe\nexport void on_row(i32 key, EventKind kind, fn(i32 owner, i32 row) -> void callback) {\n    add_handler(key, kind, HandlerShape::ROW, (fn(i32 owner) -> void)callback);\n}\n\n/** Registers a handler of a caret that moved: its line and column, from 1. */\n@safe\nexport void on_caret(i32 key, fn(i32 owner, i32 line, i32 column) -> void callback) {\n    add_handler(key, EventKind::CARET, HandlerShape::CARET, (fn(i32 owner) -> void)callback);\n}\n\nvoid add_handler(i32 key, EventKind kind, HandlerShape shape, fn(i32 owner) -> void callback) {\n    if (callback == 0 || handler_count >= HANDLERS_MAX) { return; }\n    handlers[handler_count].key = key;\n    handlers[handler_count].kind = kind;\n    handlers[handler_count].shape = shape;\n    handlers[handler_count].callback = callback;\n    handler_count++;\n}\n\n// The row of the handler for (key, kind), or -1.\ni32 find_handler(i32 key, EventKind kind) {\n    i32 i = 0;\n    while (i < handler_count) {\n        if (handlers[i].key == key && handlers[i].kind == kind) { return i; }\n        i++;\n    }\n    return -1;\n}\n\nvoid call_handler(i32 row, Event *ev) {\n    fn(i32 owner) -> void callback = handlers[row].callback;\n    if (handlers[row].shape == HandlerShape::FLAG) {\n        fn(i32 owner, bool on) -> void flag = (fn(i32 owner, bool on) -> void)callback;\n        flag(current_owner, ev->arg != 0);\n        return;\n    }\n    if (handlers[row].shape == HandlerShape::TEXT) {\n        fn(i32 owner, str text) -> void changed = (fn(i32 owner, str text) -> void)callback;\n        changed(current_owner, read_text(NodeId(ev->id)));\n        return;\n    }\n    if (handlers[row].shape == HandlerShape::ROW) {\n        fn(i32 owner, i32 row) -> void selected = (fn(i32 owner, i32 row) -> void)callback;\n        selected(current_owner, ev->arg);\n        return;\n    }\n    if (handlers[row].shape == HandlerShape::CARET) {\n        fn(i32 owner, i32 line, i32 column) -> void moved = (fn(i32 owner, i32 line, i32 column) -> void)callback;\n        moved(current_owner, ev->arg >> 16, ev->arg & 0xFFFF);\n        return;\n    }\n    callback(current_owner);\n}\n\n// --- requests ------------------------------------------------------------------------------\n\n/** Creates a zero-filled UI request with safe empty string payloads. */\n@safe\nexport Request ui_request(i32 op) {\n    Request request = Request {};\n    request.domain = RequestDomain::UI;\n    request.op = op;\n    request.s0 = \"\";\n    request.s1 = \"\";\n    return request;\n}\n\n/** Creates a zero-filled application lifecycle request. */\n@safe\nexport Request app_request(i32 op) {\n    Request request = Request {};\n    request.domain = RequestDomain::APP;\n    request.op = op;\n    request.s0 = \"\";\n    request.s1 = \"\";\n    return request;\n}\n\n/** Sends one fully described request as the current application instance. */\n@safe\nexport RequestStatus send(borrow Request request) {\n    request.owner = current_owner;\n    return app_transport.request(&request);\n}\n\n/** Attaches the first string argument. The OS copies it during send(). */\n@safe\nexport void put_s0(borrow Request request, str s) {\n    request.s0 = s.data;\n    request.s0_len = s.length;\n}\n\n/** Attaches the second string argument. The OS copies it during send(). */\n@safe\nexport void put_s1(borrow Request request, str s) {\n    request.s1 = s.data;\n    request.s1_len = s.length;\n}\n\n// Sends a request whose typed answer the OS copies to `address`.\nvoid ask(borrow Request request, i32 address, i32 size) {\n    request.result_out = address;\n    request.result_size = size;\n    send(&request);\n}\n\n/** Sends a request and receives its Result<i32, UiError> answer. */\n@safe\nexport void ask_i32(borrow Request request, borrow Result<i32, UiError> result) {\n    ask(&request, (i32)&result, sizeof(Result<i32, UiError>));\n}\n\n/** Sends a request and receives its Result<NodeId, UiError> answer. */\n@safe\nexport void ask_node(borrow Request request, borrow Result<NodeId, UiError> result) {\n    ask(&request, (i32)&result, sizeof(Result<NodeId, UiError>));\n}\n\n/** Sends an OPEN request. The answer names the window, which only the shell needs. */\n@safe\nexport Result<_, AppError> ask_open(borrow Request request) {\n    Result<Option<NodeId>, AppError> result = Err(AppError::NoOpenHandler);\n    ask(&request, (i32)&result, sizeof(Result<Option<NodeId>, AppError>));\n    AppError error = case result of {\n        Ok(_) -> ({ return Ok(_); });\n        Err(value) -> value;\n    };\n    return Err(error);\n}\n\n/** Sends a request and receives its Result<i32, KeyClaimError> answer. */\n@safe\nexport void ask_key(borrow Request request, borrow Result<i32, KeyClaimError> result) {\n    ask(&request, (i32)&result, sizeof(Result<i32, KeyClaimError>));\n}\n\n/** Sends a request and receives its Result<_, UiError> answer. */\n@safe\n/** Sends a request and receives its Result<_, AppError> answer. */\n@safe\nvoid send_app_value(i32 op, i32 a0, str s0) {\n    Request request = app_request(op);\n    request.a0 = a0;\n    put_s0(&request, s0);\n    send(&request);\n}\n\n// --- bound properties ------------------------------------------------------------------------\n\n// A property of `view` that reads the state. Each pass the element's hook\n// hands in the value; what goes to the server is what differs from the last\n// value. `view` built the node with the first value, so the first pass only\n// records it. Text is kept whole on the heap: a hash would miss a change.\ni32 BINDINGS_MAX = 32;\nstruct Binding {\n    i32 node;\n    bool seen;\n    i32 word;\n    char *text;\n    i32 length;\n    i32 capacity;\n};\nBinding bindings[32];\n\n/** Records the node of a bound property. */\n@safe\nexport void bind(i32 slot, i32 node) {\n    if (slot >= BINDINGS_MAX) {\n        log(\"Too many bound properties\");\n        app_transport.exit();\n    }\n    bindings[slot].node = node;\n}\n\n/** The node of a bound property. */\n@safe\nexport NodeId bound(i32 slot) { return NodeId(bindings[slot].node); }\n\n/** Records a scalar value.\n * @return True when it differs from the last one, so the screen must change.\n */\n@safe\nexport bool word_changed(i32 slot, i32 value) {\n    bool first = !bindings[slot].seen;\n    return word_differs(slot, value) && !first;\n}\n\n/** Records a scalar value that `view` did not show: a binding starts at zero.\n * @return True when it differs from the last one.\n */\n@safe\nexport bool word_differs(i32 slot, i32 value) {\n    bool same = bindings[slot].word == value;\n    bindings[slot].seen = true;\n    bindings[slot].word = value;\n    return !same;\n}\n\nbool same_bytes(char *a, str b) {\n    i32 i = 0;\n    while (i < b.length) {\n        if (a[i] != b.data[i]) { return false; }\n        i++;\n    }\n    return true;\n}\n\n/** Records a text value.\n * @return True when it differs from the last one, so the screen must change.\n */\n@safe\nexport bool text_changed(i32 slot, str value) {\n    bool first = !bindings[slot].seen;\n    bindings[slot].seen = true;\n    if (!first && bindings[slot].length == value.length && same_bytes(bindings[slot].text, value)) {\n        return false;\n    }\n    if (value.length > bindings[slot].capacity) {\n        app_allocator.free((i32)bindings[slot].text);\n        i32 room = value.length + 16;\n        bindings[slot].text = case app_allocator.alloc(room) of {\n            Ok(pointer) -> (char*)pointer;\n            Err(_) -> ({ log(\"Out of memory for a bound text\"); app_transport.exit(); (char*)0; });\n        };\n        bindings[slot].capacity = room;\n    }\n    i32 i = 0;\n    while (i < value.length) {\n        bindings[slot].text[i] = value.data[i];\n        i++;\n    }\n    bindings[slot].length = value.length;\n    return !first;\n}\n\n// --- parts -------------------------------------------------------------------------------------\n\n// A part is what an app holds of a value the DOM keeps: a number it gets in\n// `start`, because `view` cannot write to the state. `view` hands the number to\n// an element, which is how it comes to name a node. Zero is no part.\ni32 PARTS_MAX = 16;\ni32 parts[16];\ni32 part_count = 0;\n\n/** A new part's number. */\n@safe\nexport i32 new_part() {\n    if (part_count + 1 >= PARTS_MAX) {\n        log(\"Too many parts\");\n        app_transport.exit();\n    }\n    part_count++;\n    return part_count;\n}\n\n/** Makes a part name a node. */\n@safe\nexport void attach(i32 part, NodeId node) {\n    if (part != 0) { parts[part] = (i32)node; }\n}\n\n/** The node of a part. */\n@safe\nexport NodeId part_node(i32 part) { return NodeId(parts[part]); }\n\n// A read's text. The largest is an Editor's body, and few apps read that much,\n// so it comes from the heap on the first read.\ni32 READ_MAX = 4096;\nchar *g_read = (char*)0;\n\n/** A node's text, valid until the next read. */\n@safe\nexport str read_text(NodeId id) {\n    if (g_read == 0) {\n        g_read = case app_allocator.alloc(READ_MAX) of {\n            Ok(pointer) -> (char*)pointer;\n            Err(_) -> ({ log(\"Out of memory for a text\"); app_transport.exit(); (char*)0; });\n        };\n    }\n    Result<i32, UiError> result = Err(UiError::NodeNotFound(id));\n    Request request = ui_request(UiOp::TEXT_COPY);\n    request.a0 = (i32)id;\n    request.a1 = (i32)g_read;\n    request.a2 = READ_MAX;\n    ask_i32(&request, &result);\n    i32 length = case result of { Ok(value) -> value; Err(_) -> 0; };\n    return str { data: g_read, length: length };\n}\n\n// --- dialogs -----------------------------------------------------------------------------------\n\n// A dialog is built with the rest of `view`, but as a window of its own: it\n// stays out of the tree its markup sits in, off the desktop until it is shown.\ni32 DIALOGS_MAX = 4;\nstruct Dialog {\n    i32 window;\n    i32 text;      // the label that says what is asked\n};\nDialog dialogs[4];\ni32 dialog_count = 0;\n\n/** Records a dialog's window and the label its text goes to. */\n@safe\nexport void add_dialog(NodeId window, NodeId text) {\n    if (dialog_count >= DIALOGS_MAX) {\n        log(\"Too many dialogs\");\n        app_transport.exit();\n    }\n    dialogs[dialog_count].window = (i32)window;\n    dialogs[dialog_count].text = (i32)text;\n    dialog_count++;\n}\n\n/** Whether a node is a dialog's window. */\n@safe\nexport bool is_dialog(NodeId window) {\n    i32 i = 0;\n    while (i < dialog_count) {\n        if (dialogs[i].window == (i32)window) { return true; }\n        i++;\n    }\n    return false;\n}\n\n/** The label of a dialog's window. */\n@safe\nexport NodeId dialog_text(NodeId window) {\n    i32 i = 0;\n    while (i < dialog_count) {\n        if (dialogs[i].window == (i32)window) { return NodeId(dialogs[i].text); }\n        i++;\n    }\n    return window;\n}\n\n/** Puts a dialog on the desktop, or takes it off. */\n@safe\nexport void show_dialog(NodeId window, bool shown) {\n    send_app_value(shown ? AppOp::SHOW_DIALOG : AppOp::HIDE_DIALOG, (i32)window, \"\");\n}\n\n// --- lifecycle -----------------------------------------------------------------------------\n\n/** Prepares the process before the app's first state is made. */\n@safe\nexport void enter() { app_allocator.init(); }\n\n/** Names the instance handlers are called on. */\n@safe\nexport void adopt(i32 self) { current_owner = self; }\n\n/** Hands the shell the app's window. */\n@safe\nexport void show_main(NodeId win) {\n    g_main_window = (i32)win;\n    send_app_value(AppOp::MAIN_WINDOW, (i32)win, \"\");\n}\n\n/** What the event just taken asks of the instance. */\nexport enum Step {\n    Idle,     // no event is waiting\n    Handled,  // its handler has run\n    Open,     // open(opened_path())\n    Close,    // close(), then exit()\n}\n\n/** The path of the Step::Open just taken, valid until the next event. */\n@safe\nexport str opened_path() { return g_open_path.as_str(); }\n\n/** Takes one event and runs its handler. */\n@safe\nexport Step next() {\n    Event ev;\n    if (!app_transport.poll(&ev)) { return Step::Idle; }\n    if (ev.kind == EventKind::OPEN) {\n        g_open_path.clear();\n        g_open_path.append(str.from_c(&ev.text[0]));\n        return Step::Open;\n    }\n    if (ev.kind == EventKind::CLOSE && ev.id == g_main_window) { return Step::Close; }\n    i32 key = ev.id;\n    if (ev.kind == EventKind::KEY) { key = ev.token; }\n    i32 row = find_handler(key, ev.kind);\n    if (row >= 0) { call_handler(row, &ev); }\n    return Step::Handled;\n}\n\n/** Blocks until an event is published. */\n@safe\nexport void idle() { app_transport.idle(); }\n\n/** Tells the OS the instance is done and ends the process. */\n@safe\nexport void exit() {\n    send_app_value(AppOp::EXIT, 0, \"\");\n    app_transport.exit();\n}\n\n// Creates the @timer timers of type `type` and claims its @key shortcuts.\nvoid start_annotated(str type) {\n    Annotations timers = annotations.where(\"timer\", type);\n    while (timers.next()) {\n        Result<NodeId, UiError> created = Err(UiError::TimerLimit);\n        Request request = ui_request(UiOp::CREATE_TIMER);\n        request.a0 = annotation_i32(timers.arg(0));\n        ask_node(&request, &created);\n        NodeId id = case created of { Ok(value) -> value; Err(e) -> ({ fail_ui(e); (NodeId)0; }); };\n        on_event((i32)id, EventKind::TIMER, (fn(i32 owner) -> void)annotation_code(timers.fn()));\n    }\n    Annotations keys = annotations.where(\"key\", type);\n    while (keys.next()) {\n        Result<i32, KeyClaimError> claimed = Err(KeyClaimError::TableFull);\n        Request request = app_request(AppOp::CLAIM_KEY);\n        put_s0(&request, annotation_text(keys.text(0)));\n        ask_key(&request, &claimed);\n        case claimed of {\n            Ok(token) -> on_event(token, EventKind::KEY, (fn(i32 owner) -> void)annotation_code(keys.fn()));\n            Err(_) -> log(\"Could not register app keyboard shortcut\");\n        };\n    }\n}\n\n/** Starts what the @app type's annotations ask for: its timers and keys. */\n@safe\nexport void start_annotations() {\n    Annotations rows = annotations.named(\"app\");\n    if (rows.next()) { start_annotated(annotation_text(rows.type())); }\n}\n\n// --- nodes --------------------------------------------------------------------------------------\n\n// What the framework does to a node for an app. An app holds parts, never nodes,\n// so these stay out of ui.mln.\n\n/** Adds NodeStyle bits an app may set (UiOp::ADD_STYLE): following the\n * window's size, a TextArea's wrapping, reporting its caret. */\n@safe\nexport void add_style(NodeId id, i32 bits) {\n    if (bits == 0) { return; }\n    Request request = ui_request(UiOp::ADD_STYLE);\n    request.a0 = (i32)id;\n    request.a1 = bits;\n    send(&request);\n}\n\n/** Cuts, copies, pastes or selects all in a TextInput or TextArea\n * (UiOp::TEXT_EDIT), as its Ctrl+X, C, V and A keys do. */\n@safe\nexport void text_edit(NodeId id, i32 command) {\n    Request request = ui_request(UiOp::TEXT_EDIT);\n    request.a0 = (i32)id;\n    request.a1 = command;\n    send(&request);\n}\n\n/** Replaces the text of a TextInput or TextArea. */\n@safe\nexport void input_set(NodeId id, str s) {\n    Request request = ui_request(UiOp::INPUT_SET);\n    request.a0 = (i32)id; put_s0(&request, s);\n    send(&request);\n}\n\n/** Adds to the end of a TextArea's text. */\n@safe\nexport void area_append(NodeId id, str s) {\n    Request request = ui_request(UiOp::AREA_APPEND);\n    request.a0 = (i32)id; put_s0(&request, s);\n    send(&request);\n}\n\n/** Moves the keyboard to a node. */\n@safe\nexport void focus(NodeId id) {\n    Request request = ui_request(UiOp::FOCUS);\n    request.a0 = (i32)id;\n    send(&request);\n}\n","system/MyAppFramework/src/runtime/transport.unsafe.mln":"namespace app_transport;\n\n// The application's end of the request/event transport declared in\n// contracts/myapp/message.contract.mln. request() queues the message and blocks until the\n// reply is in; poll() takes one event; idle() blocks for an event; exit() ends\n// the process. Everything the message names by pointer is copied by the\n// OS at the boundary.\n\nimport { sys_wait_notification, sys_exit } from \"@std/platform/myos/syscall.masm\";\nimport myos_service from \"@std/platform/myos/service.mln\";\nimport { OsService } from \"@contracts/myos/services.contract.mln\";\nimport { Request, Event, TransportSignal } from \"@contracts/myapp/message.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\n\n/** Returns a known service's scalar value, or zero if its transport fails. */\ni32 service_value(i32 service_number, i32 args) {\n    return case myos_service.call(service_number, args) of {\n        Ok(value) -> value;\n        Err(_) -> 0;\n    };\n}\n\n/** Blocks for an armed transport signal and discards the delivered bit mask. */\nvoid wait_for(i32 mask) {\n    i32 notification = 0;\n    sys_wait_notification(mask, &notification);\n}\n\n// The syscall reply is an ABI word. runtime.send() converts it to the public\n// RequestStatus enum at this boundary.\nexport i32 request(borrow Request m) {\n    // The shared request ring can be briefly full while several applications\n    // are mounting. A rejected enqueue has no reply, so retry it instead of\n    // entering the reply wait with no request in flight.\n    while (service_value(OsService::REQUEST, (i32)&m) == 0) {\n        wait_for(TransportSignal::REQUEST_SPACE);\n    }\n    i32 r[2];\n    r[0] = 0;\n    while (service_value(OsService::REPLY, (i32)(&r[0])) == 0) {\n        wait_for(TransportSignal::REPLY);\n    }\n    return r[0];\n}\n\nexport bool poll(Event *out) {\n    if (service_value(OsService::POLL, (i32)out) == 0) { return false; }\n    return true;\n}\n\nexport void idle() {\n    wait_for(TransportSignal::EVENT);\n}\n\nexport void exit() {\n    sys_exit(0);\n}\n","system/MyKernel/src/kernel/ipc.unsafe.mln":"namespace ipc;\n\n/**\n * Fixed-capacity message channels shared by kernel tasks and user processes.\n * Channel IDs are 1-based. Each ring reserves one slot to distinguish full\n * from empty, so a channel can hold at most SLOTS - 1 messages. Operations\n * are serialized by the syscall/interrupt path on this single-core kernel.\n * Message words containing pointers are only meaningful in a shared address\n * space; user-facing callers must copy pointed-to data across the boundary.\n */\n//\n// A channel is a ring of MSG_WORDS-word slots. The application request channel\n// has multiple producers, but syscall handlers run with interrupts disabled on\n// this single-core kernel, so send operations are serialized. send() copies a\n// message in and fails when the ring is full; recv() copies the oldest out; wait() sleeps\n// until one arrives. Messages are words: pointers in them are only\n// meaningful while both ends share an address space -- when one end is a\n// user process, the syscall layer copies what a pointer names before the\n// message crosses (MYOS-022).\n//\n// The application protocol runs on these (MyOS/src/ipc/channel.mln):\n// requests to the UI server, replies back, and events to the apps.\n\nimport scheduler from \"scheduler.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Result } from \"@std/core/result.mln\";\n\n/** Opaque 1-based handle for a kernel message channel. Zero is invalid. */\nexport newtype ChannelId = i32;\n\n/** Failure while querying a message channel. */\nexport enum ChannelError {\n    InvalidId(i32),\n}\n\n// 24 words leave 64 inline bytes after an Event's five scalar words. Keeping\n// event text in the ring slot avoids queuing a pointer to reused server memory.\n/** Number of 32-bit words in each message slot. */\nexport const i32 MSG_WORDS = 24;\ni32 CHANNELS_MAX = 40;   // the UI protocol takes two per process plus one\ni32 SLOTS = 32;\n\nstruct Channel {\n    bool used;\n    i32 head;       // next slot to read\n    i32 tail;       // next slot to write\n};\nChannel g_channels[40];\ni32 g_ring[30720];  // CHANNELS_MAX * SLOTS * MSG_WORDS\n\n/**\n * Allocates the next unused message channel.\n * @return Some(channel_id) with a 1-based ID, or None when all channels are used.\n */\nexport Option<ChannelId> create() {\n    i32 c = 0;\n    while (c < CHANNELS_MAX) {\n        if (!g_channels[c].used) {\n            g_channels[c] = Channel { used: true, head: 0, tail: 0 };\n            return Some(ChannelId(c + 1));\n        }\n        c++;\n    }\n    return None;\n}\n\n/**\n * Calculates the first word index of a slot in the flattened ring buffer.\n * @param c Zero-based channel table index.\n * @param slot Zero-based slot index within that channel.\n * @return Word offset of the slot in g_ring.\n */\ni32 slot_base(i32 c, i32 slot) {\n    return (c * SLOTS + slot) * MSG_WORDS;\n}\n\n/**\n * Copies one message into a channel's queue.\n * @param ch 1-based channel ID returned by create().\n * @param words Pointer to at least MSG_WORDS message words.\n * @return True if queued; false if the ID is invalid or the queue is full.\n */\nexport bool send(ChannelId ch, i32 *words) {\n    i32 raw = (i32)ch;\n    if (raw <= 0 || raw > CHANNELS_MAX) { return false; }\n    i32 c = raw - 1;\n    i32 next = g_channels[c].tail + 1;\n    if (next >= SLOTS) { next = 0; }\n    if (next == g_channels[c].head) { return false; }\n    i32 at = slot_base(c, g_channels[c].tail);\n    i32 i = 0;\n    while (i < MSG_WORDS) { g_ring[at + i] = words[i]; i++; }\n    g_channels[c].tail = next;\n    return true;\n}\n\n/**\n * Checks whether a queued message matches two key words.\n * Compares w1 and w2 with message words 1 and 2 respectively; callers use\n * this to coalesce duplicate notifications such as an already-queued tick.\n * @param ch 1-based channel ID.\n * @param w1 Value expected in message word 1.\n * @param w2 Value expected in message word 2.\n * @return True if a matching message is queued; false for no match or invalid ID.\n */\nexport bool has(ChannelId ch, i32 w1, i32 w2) {\n    i32 raw = (i32)ch;\n    if (raw <= 0 || raw > CHANNELS_MAX) { return false; }\n    i32 c = raw - 1;\n    i32 i = g_channels[c].head;\n    while (i != g_channels[c].tail) {\n        i32 at = slot_base(c, i);\n        if (g_ring[at + 1] == w1 && g_ring[at + 2] == w2) { return true; }\n        i = i + 1;\n        if (i >= SLOTS) { i = 0; }\n    }\n    return false;\n}\n\n/**\n * Removes the oldest queued message and copies it to the caller's buffer.\n * @param ch 1-based channel ID.\n * @param out Destination for at least MSG_WORDS message words.\n * @return True if a message was copied; false if the ID is invalid or the queue is empty.\n */\nexport bool recv(ChannelId ch, i32 *out) {\n    i32 raw = (i32)ch;\n    if (raw <= 0 || raw > CHANNELS_MAX) { return false; }\n    i32 c = raw - 1;\n    if (g_channels[c].head == g_channels[c].tail) { return false; }\n    i32 at = slot_base(c, g_channels[c].head);\n    i32 i = 0;\n    while (i < MSG_WORDS) { out[i] = g_ring[at + i]; i++; }\n    i32 next = g_channels[c].head + 1;\n    if (next >= SLOTS) { next = 0; }\n    g_channels[c].head = next;\n    return true;\n}\n\n","system/MyKernel/src/kernel/irq_dispatch.unsafe.mln":"namespace irq_dispatch;\n\nimport mem from \"@kernel/mm/mem.mln\";\nimport scheduler from \"scheduler.mln\";\nimport serial from \"@kernel/io/serial.mln\";\nimport mouse from \"@kernel/io/mouse.mln\";\nimport keyboard from \"@kernel/io/keyboard.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport process from \"process.mln\";\nimport thread from \"thread.mln\";\nimport { KernelSignal } from \"thread.mln\";\nimport syscall from \"syscall.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport irq_frame from \"@kernel/arch/irq_frame.mln\";\nimport mmu from \"@kernel/mm/mmu.mln\";\nimport { irq_trampoline, irq_resume } from \"@kernel/arch/irq_trampoline.masm\";\nimport { Result } from \"@std/core/result.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Pid, ProcessExitStatus } from \"@contracts/process/control.contract.mln\";\n\n/** Memory-mapped hardware register containing pending interrupt-cause bits. */\ni32 IRQ_CAUSE_ADDR = 0x24000084;\n/** Bit mask for timer interrupts in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_TIMER  = 1;\n/** Bit mask for mouse interrupts in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_MOUSE  = 2;\n/** Bit mask for serial input interrupts in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_SERIAL = 4;\n/** Bit mask for storage-device interrupts in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_SSD    = 8;\n/** Bit mask for software system-call traps in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_SYSCALL = 16;\n/** Bit mask for page-fault traps in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_PAGE_FAULT = 32;\n/** Bit mask for user-mode privilege-violation traps in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_PRIVILEGE_VIOLATION = 64;\n/** Bit mask for keyboard interrupts in IRQ_CAUSE_ADDR. */\ni32 IRQ_CAUSE_KEYBOARD = 128;\n/** Bit mask for illegal-instruction traps raised from user mode. */\ni32 IRQ_CAUSE_ILLEGAL_INSTRUCTION = 256;\n/** Bit mask for a request the host posted on the automation bridge. */\ni32 IRQ_CAUSE_AUTOMATION = 512;\n\n/**\n * Top-level hardware interrupt entry point called from the vector table.\n *\n * Preserves CPU state via trampoline, dispatches to interrupt handlers, and never returns directly.\n * The saved frame depends on this function's prologue; see irq_frame.unsafe.mln.\n */\nexport void entry() {\n    dispatch(irq_frame.complete(irq_trampoline()));\n    debug.panic(\"irq dispatcher returned unexpectedly\");\n}\n\n/**\n * Dispatches interrupt causes (serial, mouse, keyboard, faults, syscall, timer).\n *\n * Handles pending hardware events, traps, system calls, and timer ticks before resuming execution.\n * @param sp Stack pointer of the saved interrupt frame.\n */\nexport void dispatch(i32 sp) {\n    bool was_enabled = irq.enter_handler();\n    i32 cause = mem.read_word(IRQ_CAUSE_ADDR);\n    \n    // Ack the handled interrupts to hardware\n    mem.write_word(IRQ_CAUSE_ADDR, cause);\n\n    if (cause & IRQ_CAUSE_SERIAL) {\n        // Drain the hardware RX register into the software input queue.\n        while (serial.rx_ready()) {\n            i32 c = serial.read_rx();\n            serial.input_push(c);\n        }\n        thread.notify_all(KernelSignal::SERIAL);\n    }\n\n    if (cause & IRQ_CAUSE_MOUSE) {\n        mouse.drain_hw();\n    }\n\n    if (cause & IRQ_CAUSE_KEYBOARD) {\n        keyboard.drain_hw();\n    }\n\n    if (cause & (IRQ_CAUSE_MOUSE | IRQ_CAUSE_KEYBOARD)) {\n        thread.notify_all(KernelSignal::INPUT);\n    }\n\n    if (cause & IRQ_CAUSE_AUTOMATION) {\n        thread.notify_all(KernelSignal::AUTOMATION);\n    }\n\n    // Handle synchronous traps first\n    if (cause & IRQ_CAUSE_PRIVILEGE_VIOLATION) {\n        debug.println(\"irq: privilege violation in user process\");\n        debug.printf(\"irq: fault addr: 0x%x status: %i\\n\", mmu.get_fault_address(), mmu.get_fault_status());\n        Option<Pid> current = thread.current_pid();\n        case current of {\n            Some(_) -> ({\n                ProcessExitStatus status = ProcessExitStatus::PrivilegeViolation;\n                syscall.sys_exit_status(status);\n                sp = scheduler.reschedule(sp);\n                irq.leave_handler(was_enabled);\n                irq_resume(sp);\n                return; // unreachable: irq_resume restores a frame and executes iret\n            });\n            None -> _;\n        };\n    }\n\n    if (cause & IRQ_CAUSE_PAGE_FAULT) {\n        debug.println(\"irq: unhandled page fault in user process\");\n        Option<Pid> current = thread.current_pid();\n        case current of {\n            Some(_) -> ({\n                ProcessExitStatus status = ProcessExitStatus::PageFault;\n                syscall.sys_exit_status(status);\n                sp = scheduler.reschedule(sp);\n                irq.leave_handler(was_enabled);\n                irq_resume(sp);\n                return; // unreachable: irq_resume restores a frame and executes iret\n            });\n            None -> _;\n        };\n    }\n\n    if (cause & IRQ_CAUSE_ILLEGAL_INSTRUCTION) {\n        debug.println(\"irq: illegal instruction in user process\");\n        Option<Pid> current = thread.current_pid();\n        case current of {\n            Some(_) -> ({\n                ProcessExitStatus status = ProcessExitStatus::IllegalInstruction;\n                syscall.sys_exit_status(status);\n                sp = scheduler.reschedule(sp);\n                irq.leave_handler(was_enabled);\n                irq_resume(sp);\n                return;\n            });\n            None -> _;\n        };\n    }\n\n    if (cause & IRQ_CAUSE_SYSCALL) {\n        case syscall.dispatch(sp) of {\n            Ok(outcome) -> ({\n                if (!outcome.parked) { irq_frame.set_syscall_return(sp, outcome.status, outcome.value); }\n                sp = outcome.next_sp;\n            });\n            Err(error) -> ({ irq_frame.set_syscall_return(sp, syscall.error_status(error), 0); });\n        };\n    }\n\n    if (cause & IRQ_CAUSE_TIMER) {\n        sp = scheduler.tick(sp);\n    } else {\n        sp = scheduler.resume_after_interrupt(sp);\n    }\n\n    irq.leave_handler(was_enabled);\n    irq_resume(sp);\n}\n","system/MyKernel/src/kernel/scheduler.unsafe.mln":"namespace scheduler;\n\nimport debug from \"@kernel/debug/debug.mln\";\nimport mem from \"@kernel/mm/mem.mln\";\nimport heap from \"@kernel/mm/heap.mln\";\nimport process from \"process.mln\";\nimport thread from \"thread.mln\";\nimport mmu from \"@kernel/mm/mmu.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport irq_frame from \"@kernel/arch/irq_frame.mln\";\nimport { SyscallStatus } from \"@contracts/myos/syscall.contract.mln\";\nimport { wfi_cpu } from \"@kernel/arch/wfi.masm\";\nimport { Result } from \"@std/core/result.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Pid, ProcessExitStatus } from \"@contracts/process/control.contract.mln\";\n\n/** Failure cases returned by kernel-thread creation. */\nexport enum SchedulerError {\n    OutOfMemory,\n    TaskSlotFull,\n}\n\n// Scheduler ticks since init: the ticks the timer's clock has passed. Each\n// timer interrupt brings it up to the clock, and so does the end of a hold.\ni32 g_irq_count = 0;\nbool g_initialized = false;\ni32 idle_sp = 0;\nOption<i32> deferred_cleanup_slot;\n// thread.ready_epoch() when the scheduler last found nothing to run; None\n// until it first does.\nOption<i32> g_idle_epoch;\ni32 MMU_PDBR_ADDR = 0x24000104;\ni32 KERNEL_SP_ADDR = 0x24000110;\n// The timer, a clock of 256 units a tick. Read: the ticks so far in the high\n// 24 bits, how far the current tick has got in the low 8; it wraps at 2^24\n// ticks. Write: a clock value to interrupt next at, the ticks before it\n// passing without an interrupt; 0 for every tick.\ni32 TIMER_ADDR = 0x24000088;\ni32 CLOCK_SHIFT = 8;\ni32 CLOCK_TICK_MASK = 0xFFFFFF;\n// The clock's ticks when g_irq_count last caught up with them.\ni32 g_clock_ticks = 0;\n// The timer holds its interrupts back until a wake tick: idle set one, having\n// nothing to do before it (hold_until_due).\nbool g_held = false;\n// The furthest a hold reaches, and the wake tick of one with no deadline to\n// wake for: 2^22 ticks, 70 minutes at the usual 1 ms tick. The clock's 2^24\n// ticks tell a tick ahead from one behind only within half of them.\ni32 HOLD_LONGEST = 0x400000;\n\n// Where the CPU's time went, in clock units: the clock when the scheduler\n// started, the clock up to which time has been charged, and what the time\n// since then belongs to -- a thread's slot, or None for idle.\ni32 g_clock_base = 0;\ni32 g_clock_charged = 0;\nOption<i32> g_charge_to;\ni32 g_idle_time = 0;\ni32 g_kernel_time = 0;\n\n/**\n * Runs the non-returning WFI fallback context while no TCB is runnable. Each\n * time it is about to wait, it holds the timer's interrupts back until the next\n * deadline: no tick before it has anything to do.\n */\nvoid idle_main() {\n    while (1) {\n        hold_until_due();\n        wfi_cpu();\n    }\n}\n\n/** Brings g_irq_count up to the ticks the timer's clock has passed. */\nvoid catch_up_ticks() {\n    i32 now = (mem.read_word(TIMER_ADDR) >> CLOCK_SHIFT) & CLOCK_TICK_MASK;\n    g_irq_count = g_irq_count + ((now - g_clock_ticks) & CLOCK_TICK_MASK);\n    g_clock_ticks = now;\n}\n\n/**\n * Ends a hold, if one is set: the timer interrupts at every tick again, and\n * the ticks it held back are counted. Their time was idle's, which charge_elapsed\n * gives it, idle being what it is charged to.\n */\nvoid release_hold() {\n    if (!g_held) { return; }\n    g_held = false;\n    mem.write_word(TIMER_ADDR, 0);\n    catch_up_ticks();\n}\n\n/**\n * Charges `spent` to what the time since the last charge belongs to: the\n * process of a user thread, the kernel for a kernel thread, idle for none.\n * @param spent Timer clock units.\n */\nexport void charge(i32 spent) {\n    case g_charge_to of {\n        Some(slot) -> ({\n            case thread.owner_pid_at(slot) of {\n                Some(pid) -> ({ process.charge_time(pid, spent); });\n                None -> ({ g_kernel_time = g_kernel_time + spent; });\n            };\n        });\n        None -> ({ g_idle_time = g_idle_time + spent; });\n    };\n}\n\n/** Charges the time up to the clock to what it belongs to. */\nexport void charge_elapsed() {\n    i32 now = mem.read_word(TIMER_ADDR);\n    charge(now - g_clock_charged);\n    g_clock_charged = now;\n}\n\n/**\n * Says what the time from the last charge on belongs to: the scheduler sets\n * it when it switches, and a kernel thread hands its time to idle while it\n * waits in WFI.\n * @param context A thread's slot, or None for idle.\n */\nexport void charge_to(Option<i32> context) { g_charge_to = context; }\n\n/**\n * A kernel thread blocked itself, with interrupts off, to wait in WFI on its\n * own stack: its time ends here, and the wait is idle's.\n */\nvoid charge_wait() {\n    charge_elapsed();\n    charge_to(None);\n}\n\n/**\n * Waits in WFI on the current kernel thread's own stack until it is no longer\n * blocked, then takes its time back: the wait was idle's, unless a switch away\n * and back already says otherwise.\n * @param slot The thread, which has blocked itself and called charge_wait.\n */\nvoid wait_in_wfi(i32 slot) {\n    while (thread.blocked(slot)) { wfi_cpu(); }\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    charge_elapsed();\n    charge_to(Some(slot));\n}\n\n/**\n * Called by idle before it waits: holds the timer's interrupts back until the\n * earliest deadline a sleep, a futex timeout or a notification wait has, or\n * for good when none has one. An interrupt that wakes a thread before then\n * ends the hold (resume_after_interrupt), and so does the wake tick (tick).\n */\nvoid hold_until_due() {\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    release_hold();\n    // The thread the last switch retired is cleaned up, and its joiner woken,\n    // by the next reschedule: that has to come at the next tick.\n    case deferred_cleanup_slot of {\n        Some(_) -> ({ return; });\n        None -> _;\n    };\n    catch_up_ticks();\n    i32 ahead = case thread.next_due() of {\n        Some(due) -> due - g_irq_count;\n        None -> HOLD_LONGEST;\n    };\n    if (ahead <= 1) { return; }\n    if (ahead > HOLD_LONGEST) { ahead = HOLD_LONGEST; }\n    // The clock at the wake tick; the tick wraps with the clock.\n    mem.write_word(TIMER_ADDR, (g_clock_ticks + ahead) << CLOCK_SHIFT);\n    g_held = true;\n}\n\n/** @return Scheduler timer-tick count used by sleep and futex deadlines. */\n@safe\nexport i32 ticks() { return g_irq_count; }\n\n/**\n * @return Time since the scheduler started, up to the last charge, in timer\n *         clock units (256 a tick). It wraps, so read differences.\n */\n@safe\nexport i32 cpu_total() { return g_clock_charged - g_clock_base; }\n\n/** @return Clock units with no thread to run, or only a kernel thread waiting in WFI. */\n@safe\nexport i32 idle_time() { return g_idle_time; }\n\n/** @return Clock units kernel threads ran: the OS's own work. */\n@safe\nexport i32 kernel_time() { return g_kernel_time; }\n\n/**\n * Exposes a stable nonzero execution-context index to the mocking runtime.\n * @return Current TCB slot plus one; zero represents the idle context.\n */\nexport i32 current_context() {\n    return case thread.current_slot() of { Some(slot) -> slot + 1; None -> 0; };\n}\n\n/**\n * Finds the next Runnable TCB by round-robin slot order.\n * @param start First slot to inspect.\n * @param count Number of slots within the current high-water range.\n * @return Some(runnable slot), or None when every candidate is unavailable.\n */\nOption<i32> find_next_runnable(i32 start, i32 count) {\n    if (count <= 0) { return None; }\n    i32 slot = start;\n    i32 checked = 0;\n    while (checked < count) {\n        if (thread.runnable(slot)) { return Some(slot); }\n        slot = (slot + 1) % count;\n        checked++;\n    }\n    return None;\n}\n\n/** Switches to the kernel's page directory, for a kernel thread or idle. */\nvoid install_kernel_space() {\n    case mmu.kernel_page_directory() of {\n        Some(kernel_pdbr) -> ({ mem.write_word(MMU_PDBR_ADDR, kernel_pdbr); });\n        None -> _;\n    };\n    mem.write_word(KERNEL_SP_ADDR, 0);\n}\n\n/**\n * Advances scheduler time and chooses the context to resume after a timer IRQ.\n * More than one tick can pass between two interrupts: a hold kept them back,\n * or interrupts were off across a tick.\n * @param sp Saved interrupt-frame SP of the interrupted context.\n * @return Saved kernel SP of the next TCB, or the idle frame when none is runnable.\n */\nexport i32 tick(i32 sp) {\n    catch_up_ticks();\n    if (g_held) {\n        // The wake tick: it ended the hold. Every tick interrupts again.\n        g_held = false;\n        mem.write_word(TIMER_ADDR, 0);\n    }\n    return reschedule(sp);\n}\n\n/**\n * After an interrupt other than the timer's: one that found the CPU idle with\n * the timer held, and woke a thread, switches to that thread now. Without a\n * hold the next tick, at most one period away, does it.\n * @param sp Saved interrupt-frame SP of the interrupted context.\n * @return Saved kernel SP of the context to resume.\n */\nexport i32 resume_after_interrupt(i32 sp) {\n    if (!g_held) { return sp; }\n    bool unchanged = case g_idle_epoch of { Some(epoch) -> epoch == thread.ready_epoch(); None -> false; };\n    if (unchanged) { return sp; }\n    return reschedule(sp);\n}\n\n/**\n * Saves the current TCB, performs safe deferred cleanup, and selects a next TCB.\n * Switch-in also installs the owner Process PDBR and per-thread user SP.\n * @param sp Saved interrupt-frame SP of the context being switched out.\n * @return Saved kernel SP that irq_resume must restore.\n */\nexport i32 reschedule(i32 sp) {\n    if (!g_initialized) { return sp; }\n    // The clock first: the deadlines below are compared with it, and the time\n    // up to now is what was running's.\n    release_hold();\n    charge_elapsed();\n\n    // Save the context being left before anything can wake a thread: a wake\n    // writes its result into the waiter's saved frame, and when the waiter is\n    // the thread leaving now (it just blocked in a syscall), that frame is the\n    // one saved here.\n    Option<i32> leaving = thread.current_slot();\n    case leaving of {\n        Some(current) -> ({ thread.switch_out(current, sp, mem.read_word(KERNEL_SP_ADDR)); });\n        None -> ({ idle_sp = sp; });\n    };\n\n    // This invocation runs on a different stack from the TCB retired by the\n    // preceding switch, so its stack can finally be released safely. Its\n    // joiner may be the thread leaving now.\n    case deferred_cleanup_slot of {\n        Some(retired) -> ({\n            deferred_cleanup_slot = None;\n            thread.finish_deferred_cleanup(retired);\n        });\n        None -> _;\n    };\n    thread.wake_due(g_irq_count);\n\n    i32 count = thread.high_water();\n    i32 start = 0;\n    case leaving of {\n        Some(current) -> ({\n            if (thread.exiting(current)) { deferred_cleanup_slot = Some(current); }\n            if (count > 0) { start = (current + 1) % count; }\n        });\n        None -> ({\n            // Idle, and nothing was woken or published since it found nothing\n            // to run: it still has nothing. Most ticks of an idle machine end here.\n            bool unchanged = case g_idle_epoch of { Some(epoch) -> epoch == thread.ready_epoch(); None -> false; };\n            if (unchanged) { return sp; }\n        });\n    };\n    Option<i32> next = find_next_runnable(start, count);\n    return case next of {\n        Some(slot) -> ({\n            thread.set_current_slot(slot);\n            case thread.owner_pid_at(slot) of {\n                Some(pid) -> ({\n                    Option<i32> pdbr = process.get_pdbr(pid);\n                    case pdbr of {\n                        Some(value) -> ({ mem.write_word(MMU_PDBR_ADDR, value); });\n                        None -> ({ debug.panic(\"scheduler: thread owner process is missing\"); });\n                    };\n                    mem.write_word(KERNEL_SP_ADDR, thread.saved_user_sp(slot));\n                });\n                None -> ({ install_kernel_space(); });\n            };\n            thread.make_running(slot);\n            charge_to(Some(slot));\n            thread.saved_kernel_sp(slot);\n        });\n        None -> ({\n            // Idle runs in the kernel's address space. The thread that just\n            // stopped may be the last of a process whose page tables the next\n            // reschedule frees, and idle can now wait for a long time.\n            install_kernel_space();\n            thread.set_idle();\n            charge_to(None);\n            g_idle_epoch = Some(thread.ready_epoch());\n            idle_sp;\n        });\n    };\n}\n\n/**\n * Blocks the current TCB until the next tick and schedules another context.\n * @param sp Saved interrupt-frame SP of the yielding TCB.\n * @return Saved kernel SP of the next context to resume.\n */\nexport i32 yield_until_tick(i32 sp) {\n    case thread.current_slot() of {\n        Some(current) -> ({ thread.sleep_until(current, g_irq_count + 1); });\n        None -> _;\n    };\n    return reschedule(sp);\n}\n\n/** @param mask Nonzero notification bits to arm on the current TCB. */\n@safe\nexport void arm_notification(i32 mask) {\n    case thread.current_slot() of {\n        Some(current) -> ({ thread.arm_notification(current, mask); });\n        None -> _;\n    };\n}\n\n/** @param mask Notification bits to clear from armed and pending state. */\nexport void disarm_notification(i32 mask) {\n    case thread.current_slot() of {\n        Some(current) -> ({ thread.disarm_notification(current, mask); });\n        None -> _;\n    };\n}\n\n/**\n * Returns immediately for pending bits or blocks the current TCB for a notification.\n * @param sp Saved syscall interrupt-frame SP.\n * @param mask Notification bits accepted by the caller.\n * @param notification_out Kernel pointer receiving immediately consumed bits.\n * @return sp for an immediate result, or the next scheduled context's SP after blocking.\n */\nexport i32 wait_notification(i32 sp, i32 mask, i32 *notification_out) {\n    *notification_out = 0;\n    if (mask == 0) { return sp; }\n    i32 current = case thread.current_slot() of {\n        Some(slot) -> slot;\n        None -> ({ return sp; });\n    };\n    i32 ready = thread.take_notification(current, mask);\n    if (ready) {\n        *notification_out = ready;\n        return sp;\n    }\n    // The frame gets its result before anything can wake it; the wake's\n    // replaces it (syscall.DispatchOutcome.parked).\n    irq_frame.set_syscall_return(sp, SyscallStatus::Ok, 0);\n    thread.block_notification(current, mask);\n    return reschedule(sp);\n}\n\n/**\n * Delivers notification bits to every TCB owned by a process.\n * @param pid Destination process.\n * @param mask Notification bits produced by the event source.\n */\nexport void notify_pid(Pid pid, i32 mask) {\n    i32 i = 0;\n    while (i < thread.high_water()) {\n        case thread.owner_pid_at(i) of {\n            Some(owner) -> ({ if (owner == pid) { thread.notify(i, mask); } });\n            None -> _;\n        };\n        i++;\n    }\n}\n\n/** @param mask Notification bits broadcast to every TCB that armed them. */\nexport void notify_armed(i32 mask) { thread.notify_all(mask); }\n\n/**\n * Waits, on the current kernel thread's own stack, until one of the bits\n * arrives or the deadline passes. Bits that arrived since the thread armed\n * them (arm_notification) return at once, so a loop that arms before it looks\n * at its queues loses nothing raised while it looked.\n * @param mask Notification bits to wait for.\n * @param deadline Absolute tick at which to give up, or zero for none.\n * @return The bits that arrived, or zero when the deadline came first.\n */\n@safe\nexport i32 await_notification(i32 mask, i32 deadline) {\n    i32 current = case thread.current_slot() of {\n        Some(slot) -> slot;\n        None -> ({ return 0; });\n    };\n    {\n        bool was_enabled = irq.save_disable();\n        defer irq.restore(was_enabled);\n        i32 ready = thread.take_notification(current, mask);\n        if (ready) { return ready; }\n        if (deadline != 0 && deadline <= g_irq_count) { return 0; }\n        thread.block_notification_until(current, mask, deadline);\n        charge_wait();\n    }\n    wait_in_wfi(current);\n    return thread.take_wake_result(current);\n}\n\n/**\n * Ends a process from outside it: an Alive process is a Zombie when this returns.\n * Its threads are switched out, so nothing is left to wait for and their stacks\n * can go at once. A process already Exiting finishes on its own next reschedule.\n * @param pid Process to end; the caller must not be one of its threads.\n * @param status Final status recorded in the Zombie.\n */\nexport void terminate(Pid pid, ProcessExitStatus status) {\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    if (!process.accepts_threads(pid)) { return; }\n    thread.exit_process_threads(pid, status);\n    // One of its threads may be waiting here. Its slot is about to be cleared\n    // and could be reused before the next reschedule would look at it.\n    case deferred_cleanup_slot of {\n        Some(retired) -> ({\n            bool owned = case thread.owner_pid_at(retired) of { Some(owner) -> owner == pid; None -> false; };\n            if (owned) { deferred_cleanup_slot = None; }\n        });\n        None -> _;\n    };\n    thread.finish_process_exit(pid);\n}\n\n/** Kernel-side sleep used outside the syscall frame path. */\n/**\n * Sleeps the current kernel context for at least the requested tick count.\n * Timer IRQ scheduling switches away while this function waits in WFI.\n * @param ticks_to_sleep Relative nonnegative scheduler tick count.\n */\n@safe\nexport void sleep(i32 ticks_to_sleep) {\n    i32 current = case thread.current_slot() of {\n        Some(slot) -> slot;\n        None -> ({ return; });\n    };\n    {\n        bool was_enabled = irq.save_disable();\n        defer irq.restore(was_enabled);\n        thread.sleep_until(current, g_irq_count + ticks_to_sleep);\n        charge_wait();\n    }\n    wait_in_wfi(current);\n}\n\n/**\n * Allocates a stack, builds an initial frame, and publishes a kernel TCB.\n * @param entry Non-returning kernel-thread entry function.\n * @param stack_bytes Requested kernel-stack allocation size.\n * @return Ok(global TCB slot), Err(OutOfMemory), or Err(TaskSlotFull).\n */\nexport Result<i32, SchedulerError> spawn_kernel_thread(fn() -> void entry, i32 stack_bytes) {\n    i32 slot = case thread.find_free_slot() of {\n        Some(value) -> value;\n        None -> ({ return Err(SchedulerError::TaskSlotFull); });\n    };\n    i32 stack = case heap.alloc(stack_bytes) of {\n        Ok(value) -> value;\n        Err(_) -> ({ return Err(SchedulerError::OutOfMemory); });\n    };\n    i32 sp = irq_frame.build_kernel(entry, stack + stack_bytes);\n    thread.publish_kernel(slot, sp, stack, stack_bytes);\n    return Ok(slot);\n}\n\n/** Initializes the TCB table and creates the scheduler's boot and idle contexts. */\nexport void init() {\n    thread.init();\n    mem.write_word(TIMER_ADDR, 0);\n    g_held = false;\n    i32 clock = mem.read_word(TIMER_ADDR);\n    g_clock_ticks = (clock >> CLOCK_SHIFT) & CLOCK_TICK_MASK;\n    g_clock_base = clock;\n    g_clock_charged = clock;\n    g_charge_to = Some(0); // the boot thread, below\n    g_irq_count = 0;\n    g_idle_time = 0;\n    g_kernel_time = 0;\n    deferred_cleanup_slot = None;\n    g_idle_epoch = None;\n\n    i32 idle_bytes = 8192;\n    i32 idle_stack = case heap.alloc(idle_bytes) of {\n        Ok(value) -> value;\n        Err(_) -> ({ debug.panic(\"scheduler: no memory for idle stack\"); 0; });\n    };\n    idle_sp = irq_frame.build_kernel(idle_main, idle_stack + idle_bytes);\n\n    thread.publish_boot(0);\n    thread.set_current_slot(0);\n    g_initialized = true;\n}\n","system/MyKernel/src/kernel/syscall.unsafe.mln":"namespace syscall;\n\nimport mem from \"@kernel/mm/mem.mln\";\nimport mmu from \"@kernel/mm/mmu.mln\";\nimport irq_frame from \"@kernel/arch/irq_frame.mln\";\nimport serial from \"@kernel/io/serial.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport process from \"process.mln\";\nimport { ProcessState, ProcessError } from \"process.mln\";\nimport thread from \"thread.mln\";\nimport { JoinOutcome } from \"thread.mln\";\nimport scheduler from \"scheduler.mln\";\nimport loader from \"loader.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { UserAddress } from \"@std/core/address.mln\";\nimport { MmuError } from \"@contracts/process/loader.contract.mln\";\nimport { SpawnError } from \"@contracts/process/spawn.contract.mln\";\nimport { Syscall, SyscallStatus } from \"@contracts/myos/syscall.contract.mln\";\nimport { OsServiceError } from \"@contracts/myos/services.contract.mln\";\nimport { Pid, ProcessExitStatus } from \"@contracts/process/control.contract.mln\";\nimport { ThreadSpawnArgs, ThreadError } from \"@contracts/process/thread.contract.mln\";\n\n/**\n * Failure reasons returned by recoverable, multi-step syscall operations.\n * These variants are consumed through Result<SyscallError> rather than being\n * accessed as bare cross-package enum members. InvalidDirectory and\n * UnalignedAddress are intentionally absent: sys_sbrk computes valid aligned\n * addresses from a live process, so either MMU error indicates a broken\n * kernel invariant and triggers a panic instead of a recoverable syscall error.\n */\nexport enum SyscallError {\n    NoProcess,      // No process is currently executing\n    OutOfMemory,    // Physical frame allocation failed\n    HeapOverflow,   // New heap break would collide with the stack\n    BadFd,          // Unsupported file descriptor\n    UnknownSyscall, // sys_nr doesn't match any dispatched syscall\n    SpawnFailed,    // Process launch failed; detailed reason is in SpawnError APIs\n}\n\n/**\n * Typed result of syscall dispatch, pairing the user-visible value with the\n * frame to resume. SYS_EXIT, SYS_YIELD, and SYS_WAIT_NOTIFICATION may choose\n * another frame through the scheduler.\n * @property next_sp Stack pointer of the context IRQ dispatch should resume.\n * @property status SyscallStatus written to the user's r1 register.\n * @property value Success value or error payload written to the user's r2 register.\n * @property parked The caller blocked. Its frame got a result before it did,\n *   and whatever wakes it writes the real one there, maybe before dispatch\n *   returns: IRQ dispatch must not write status and value over it.\n */\nexport struct DispatchOutcome {\n    i32 next_sp;\n    SyscallStatus status;\n    i32 value;\n    bool parked;\n};\n\n/**\n * Blocks the caller, which has just been put in a waiting state: its frame\n * gets Ok and zero first, then the scheduler runs, and a wake -- even one in\n * this very reschedule, such as a joined thread's cleanup -- replaces them.\n * @param sp Caller's saved syscall frame.\n * @return The outcome to resume with.\n */\nDispatchOutcome parked(i32 sp) {\n    irq_frame.set_syscall_return(sp, SyscallStatus::Ok, 0);\n    DispatchOutcome outcome;\n    outcome.status = SyscallStatus::Ok;\n    outcome.value = 0;\n    outcome.parked = true;\n    outcome.next_sp = scheduler.reschedule(sp);\n    return outcome;\n}\n\n/**\n * Converts a typed kernel syscall error into its stable positive status.\n * @param error Kernel syscall error variant.\n * @return Common SyscallStatus written to r1.\n */\nexport SyscallStatus error_status(SyscallError error) {\n    return case error of {\n        NoProcess -> SyscallStatus::NoProcess;\n        OutOfMemory -> SyscallStatus::OutOfMemory;\n        HeapOverflow -> SyscallStatus::HeapOverflow;\n        BadFd -> SyscallStatus::BadFileDescriptor;\n        UnknownSyscall -> SyscallStatus::UnknownSyscall;\n        SpawnFailed -> SyscallStatus::SpawnFailed;\n    };\n}\n\n/**\n * Converts one owned ThreadError into the complete register return envelope.\n * Matching once preserves move-only payloads while assigning both registers.\n * @param sp Saved interrupt-frame SP to resume after an immediate failure.\n * @param error Thread or futex domain error to expose to user space.\n * @return Dispatch outcome with positive status in r1 and detail in r2.\n */\nDispatchOutcome thread_error_outcome(i32 sp, ThreadError error) {\n    DispatchOutcome outcome;\n    outcome.parked = false;\n    outcome.next_sp = sp;\n    case error of {\n        ThreadError::NoFreeSlot -> ({ outcome.status = SyscallStatus::NoFreeThreadSlot; outcome.value = 0; });\n        ThreadError::OutOfMemory -> ({ outcome.status = SyscallStatus::OutOfMemory; outcome.value = 0; });\n        ThreadError::InvalidTid(value) -> ({ outcome.status = SyscallStatus::InvalidThreadId; outcome.value = value; });\n        ThreadError::JoinSelf -> ({ outcome.status = SyscallStatus::JoinSelf; outcome.value = 0; });\n        ThreadError::AlreadyJoined(value) -> ({ outcome.status = SyscallStatus::AlreadyJoined; outcome.value = value; });\n        ThreadError::WouldBlock -> ({ outcome.status = SyscallStatus::WouldBlock; outcome.value = 0; });\n        ThreadError::TimedOut -> ({ outcome.status = SyscallStatus::TimedOut; outcome.value = 0; });\n        ThreadError::BadAddress(value) -> ({ outcome.status = SyscallStatus::BadAddress; outcome.value = value; });\n        ThreadError::ProcessExiting -> ({ outcome.status = SyscallStatus::ProcessExiting; outcome.value = 0; });\n        ThreadError::InvalidEntry(value) -> ({ outcome.status = SyscallStatus::InvalidEntry; outcome.value = value; });\n        ThreadError::InvalidStackSize(value) -> ({ outcome.status = SyscallStatus::InvalidStackSize; outcome.value = value; });\n        ThreadError::UnexpectedStatus(value) -> ({ outcome.status = SyscallStatus::UnknownSyscall; outcome.value = value; });\n    };\n    return outcome;\n}\n\n/**\n * Converts a typed thread result into the two-register syscall envelope.\n * @param sp Saved syscall interrupt-frame SP.\n * @param result Successful integer result or typed ThreadError.\n * @return DispatchOutcome that resumes sp with status in r1 and value/detail in r2.\n */\nDispatchOutcome thread_result(i32 sp, Result<i32, ThreadError> result) {\n    DispatchOutcome outcome;\n    outcome.parked = false;\n    outcome.next_sp = sp;\n    case result of {\n        Ok(value) -> ({\n            outcome.status = SyscallStatus::Ok;\n            outcome.value = value;\n        });\n        Err(error) -> ({ return thread_error_outcome(sp, error); });\n    };\n    return outcome;\n}\n\n/**\n * Copies ThreadSpawnArgs from user memory and delegates validated creation.\n * The kernel stores only the copied value, never the caller's raw pointer.\n * @param args_addr Aligned user virtual address of a complete ThreadSpawnArgs.\n * @return Ok(new TID), or BadAddress, ProcessExiting, or a spawn validation error.\n */\nResult<i32, ThreadError> sys_thread_spawn(i32 args_addr) {\n    Pid pid = case thread.current_pid() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    i32 pdbr = case process.get_pdbr(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    if ((args_addr & 3) || !mmu.user_range_has_flags(pdbr, args_addr, 16, mmu.PTE_USER)) {\n        return Err(ThreadError::BadAddress(args_addr));\n    }\n    ThreadSpawnArgs args;\n    args.entry = case mmu.read_user_word(pdbr, args_addr) of { Some(v) -> v; None -> 0; };\n    args.arg0 = case mmu.read_user_word(pdbr, args_addr + 4) of { Some(v) -> v; None -> 0; };\n    args.arg1 = case mmu.read_user_word(pdbr, args_addr + 8) of { Some(v) -> v; None -> 0; };\n    args.stack_bytes = case mmu.read_user_word(pdbr, args_addr + 12) of { Some(v) -> v; None -> 0; };\n    return thread.spawn_user_thread(pid, args);\n}\n\ni32 PTE_USER_RW = 0x0B; // VALID | WRITABLE | USER\n\n// --- console and spawn hooks (MYOS-015) ---\n// The kernel owns the syscall boundary but not the desktop: where a\n// process's stdout goes and how a path becomes an executable image are\n// MyOS decisions. MyOS replaces these at boot. Until then the console is the\n// serial port, and nothing can be spawned or served.\n\n/** The console until MyOS installs its own: every byte goes to the serial port. */\ni32 serial_write(Pid pid, UserAddress buf, i32 count) {\n    i32 i = 0;\n    while (i < count) {\n        serial.putc(mem.read_byte((i32)buf.plus(i)));\n        i++;\n    }\n    return count;\n}\n\n/** The console until MyOS installs its own: whatever the serial port has waiting. */\ni32 serial_read(Pid pid, UserAddress buf, i32 count) {\n    i32 i = 0;\n    while (i < count) {\n        Option<i32> input = serial.read_input();\n        bool has_input = case input of {\n            Some(c) -> ({\n                mem.write_byte((i32)buf.plus(i), c);\n                i++;\n                true;\n            });\n            None -> false;\n        };\n        if (!has_input) { break; }\n    }\n    return i;\n}\n\nResult<Pid, SpawnError> no_spawn(UserAddress path) {\n    return Err(SpawnError::NoHandler);\n}\n\nResult<i32, OsServiceError> no_os_services(Pid pid, i32 service, UserAddress args) {\n    return Err(OsServiceError::UnknownService(service));\n}\n\nfn(Pid pid, UserAddress buf, i32 count) -> i32 g_console_write = serial_write;\nfn(Pid pid, UserAddress buf, i32 count) -> i32 g_console_read = serial_read;\nfn(UserAddress path) -> Result<Pid, SpawnError> g_spawn_handler = no_spawn;\nfn(Pid pid, i32 service, UserAddress args) -> Result<i32, OsServiceError> g_os_handler = no_os_services;\n\n/**\n * Registers the OS_CALL handler: every service the OS offers a process\n * beyond the kernel's own syscalls -- the UI protocol, the filesystem,\n * process control -- goes through one syscall, OS_CALL(service, args).\n * `service` is the wire value as the process sent it, known or not. The\n * handler reads and writes `args` through the process's page tables, which\n * are active for the syscall's duration.\n * @param handler Function taking (pid, service, args).\n */\nexport void set_os_handler(fn(Pid pid, i32 service, UserAddress args) -> Result<i32, OsServiceError> handler) {\n    g_os_handler = handler;\n}\n\n/**\n * Registers OS-level console I/O hook functions for stdout/stdin redirection.\n * @param write_handler Function taking (pid, buf, count) and returning bytes written.\n * @param read_handler Function taking (pid, buf, count) and returning bytes read.\n */\nexport void set_console(fn(Pid pid, UserAddress buf, i32 count) -> i32 write_handler,\n                        fn(Pid pid, UserAddress buf, i32 count) -> i32 read_handler) {\n    g_console_write = write_handler;\n    g_console_read = read_handler;\n}\n\n/**\n * Registers the OS-level process spawning hook for SYS_SPAWN.\n * @param handler Function taking the path and returning the new process ID.\n */\nexport void set_spawn_handler(fn(UserAddress path) -> Result<Pid, SpawnError> handler) {\n    g_spawn_handler = handler;\n}\n\n/**\n * Terminates the current process with an application-supplied exit code.\n * @param code Arbitrary application exit code, stored as ProcessExitStatus::Code.\n */\nexport void sys_exit(i32 code) {\n    ProcessExitStatus status = ProcessExitStatus::Code(code);\n    sys_exit_status(status);\n}\n\n/**\n * Terminates the current process with a typed kernel or application exit status.\n * @param status Process exit status to preserve in the Zombie state.\n */\nexport void sys_exit_status(ProcessExitStatus status) {\n    Pid pid = case thread.current_pid() of {\n        Some(value) -> value;\n        None -> ({ return; });\n    };\n    thread.exit_process_threads(pid, status);\n}\n\n/**\n * Writes data from a user buffer to an open file descriptor (e.g. stdout/stderr).\n * @param fd File descriptor index (1 = stdout, 2 = stderr).\n * @param buf Virtual memory address of source buffer.\n * @param count Number of bytes to write.\n * @return Ok(written), Err(BadFd) for an unsupported fd, or Err(NoProcess) outside a process.\n */\nexport Result<i32, SyscallError> sys_write(i32 fd, UserAddress buf, i32 count) {\n    if (count <= 0) {\n        return Ok(0);\n    }\n    if (fd == 1 || fd == 2) {\n        Pid pid = case thread.current_pid() of {\n            Some(value) -> value;\n            None -> ({ return Err(SyscallError::NoProcess); });\n        };\n        return Ok(g_console_write(pid, buf, count));\n    }\n    SyscallError cause = BadFd;\n    return Err(cause);\n}\n\n/**\n * Reads data into a user buffer from an open file descriptor (e.g. stdin).\n * @param fd File descriptor index (0 = stdin).\n * @param buf Virtual memory address of destination buffer.\n * @param count Maximum number of bytes to read.\n * @return Ok(read_bytes), Err(BadFd) for an unsupported fd, or Err(NoProcess) outside a process.\n */\nexport Result<i32, SyscallError> sys_read(i32 fd, UserAddress buf, i32 count) {\n    if (count <= 0) {\n        return Ok(0);\n    }\n    if (fd == 0) {\n        Pid pid = case thread.current_pid() of {\n            Some(value) -> value;\n            None -> ({ return Err(SyscallError::NoProcess); });\n        };\n        return Ok(g_console_read(pid, buf, count));\n    }\n    SyscallError cause = BadFd;\n    return Err(cause);\n}\n\n/**\n * Starts a new process from the executable file at the specified path.\n * @param path Pointer to null-terminated file path string.\n * @return Ok(pid) on success, or Err(NoProcess), Err(UnknownSyscall), or Err(SpawnFailed).\n */\nexport Result<i32, SyscallError> sys_spawn(UserAddress path) {\n    Option<Pid> current = thread.current_pid();\n    case current of {\n        Some(_) -> _;\n        None -> ({ return Err(SyscallError::NoProcess); });\n    };\n    Result<Pid, SpawnError> spawned = g_spawn_handler(path);\n    return case spawned of {\n        Ok(pid) -> Ok((i32)pid);\n        Err(_) -> Err(SyscallError::SpawnFailed);\n    };\n}\n\n/**\n * Adjusts the process's data segment break, allocating and mapping new pages as needed.\n * @param increment Number of bytes to expand the heap by (0 queries current break).\n * @return Ok(prev_brk) with previous heap break on success, or Err(SyscallError) on error.\n */\nexport Result<i32, SyscallError> sys_sbrk(i32 increment) {\n    Pid pid = case thread.current_pid() of {\n        Some(current) -> current;\n        None -> ({ return Err(SyscallError::NoProcess); });\n    };\n    i32 cur_brk = case process.get_heap_break(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(SyscallError::NoProcess); });\n    };\n    if (increment == 0) {\n        return Ok(cur_brk);\n    }\n    if (increment < 0) {\n        // Shrinking not supported yet\n        return Ok(cur_brk);\n    }\n\n    i32 new_brk = cur_brk + increment;\n    if (new_brk >= thread.USER_STACK_REGION_BASE) {\n        return Err(SyscallError::HeapOverflow);\n    }\n\n    // Map pages if new_brk crosses page boundaries\n    i32 cur_page = (cur_brk + 4095) & ~4095;\n    i32 target_page = (new_brk + 4095) & ~4095;\n    i32 pd = case process.get_pdbr(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(SyscallError::NoProcess); });\n    };\n\n    i32 first_new_page = cur_page;\n    while (cur_page < target_page) {\n        i32 frame = case mmu.alloc_page() of {\n            Some(f) -> f;\n            None -> ({\n                return Err(SyscallError::OutOfMemory);\n            });\n        };\n        Result<_, MmuError> map_res = mmu.map_page(pd, cur_page, frame, PTE_USER_RW);\n        case map_res of {\n            Ok(_) -> _;\n            Err(MmuError::AllocFailed) -> ({\n                mmu.free_frame(frame);\n                i32 rollback = first_new_page;\n                while (rollback < cur_page) {\n                    i32 old_frame = case mmu.unmap_page(pd, rollback) of { Ok(value) -> value; Err(_) -> 0; };\n                    if (old_frame != 0) { mmu.free_frame(old_frame); }\n                    rollback = rollback + 4096;\n                }\n                return Err(SyscallError::OutOfMemory);\n            });\n            Err(e) -> ({\n                mmu.free_frame(frame);\n                i32 rollback = first_new_page;\n                while (rollback < cur_page) {\n                    i32 old_frame = case mmu.unmap_page(pd, rollback) of { Ok(value) -> value; Err(_) -> 0; };\n                    if (old_frame != 0) { mmu.free_frame(old_frame); }\n                    rollback = rollback + 4096;\n                }\n                // InvalidDirectory/UnalignedAddress here mean a kernel\n                // invariant broke: `pd` comes from a live process's pdbr\n                // (always set from a real create_page_directory() success),\n                // and `cur_page`/`frame` are always page-aligned by\n                // construction. Not a recoverable syscall error -- panic\n                // while we still have the pid for the diagnostic.\n                debug.printf(\"sys_sbrk: unexpected MMU error for pid=%d\\n\", (i32)pid);\n                debug.panic(\"kernel invariant broken -- MMU rejected an address sys_sbrk computed itself\");\n            });\n        };\n        cur_page = cur_page + 4096;\n    }\n\n    Result<_, ProcessError> set_heap_break = process.set_heap_break(pid, new_brk);\n    case set_heap_break of {\n        Ok(_) -> _;\n        Err(_) -> ({ return Err(SyscallError::NoProcess); });\n    };\n    return Ok(cur_brk);\n}\n\n/**\n * Packages a syscall result into a typed DispatchOutcome for IRQ dispatch.\n * @param sp Stack pointer to restore upon syscall return.\n * @param result Typed syscall result.\n * @return Ok(DispatchOutcome) that resumes sp with the status in r1 and the\n *         value in r2; an error becomes its SyscallStatus with r2 zero.\n */\nResult<DispatchOutcome, SyscallError> resume_after_syscall(i32 sp, Result<i32, SyscallError> result) {\n    DispatchOutcome outcome;\n    outcome.parked = false;\n    outcome.next_sp = sp;\n    case result of {\n        Ok(value) -> ({\n            outcome.status = SyscallStatus::Ok;\n            outcome.value = value;\n        });\n        Err(error) -> ({\n            outcome.status = error_status(error);\n            outcome.value = 0;\n        });\n    };\n    return Ok(outcome);\n}\n\n/**\n * Top-level system call dispatcher called from irq_dispatch.\n *\n * Decodes the syscall number and arguments from the saved stack frame and executes the corresponding service.\n * @param sp Stack pointer of saved user interrupt frame.\n * @return Ok(DispatchOutcome) describing next SP and return value, or Err(SyscallError).\n */\nexport Result<DispatchOutcome, SyscallError> dispatch(i32 sp) {\n    i32 sys_nr = irq_frame.syscall_number(sp);\n    i32 arg1   = irq_frame.syscall_arg1(sp);\n    i32 arg2   = irq_frame.syscall_arg2(sp);\n    i32 arg3   = irq_frame.syscall_arg3(sp);\n    if (sys_nr == Syscall::EXIT) {\n        sys_exit(arg1);\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = scheduler.reschedule(sp);\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = 0;\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::READ) {\n        Result<i32, SyscallError> result = sys_read(arg1, UserAddress(arg2), arg3);\n        return resume_after_syscall(sp, result);\n    }\n    if (sys_nr == Syscall::WRITE) {\n        Result<i32, SyscallError> result = sys_write(arg1, UserAddress(arg2), arg3);\n        return resume_after_syscall(sp, result);\n    }\n    if (sys_nr == Syscall::SBRK) {\n        Result<i32, SyscallError> result = sys_sbrk(arg1);\n        return resume_after_syscall(sp, result);\n    }\n    if (sys_nr == Syscall::YIELD) {\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = scheduler.yield_until_tick(sp);\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = 0;\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::SPAWN) {\n        Result<i32, SyscallError> result = sys_spawn(UserAddress(arg1));\n        return resume_after_syscall(sp, result);\n    }\n    if (sys_nr == Syscall::OS_CALL) {\n        Pid pid = case thread.current_pid() of {\n            Some(value) -> value;\n            None -> ({ return Err(SyscallError::NoProcess); });\n        };\n        Result<i32, OsServiceError> result = g_os_handler(pid, arg1, UserAddress(arg2));\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = sp;\n        case result of {\n            Ok(value) -> ({\n                outcome.status = SyscallStatus::Ok;\n                outcome.value = value;\n            });\n            Err(OsServiceError::UnknownService(service)) -> ({\n                outcome.status = SyscallStatus::UnknownService;\n                outcome.value = service;\n            });\n        };\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::WAIT_NOTIFICATION) {\n        DispatchOutcome outcome;\n        i32 notification = 0;\n        outcome.next_sp = scheduler.wait_notification(sp, arg1, &notification);\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = notification;\n        // Nothing was ready, so it blocked (wait_notification parked the frame).\n        outcome.parked = arg1 != 0 && notification == 0;\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::THREAD_SPAWN) {\n        Result<i32, ThreadError> result = sys_thread_spawn(arg1);\n        return Ok(thread_result(sp, result));\n    }\n    if (sys_nr == Syscall::THREAD_EXIT) {\n        thread.exit_current_thread(arg1);\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = scheduler.reschedule(sp);\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = 0;\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::THREAD_JOIN) {\n        Result<JoinOutcome, ThreadError> joined = thread.join_thread(arg1);\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = sp;\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = 0;\n        case joined of {\n            Ok(join_outcome) -> ({\n                case join_outcome of {\n                    JoinOutcome::Completed(code) -> ({ outcome.value = code; });\n                    JoinOutcome::Waiting -> ({ return Ok(parked(sp)); });\n                };\n            });\n            Err(error) -> ({ return Ok(thread_error_outcome(sp, error)); });\n        };\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::THREAD_SELF) {\n        Result<i32, ThreadError> result = case thread.current_tid() of {\n            Some(tid) -> Ok(tid);\n            None -> Err(ThreadError::InvalidTid(0));\n        };\n        return Ok(thread_result(sp, result));\n    }\n    if (sys_nr == Syscall::FUTEX_WAIT) {\n        Result<bool, ThreadError> waited = thread.futex_wait(arg1, arg2, arg3, scheduler.ticks());\n        DispatchOutcome outcome;\n        outcome.parked = false;\n        outcome.next_sp = sp;\n        outcome.status = SyscallStatus::Ok;\n        outcome.value = 0;\n        case waited of {\n            Ok(immediate) -> ({ if (!immediate) { return Ok(parked(sp)); } });\n            Err(error) -> ({ return Ok(thread_error_outcome(sp, error)); });\n        };\n        return Ok(outcome);\n    }\n    if (sys_nr == Syscall::FUTEX_WAKE) {\n        Result<i32, ThreadError> result = thread.futex_wake(arg1, arg2);\n        return Ok(thread_result(sp, result));\n    }\n\n    return Err(SyscallError::UnknownSyscall);\n}\n","system/MyKernel/src/kernel/thread.unsafe.mln":"namespace thread;\n\nimport { Option } from \"@std/core/option.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport kernel_config from \"kernel_config.mln\";\nimport process from \"process.mln\";\nimport { ProcessState, ProcessError } from \"process.mln\";\nimport heap from \"@kernel/mm/heap.mln\";\nimport mmu from \"@kernel/mm/mmu.mln\";\nimport irq_frame from \"@kernel/arch/irq_frame.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport { MmuError } from \"@contracts/process/loader.contract.mln\";\nimport { Pid, ProcessExitStatus } from \"@contracts/process/control.contract.mln\";\nimport { ThreadSpawnArgs, ThreadError } from \"@contracts/process/thread.contract.mln\";\nimport { SyscallStatus } from \"@contracts/myos/syscall.contract.mln\";\n\n/**\n * Resource owner of a schedulable execution context.\n * @property Kernel Context owned by the kernel and not associated with a PID.\n * @property User Context sharing the address space and resources of the carried PID.\n */\nexport enum ThreadOwner {\n    Kernel,\n    User(Pid),\n}\n\n/**\n * Kernel stack backing one TCB's interrupt and syscall execution.\n * @property base Allocation base, or zero for the borrowed boot stack.\n * @property bytes Size of the allocation in bytes.\n * @property owned Whether deferred cleanup must return base to the kernel heap.\n */\nexport struct KernelStack {\n    i32 base;\n    i32 bytes;\n    bool owned;\n};\n\n/**\n * User-stack mapping owned by one user TCB.\n * @property slot Process-local fixed virtual-address slot index.\n * @property mapped_base Lowest mapped user virtual address in the slot.\n * @property mapped_bytes Number of mapped bytes, excluding the guard page.\n */\nexport struct UserStack {\n    i32 slot;\n    i32 mapped_base;\n    i32 mapped_bytes;\n};\n\n/**\n * Timer wait registration stored in a Blocked TCB.\n * @property deadline_tick First scheduler tick at which the TCB may run again.\n */\nexport struct SleepWait {\n    i32 deadline_tick;\n};\n\n/**\n * Notification wait registration stored in a Blocked TCB.\n * @property mask Bit set accepted by the waiter.\n * @property deadline_tick Tick at which the wait gives up with no bits, or zero for none.\n * @property syscall The waiter is in a syscall, so its result goes to the saved frame;\n *   a kernel thread waits on its own stack and reads it with take_wake_result.\n */\nexport struct NotificationWait {\n    i32 mask;\n    i32 deadline_tick;\n    bool syscall;\n};\n\n/**\n * Notification bits raised by the kernel for kernel threads. A thread's bits\n * are shared with the app transport's TransportSignal (1, 2, 4) and the OS's\n * ProcessSignal (8, 16), so these start above them.\n */\nexport enum KernelSignal {\n    INPUT = 32,          // the keyboard or mouse queue got an event\n    PROCESS_ENDED = 64,  // a process became a Zombie\n    SERIAL = 128,        // the serial input queue got a character\n    SERVICE = 256,       // the OS queued work for a kernel thread's own loop\n    AUTOMATION = 512,    // the host posted a request on the automation bridge\n}\n\n/**\n * Join registration stored in the waiting TCB.\n * @property target_tid Stable TID whose exit is being awaited.\n */\nexport struct JoinWait {\n    i32 target_tid;\n};\n\n/** Result of attempting to join a thread before the scheduler is invoked. */\nexport enum JoinOutcome {\n    Completed(i32),\n    Waiting,\n}\n\n/**\n * Futex registration stored in the waiting TCB.\n * @property addr Aligned user virtual address; the owner PID completes the futex key.\n * @property deadline_tick Absolute timeout tick, or zero for no timeout.\n * @property sequence Monotonic registration order used to provide FIFO wakeup.\n */\nexport struct FutexWait {\n    i32 addr;\n    i32 deadline_tick;\n    i32 sequence;\n};\n\n/** Exactly one reason is attached to a blocked thread. */\nexport enum WaitReason {\n    Sleep(SleepWait),\n    Notification(NotificationWait),\n    Join(JoinWait),\n    Futex(FutexWait),\n}\n\n/** Lifecycle of one schedulable execution context. */\nexport enum ThreadState {\n    Runnable,\n    Running,\n    Blocked(WaitReason),\n    Exiting(i32),\n    Zombie(i32),\n}\n\n/**\n * Kernel Thread Control Block and single source of truth for execution state.\n * @property tid Stable positive thread identifier, independent of table slot reuse.\n * @property owner Kernel ownership or the PID whose resources are shared.\n * @property state Scheduling, blocking, exit, or retained-Zombie state.\n * @property saved_kernel_sp Interrupt-frame SP restored by irq_resume.\n * @property saved_user_sp User SP restored through KERNEL_SP; zero for kernel threads.\n * @property kernel_stack Kernel stack allocation or borrowed boot-stack descriptor.\n * @property user_stack User mapping owned by a user thread; None for kernel threads.\n * @property joiner_tid Sole registered joiner TID, if one exists.\n * @property notification_pending Armed notification bits already delivered.\n * @property notification_armed Notification bits this TCB currently accepts.\n * @property wake_result Success value or error payload installed in syscall r2 on wake.\n */\nexport struct Thread {\n    i32 tid;\n    ThreadOwner owner;\n    ThreadState state;\n    i32 saved_kernel_sp;\n    i32 saved_user_sp;\n    KernelStack kernel_stack;\n    Option<UserStack> user_stack;\n    Option<i32> joiner_tid;\n    i32 notification_pending;\n    i32 notification_armed;\n    i32 wake_result;\n};\n\nOption<Thread> g_threads[256];\ni32 g_thread_slot_high_water = 0;\ni32 g_next_tid = 1;\ni32 g_current_thread_slot = -1;\ni32 g_next_wait_sequence = 1;\n\n/**\n * Allocates a positive TID that is not used by any published TCB.\n * @return A stable nonzero TID; panics if a free slot has no representable TID.\n */\ni32 allocate_tid() {\n    i32 candidate = g_next_tid;\n    i32 checked = 0;\n    while (checked <= kernel_config.MAX_THREADS) {\n        if (candidate <= 0) { candidate = 1; }\n        bool used = case slot_for_tid(candidate) of { Some(_) -> true; None -> false; };\n        if (!used) {\n            g_next_tid = candidate + 1;\n            if (g_next_tid <= 0) { g_next_tid = 1; }\n            return candidate;\n        }\n        candidate++;\n        checked++;\n    }\n    debug.panic(\"thread: no TID available for a free TCB slot\");\n    return 0;\n}\n\n// The earliest tick at which a sleep, a futex timeout or a notification\n// deadline falls due, or None when no thread waits on one. A wait that ends\n// sooner (a notification, a futex wake) leaves it standing; the scan it brings\n// about only finds nothing to do.\nOption<i32> g_next_due;\n\n/** Clears the TCB table and resets thread, scheduler-slot, and wait IDs. */\nexport void init() {\n    i32 i = 0;\n    while (i < kernel_config.MAX_THREADS) {\n        Option<Thread> empty = None;\n        g_threads[i] = empty;\n        i++;\n    }\n    g_thread_slot_high_water = 0;\n    g_next_tid = 1;\n    g_current_thread_slot = -1;\n    g_next_wait_sequence = 1;\n    g_next_due = None;\n}\n\n/** @return One past the highest TCB slot that may currently be occupied. */\nexport i32 high_water() { return g_thread_slot_high_water; }\n\n/** @return Current scheduler slot, or None while the idle context runs. */\nexport Option<i32> current_slot() {\n    if (g_current_thread_slot < 0) { return None; }\n    return Some(g_current_thread_slot);\n}\n\n/**\n * Records the scheduler slot that is currently executing.\n * @param slot Occupied TCB slot.\n */\nexport void set_current_slot(i32 slot) { g_current_thread_slot = slot; }\n\n// Counts the times a TCB became Runnable from outside the scheduler's own\n// switch-out: published, woken, timed out. While it holds still, a scheduler\n// that found nothing to run need not look again.\ni32 g_ready_epoch = 0;\n\n/** @return How many times a TCB has been made Runnable by a wake or a publish. */\nexport i32 ready_epoch() { return g_ready_epoch; }\n\n// Keeps `tick` if it comes before every deadline noted so far.\nvoid note_due(i32 tick) {\n    bool sooner = case g_next_due of { Some(due) -> tick < due; None -> true; };\n    if (sooner) { g_next_due = Some(tick); }\n}\n\n/** @return The earliest tick a sleep, futex timeout or notification deadline\n * may fall due at, or None when no thread waits on one. It may come and wake\n * nobody, when the wait ended sooner. */\nexport Option<i32> next_due() { return g_next_due; }\n\n/** Records that the idle fallback context is executing. */\nexport void set_idle() { g_current_thread_slot = -1; }\n\n/**\n * Tests whether a slot contains a published TCB below the high-water mark.\n * @param slot Global TCB table index.\n * @return true when the slot contains Some(Thread); otherwise false.\n */\nexport bool occupied(i32 slot) {\n    if (slot < 0 || slot >= g_thread_slot_high_water) { return false; }\n    return case g_threads[slot] of { Some(_) -> true; None -> false; };\n}\n\n/** @return The first unused global TCB slot, or None when the table is full. */\nexport Option<i32> find_free_slot() {\n    i32 i = 0;\n    while (i < kernel_config.MAX_THREADS) {\n        bool free = case g_threads[i] of { None -> true; Some(_) -> false; };\n        if (free) { return Some(i); }\n        i++;\n    }\n    return None;\n}\n\n/**\n * Publishes a fully initialized TCB and advances the table high-water mark.\n * @param slot Previously verified free TCB table index.\n * @param value Complete TCB value whose resources are ready for scheduling.\n */\nvoid publish_at(i32 slot, Thread value) {\n    g_ready_epoch++;\n    Option<Thread> entry = Some(value);\n    g_threads[slot] = entry;\n    if (slot >= g_thread_slot_high_water) {\n        g_thread_slot_high_water = slot + 1;\n    }\n}\n\n/**\n * Registers the boot context, whose kernel stack is borrowed.\n * @param slot Free TCB slot reserved for the boot context.\n */\nexport void publish_boot(i32 slot) {\n    Thread value = Thread {\n        tid: allocate_tid(),\n        owner: ThreadOwner::Kernel,\n        state: ThreadState::Runnable,\n        saved_kernel_sp: 0,\n        saved_user_sp: 0,\n        kernel_stack: KernelStack { base: 0, bytes: 0, owned: false },\n        user_stack: None,\n        joiner_tid: None,\n        notification_pending: 0,\n        notification_armed: 0,\n        wake_result: 0,\n    };\n    publish_at(slot, value);\n}\n\n/**\n * Publishes a fully constructed kernel thread.\n * @param slot Free global TCB slot.\n * @param saved_sp Initial interrupt-frame stack pointer.\n * @param stack_base Base of the owned kernel-stack allocation.\n * @param stack_bytes Kernel-stack allocation size in bytes.\n * @return Newly allocated stable TID.\n */\nexport i32 publish_kernel(i32 slot, i32 saved_sp, i32 stack_base, i32 stack_bytes) {\n    i32 tid = allocate_tid();\n    Thread value = Thread {\n        tid: tid,\n        owner: ThreadOwner::Kernel,\n        state: ThreadState::Runnable,\n        saved_kernel_sp: saved_sp,\n        saved_user_sp: 0,\n        kernel_stack: KernelStack { base: stack_base, bytes: stack_bytes, owned: true },\n        user_stack: None,\n        joiner_tid: None,\n        notification_pending: 0,\n        notification_armed: 0,\n        wake_result: 0,\n    };\n    publish_at(slot, value);\n    return tid;\n}\n\n/**\n * Publishes a fully constructed user thread.\n * @param slot Free global TCB slot.\n * @param pid Alive owner process.\n * @param saved_kernel_sp Initial interrupt-frame stack pointer.\n * @param saved_user_sp Initial user stack pointer.\n * @param kernel_stack Owned kernel-stack descriptor.\n * @param user_stack Owned user-stack mapping descriptor.\n * @return Newly allocated stable TID.\n */\nexport i32 publish_user(\n    i32 slot,\n    Pid pid,\n    i32 saved_kernel_sp,\n    i32 saved_user_sp,\n    KernelStack kernel_stack,\n    UserStack user_stack\n) {\n    i32 tid = allocate_tid();\n    Thread value = Thread {\n        tid: tid,\n        owner: ThreadOwner::User(pid),\n        state: ThreadState::Runnable,\n        saved_kernel_sp: saved_kernel_sp,\n        saved_user_sp: saved_user_sp,\n        kernel_stack: kernel_stack,\n        user_stack: Some(user_stack),\n        joiner_tid: None,\n        notification_pending: 0,\n        notification_armed: 0,\n        wake_result: 0,\n    };\n    publish_at(slot, value);\n    return tid;\n}\n\n/**\n * Returns the stable TID stored in a scheduler slot.\n * @param slot Global TCB table index.\n * @return Some(TID) for an occupied slot; otherwise None.\n */\nexport Option<i32> tid_at(i32 slot) {\n    if (!occupied(slot)) { return None; }\n    return case g_threads[slot] of { Some(t) -> Some(t.tid); None -> None; };\n}\n\n/**\n * Resolves a stable TID to its current scheduler slot.\n * @param tid Positive stable thread identifier.\n * @return Some(slot) while the TCB is retained; otherwise None.\n */\nexport Option<i32> slot_for_tid(i32 tid) {\n    if (tid <= 0) { return None; }\n    i32 i = 0;\n    while (i < g_thread_slot_high_water) {\n        case g_threads[i] of {\n            Some(t) -> ({ if (t.tid == tid) { return Some(i); } });\n            None -> _;\n        };\n        i++;\n    }\n    return None;\n}\n\n/**\n * Resolves the process owner of a TCB slot.\n * @param slot Global TCB table index.\n * @return Some(PID) for a user TCB; None for kernel or empty slots.\n */\nexport Option<Pid> owner_pid_at(i32 slot) {\n    if (!occupied(slot)) { return None; }\n    return case g_threads[slot] of {\n        Some(t) -> case t.owner of { User(pid) -> Some(pid); Kernel -> None; };\n        None -> None;\n    };\n}\n\n/** @return Current user PID derived from the TCB, or None in a kernel/idle context. */\nexport Option<Pid> current_pid() { return owner_pid_at(g_current_thread_slot); }\n\n/** @return Stable TID of the current TCB, or None while idle. */\nexport Option<i32> current_tid() {\n    if (g_current_thread_slot < 0) { return None; }\n    return tid_at(g_current_thread_slot);\n}\n\n/**\n * Tests whether a TCB can be selected by the scheduler.\n * @param slot Global TCB table index.\n * @return true only for ThreadState::Runnable.\n */\nexport bool runnable(i32 slot) {\n    if (!occupied(slot)) { return false; }\n    return case g_threads[slot] of {\n        Some(t) -> case t.state of { Runnable -> true; _ -> false; };\n        None -> false;\n    };\n}\n\n/**\n * Tests whether a TCB is blocked on a WaitReason.\n * @param slot Global TCB table index.\n * @return true only for ThreadState::Blocked(_).\n */\nexport bool blocked(i32 slot) {\n    if (!occupied(slot)) { return false; }\n    return case g_threads[slot] of {\n        Some(t) -> case t.state of { Blocked(_) -> true; _ -> false; };\n        None -> false;\n    };\n}\n\n/**\n * Marks the selected TCB as the CPU's Running context.\n * @param slot Occupied global TCB table index selected by the scheduler.\n */\nexport void make_running(i32 slot) {\n    if (!occupied(slot)) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({ t.state = ThreadState::Running; });\n        None -> _;\n    };\n}\n\n/**\n * Saves a switched-out context and makes a still-live Running TCB Runnable.\n * Blocked and Exiting states are preserved.\n * @param slot TCB slot being switched out.\n * @param kernel_sp Saved interrupt-frame SP on the thread's kernel stack.\n * @param user_sp Hardware-saved user SP; ignored for kernel threads.\n */\nexport void switch_out(i32 slot, i32 kernel_sp, i32 user_sp) {\n    if (!occupied(slot)) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({\n            t.saved_kernel_sp = kernel_sp;\n            case t.owner of { User(_) -> ({ t.saved_user_sp = user_sp; }); Kernel -> _; };\n            case t.state of { Running -> ({ t.state = ThreadState::Runnable; }); _ -> _; };\n        });\n        None -> _;\n    };\n}\n\n/**\n * @param slot Occupied global TCB table index.\n * @return Saved interrupt-frame SP, or zero for an empty slot.\n */\nexport i32 saved_kernel_sp(i32 slot) {\n    return case g_threads[slot] of { Some(t) -> t.saved_kernel_sp; None -> 0; };\n}\n\n/**\n * @param slot Occupied global TCB table index.\n * @return Saved user SP, or zero for kernel/empty slots.\n */\nexport i32 saved_user_sp(i32 slot) {\n    return case g_threads[slot] of { Some(t) -> t.saved_user_sp; None -> 0; };\n}\n\n/**\n * @param slot Global TCB table index.\n * @return Some(state) for an occupied slot; otherwise None.\n */\nexport Option<ThreadState> state_at(i32 slot) {\n    if (!occupied(slot)) { return None; }\n    return case g_threads[slot] of { Some(t) -> Some(t.state); None -> None; };\n}\n\n/**\n * @param slot Global TCB table index.\n * @return true only when the TCB is in ThreadState::Exiting(_).\n */\nexport bool exiting(i32 slot) {\n    if (!occupied(slot)) { return false; }\n    return case g_threads[slot] of {\n        Some(t) -> case t.state of { ThreadState::Exiting(_) -> true; _ -> false; };\n        None -> false;\n    };\n}\n\n/**\n * Blocks a TCB until the scheduler reaches the specified tick.\n * @param slot Occupied global TCB table index.\n * @param deadline Absolute scheduler tick at which the wait expires.\n */\nexport void sleep_until(i32 slot, i32 deadline) {\n    if (!occupied(slot)) { return; }\n    note_due(deadline);\n    SleepWait wait = SleepWait { deadline_tick: deadline };\n    case g_threads[slot] of {\n        Some(t) -> ({ t.state = ThreadState::Blocked(WaitReason::Sleep(wait)); });\n        None -> _;\n    };\n}\n\n/**\n * Arms notification bits for one TCB without blocking it.\n * @param slot Occupied global TCB table index.\n * @param mask Nonzero set of notification bits to accept.\n */\nexport void arm_notification(i32 slot, i32 mask) {\n    if (!occupied(slot) || mask == 0) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({ t.notification_armed = t.notification_armed | mask; });\n        None -> _;\n    };\n}\n\n/**\n * Clears armed and pending notification bits for one TCB.\n * @param slot Occupied global TCB table index.\n * @param mask Notification bits to clear.\n */\nexport void disarm_notification(i32 slot, i32 mask) {\n    if (!occupied(slot) || mask == 0) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({\n            t.notification_armed = t.notification_armed & (~mask);\n            t.notification_pending = t.notification_pending & (~mask);\n        });\n        None -> _;\n    };\n}\n\n/**\n * Arms a mask, then consumes any matching pending notification bits.\n * @param slot Occupied global TCB table index.\n * @param mask Notification bits accepted by the caller.\n * @return Matching pending bits, or zero when no notification is ready.\n */\nexport i32 take_notification(i32 slot, i32 mask) {\n    if (!occupied(slot) || mask == 0) { return 0; }\n    return case g_threads[slot] of {\n        Some(t) -> ({\n            t.notification_armed = t.notification_armed | mask;\n            i32 ready = t.notification_pending & mask;\n            if (ready) {\n                t.notification_pending = t.notification_pending & (~ready);\n                t.notification_armed = t.notification_armed & (~mask);\n            }\n            ready;\n        });\n        None -> 0;\n    };\n}\n\n/**\n * Blocks a TCB until one of the requested notification bits is delivered.\n * @param slot Occupied global TCB table index.\n * @param mask Notification bits accepted by the waiter.\n */\nexport void block_notification(i32 slot, i32 mask) {\n    if (!occupied(slot)) { return; }\n    NotificationWait wait = NotificationWait { mask: mask, deadline_tick: 0, syscall: true };\n    case g_threads[slot] of {\n        Some(t) -> ({ t.state = ThreadState::Blocked(WaitReason::Notification(wait)); });\n        None -> _;\n    };\n}\n\n/**\n * Blocks a kernel thread, waiting on its own stack, until a requested bit is\n * delivered or the deadline passes. take_wake_result tells which: the bits,\n * or zero for the deadline.\n * @param slot Occupied global TCB table index.\n * @param mask Notification bits accepted by the waiter.\n * @param deadline Absolute tick at which to give up, or zero for none.\n */\nexport void block_notification_until(i32 slot, i32 mask, i32 deadline) {\n    if (!occupied(slot)) { return; }\n    if (deadline != 0) { note_due(deadline); }\n    NotificationWait wait = NotificationWait { mask: mask, deadline_tick: deadline, syscall: false };\n    case g_threads[slot] of {\n        Some(t) -> ({ t.state = ThreadState::Blocked(WaitReason::Notification(wait)); });\n        None -> _;\n    };\n}\n\n/**\n * Delivers armed bits and wakes a matching notification waiter.\n * @param slot Destination TCB table index.\n * @param mask Notification bits produced by the event source.\n */\nexport void notify(i32 slot, i32 mask) {\n    if (!occupied(slot)) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({\n            i32 matched = t.notification_armed & mask;\n            if (matched) {\n                t.notification_pending = t.notification_pending | matched;\n                case t.state of {\n                    Blocked(wait_reason) -> ({\n                        case wait_reason of {\n                            Notification(wait) -> ({\n                                i32 reason = t.notification_pending & wait.mask;\n                                if (reason) {\n                                    t.notification_pending = t.notification_pending & (~reason);\n                                    t.notification_armed = t.notification_armed & (~wait.mask);\n                                    t.state = ThreadState::Runnable;\n                                    g_ready_epoch++;\n                                    t.wake_result = reason;\n                                    if (wait.syscall && t.saved_kernel_sp != 0) {\n                                        irq_frame.set_syscall_return(t.saved_kernel_sp, SyscallStatus::Ok, reason);\n                                    }\n                                }\n                            });\n                            _ -> _;\n                        };\n                    });\n                    _ -> _;\n                };\n            }\n        });\n        None -> _;\n    };\n}\n\n/**\n * Delivers notification bits to every TCB that armed them.\n * @param mask Notification bits produced by the event source.\n */\nexport void notify_all(i32 mask) {\n    i32 slot = 0;\n    while (slot < g_thread_slot_high_water) {\n        notify(slot, mask);\n        slot++;\n    }\n}\n\n/**\n * Reads and clears what woke a kernel thread from block_notification_until.\n * @param slot Occupied global TCB table index.\n * @return The delivered bits, or zero when the deadline passed first.\n */\nexport i32 take_wake_result(i32 slot) {\n    if (!occupied(slot)) { return 0; }\n    return case g_threads[slot] of {\n        Some(t) -> ({\n            i32 result = t.wake_result;\n            t.wake_result = 0;\n            result;\n        });\n        None -> 0;\n    };\n}\n\n/**\n * Removes a TCB and contracts the table high-water mark when possible.\n * All owned resources must already have been released.\n * @param slot Global TCB table index to clear.\n */\nexport void clear_slot(i32 slot) {\n    if (slot < 0 || slot >= kernel_config.MAX_THREADS) { return; }\n    Option<Thread> empty = None;\n    g_threads[slot] = empty;\n    if (g_current_thread_slot == slot) { g_current_thread_slot = -1; }\n    while (g_thread_slot_high_water > 0 &&\n           !occupied(g_thread_slot_high_water - 1)) {\n        g_thread_slot_high_water--;\n    }\n}\n\n// User stacks occupy fixed 2 MiB virtual slots below 0x8000_0000. Only the\n// requested top pages are mapped; the page immediately below remains a guard.\ni32 USER_STACK_TOP = 0x80000000;\ni32 USER_STACK_SLOT_BYTES = 0x00200000;\nexport const i32 USER_STACK_REGION_BASE = 0x7F000000;\n\n/**\n * Validates a requested user-stack size and rounds it to whole pages.\n * @param requested Requested bytes; zero selects DEFAULT_USER_STACK_BYTES.\n * @return Page-rounded byte count, or None when the request cannot fit its slot and guard.\n */\nOption<i32> rounded_stack_bytes(i32 requested) {\n    i32 bytes = requested;\n    if (bytes == 0) { bytes = kernel_config.DEFAULT_USER_STACK_BYTES; }\n    if (bytes <= 0 || bytes > USER_STACK_SLOT_BYTES - mmu.PAGE_SIZE) { return None; }\n    if (bytes > 0x7FFFF000) { return None; }\n    return Some((bytes + mmu.PAGE_SIZE - 1) & ~(mmu.PAGE_SIZE - 1));\n}\n\n/**\n * Unmaps and frees all physical frames in a thread-owned user-stack range.\n * @param pdbr Owner process page-directory base.\n * @param base Page-aligned first user virtual address.\n * @param bytes Page-multiple range length.\n */\nvoid release_user_mapping(i32 pdbr, i32 base, i32 bytes) {\n    i32 offset = 0;\n    while (offset < bytes) {\n        Result<i32, MmuError> unmapped = mmu.unmap_page(pdbr, base + offset);\n        case unmapped of {\n            Ok(frame) -> ({\n                if (frame != 0) {\n                    Result<_, MmuError> freed = mmu.free_frame(frame);\n                    case freed of { Ok(_) -> _; Err(_) -> ({ debug.panic(\"thread: invalid user stack frame\"); }); };\n                }\n            });\n            Err(_) -> ({ debug.panic(\"thread: failed to unmap user stack\"); });\n        };\n        offset = offset + mmu.PAGE_SIZE;\n    }\n}\n\n/**\n * Creates an additional user TCB and both of its stacks transactionally.\n * No TCB is published until the user mapping and kernel stack are complete;\n * recoverable failures release the reserved stack slot and all allocations.\n * @param pid Alive owner process that supplies the address space.\n * @param args Copied and trusted-by-value thread entry, arguments, and stack request.\n * @return Ok(new TID), or a precise allocation, entry, size, or lifecycle error.\n */\nexport Result<i32, ThreadError> spawn_user_thread(Pid pid, ThreadSpawnArgs args) {\n    if (!process.accepts_threads(pid)) { return Err(ThreadError::ProcessExiting); }\n    i32 retained = case process.retained_thread_count(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    if (retained >= kernel_config.MAX_THREADS_PER_PROC) {\n        return Err(ThreadError::NoFreeSlot);\n    }\n    i32 pdbr = case process.get_pdbr(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    if (!mmu.user_range_has_flags(pdbr, args.entry, 1, mmu.PTE_EXEC)) {\n        return Err(ThreadError::InvalidEntry(args.entry));\n    }\n    i32 stack_bytes = case rounded_stack_bytes(args.stack_bytes) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::InvalidStackSize(args.stack_bytes)); });\n    };\n\n    i32 tcb_slot = case find_free_slot() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::NoFreeSlot); });\n    };\n    i32 stack_slot = case process.reserve_user_stack_slot(pid) of {\n        Ok(Some(value)) -> value;\n        Ok(None) -> ({ return Err(ThreadError::NoFreeSlot); });\n        Err(_) -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    i32 stack_top = USER_STACK_TOP - stack_slot * USER_STACK_SLOT_BYTES;\n    i32 stack_base = stack_top - stack_bytes;\n    i32 mapped_bytes = 0;\n    while (mapped_bytes < stack_bytes) {\n        i32 frame = case mmu.alloc_page() of {\n            Some(value) -> value;\n            None -> ({\n                release_user_mapping(pdbr, stack_base, mapped_bytes);\n                process.release_user_stack_slot(pid, stack_slot);\n                return Err(ThreadError::OutOfMemory);\n            });\n        };\n        Result<_, MmuError> mapped = mmu.map_page(\n            pdbr, stack_base + mapped_bytes, frame,\n            mmu.PTE_VALID | mmu.PTE_WRITABLE | mmu.PTE_USER\n        );\n        case mapped of {\n            Ok(_) -> ({ mapped_bytes = mapped_bytes + mmu.PAGE_SIZE; });\n            Err(_) -> ({\n                mmu.free_frame(frame);\n                release_user_mapping(pdbr, stack_base, mapped_bytes);\n                process.release_user_stack_slot(pid, stack_slot);\n                return Err(ThreadError::OutOfMemory);\n            });\n        };\n    }\n\n    i32 kernel_stack = case heap.alloc(kernel_config.DEFAULT_KERNEL_STACK_BYTES) of {\n        Ok(value) -> value;\n        Err(_) -> ({\n            release_user_mapping(pdbr, stack_base, mapped_bytes);\n            process.release_user_stack_slot(pid, stack_slot);\n            return Err(ThreadError::OutOfMemory);\n        });\n    };\n    i32 user_sp = stack_top - 0x20;\n    i32 kernel_sp = irq_frame.build_user(\n        args.entry, args.arg0, args.arg1,\n        kernel_stack + kernel_config.DEFAULT_KERNEL_STACK_BYTES\n    );\n    KernelStack owned_kernel = KernelStack {\n        base: kernel_stack,\n        bytes: kernel_config.DEFAULT_KERNEL_STACK_BYTES,\n        owned: true,\n    };\n    UserStack owned_user = UserStack {\n        slot: stack_slot,\n        mapped_base: stack_base,\n        mapped_bytes: stack_bytes,\n    };\n    i32 tid = publish_user(tcb_slot, pid, kernel_sp, user_sp, owned_kernel, owned_user);\n    Result<_, ProcessError> accounted = process.retain_thread(pid);\n    case accounted of {\n        Ok(_) -> _;\n        Err(_) -> ({ debug.panic(\"thread: process disappeared at TCB publish\"); });\n    };\n    return Ok(tid);\n}\n\n/**\n * Marks only the calling thread for retirement after the next context switch.\n * If this removes the final live TCB, it also starts process-wide exit using code.\n * @param code User-visible thread exit code retained for join.\n */\nexport void exit_current_thread(i32 code) {\n    i32 slot = g_current_thread_slot;\n    if (!occupied(slot)) { return; }\n    Option<Pid> owner = owner_pid_at(slot);\n    case g_threads[slot] of {\n        Some(t) -> ({ t.state = ThreadState::Exiting(code); });\n        None -> ({ return; });\n    };\n    Pid pid = case owner of { Some(value) -> value; None -> ({ return; }); };\n    Result<_, ProcessError> marked = process.mark_thread_exited(pid);\n    case marked of { Ok(_) -> _; Err(_) -> ({ debug.panic(\"thread: exiting owner is missing\"); }); };\n    i32 live = case process.live_thread_count(pid) of { Some(value) -> value; None -> 0; };\n    if (live == 0) {\n        ProcessExitStatus status = ProcessExitStatus::Code(code);\n        process.begin_exit(pid, status);\n    }\n}\n\n/**\n * Starts process-wide exit and removes every owned TCB from runnable/waiting state.\n * Physical stack and address-space cleanup is deferred until a different stack runs.\n * @param pid Process whose TCBs must all exit.\n * @param status Final process status preserved in the eventual Zombie record.\n */\nexport void exit_process_threads(Pid pid, ProcessExitStatus status) {\n    Result<_, ProcessError> begun = process.begin_exit(pid, status);\n    case begun of { Ok(_) -> _; Err(_) -> ({ return; }); };\n    i32 i = 0;\n    while (i < g_thread_slot_high_water) {\n        case g_threads[i] of {\n            Some(t) -> ({\n                bool owned = case t.owner of { User(owner) -> owner == pid; Kernel -> false; };\n                if (owned) {\n                    bool live = case t.state of {\n                        Runnable -> true; Running -> true; Blocked(_) -> true; _ -> false;\n                    };\n                    if (live) { process.mark_thread_exited(pid); }\n                    t.state = ThreadState::Exiting(0);\n                }\n            });\n            None -> _;\n        };\n        i++;\n    }\n}\n\n/**\n * Releases the user and kernel stacks owned by a switched-out TCB.\n * @param slot Occupied TCB slot that is no longer executing on its kernel stack.\n */\nvoid cleanup_stack_resources(i32 slot) {\n    if (!occupied(slot)) { return; }\n    case g_threads[slot] of {\n        Some(t) -> ({\n            case t.owner of {\n                User(pid) -> ({\n                    i32 pdbr = case process.get_pdbr(pid) of { Some(value) -> value; None -> 0; };\n                    case t.user_stack of {\n                        Some(stack) -> ({\n                            if (pdbr != 0) { release_user_mapping(pdbr, stack.mapped_base, stack.mapped_bytes); }\n                            process.release_user_stack_slot(pid, stack.slot);\n                        });\n                        None -> _;\n                    };\n                });\n                Kernel -> _;\n            };\n            if (t.kernel_stack.owned && t.kernel_stack.base != 0) { heap.free(t.kernel_stack.base); }\n            t.kernel_stack.base = 0;\n            t.kernel_stack.bytes = 0;\n            t.kernel_stack.owned = false;\n            t.user_stack = None;\n        });\n        None -> _;\n    };\n}\n\n/**\n * Returns an exit code to a registered joiner through the saved r2 slot and\n * makes that joiner runnable with SyscallStatus::Ok in r1.\n * @param target_slot Exiting target TCB carrying the joiner registration.\n * @param code Exit code to copy to the waiting process.\n */\nvoid wake_joiner(i32 target_slot, i32 code) {\n    Option<i32> joiner = case g_threads[target_slot] of {\n        Some(t) -> t.joiner_tid;\n        None -> None;\n    };\n    case joiner of {\n        Some(joiner_tid) -> ({\n            case slot_for_tid(joiner_tid) of {\n                Some(joiner_slot) -> ({\n                    case g_threads[joiner_slot] of {\n                        Some(waiter) -> ({\n                            case waiter.state of {\n                                Blocked(reason) -> ({\n                                    case reason of {\n                                    Join(_) -> ({\n                                        waiter.wake_result = code;\n                                        if (waiter.saved_kernel_sp != 0) {\n                                            irq_frame.set_syscall_return(waiter.saved_kernel_sp, SyscallStatus::Ok, code);\n                                        }\n                                        waiter.state = ThreadState::Runnable;\n                                        g_ready_epoch++;\n                                    });\n                                    _ -> _;\n                                    };\n                                });\n                                _ -> _;\n                            };\n                        });\n                        None -> _;\n                    };\n                });\n                None -> _;\n            };\n        });\n        None -> _;\n    };\n}\n\n/**\n * Releases every TCB and the address space of an Exiting process, leaving its\n * Zombie record. None of its TCBs may still be running on a kernel stack.\n * @param pid Exiting process.\n */\nexport void finish_process_exit(Pid pid) {\n    i32 pdbr = case process.get_pdbr(pid) of { Some(value) -> value; None -> 0; };\n    i32 i = 0;\n    while (i < g_thread_slot_high_water) {\n        bool owned = case owner_pid_at(i) of { Some(owner) -> owner == pid; None -> false; };\n        if (owned) {\n            cleanup_stack_resources(i);\n            clear_slot(i);\n        }\n        i++;\n    }\n    if (pdbr != 0) {\n        Result<_, MmuError> destroyed = mmu.destroy_user_address_space(pdbr);\n        case destroyed of { Ok(_) -> _; Err(_) -> ({ debug.panic(\"thread: address-space cleanup failed\"); }); };\n    }\n    process.clear_owned_resources(pid);\n    process.finish_exit(pid);\n    notify_all(KernelSignal::PROCESS_ENDED);\n}\n\n/**\n * Completes cleanup after an Exiting TCB has been switched away.\n * A normal thread becomes a stack-free Zombie unless a joiner reaps it;\n * an Exiting process instead releases every owned TCB and its address space.\n * @param retired_slot TCB slot whose kernel stack is no longer active.\n */\nexport void finish_deferred_cleanup(i32 retired_slot) {\n    if (!occupied(retired_slot)) { return; }\n    i32 code = case state_at(retired_slot) of {\n        Some(state) -> case state of { ThreadState::Exiting(value) -> value; _ -> 0; };\n        None -> 0;\n    };\n\n    Pid pid = case owner_pid_at(retired_slot) of {\n        Some(value) -> value;\n        None -> ({\n            cleanup_stack_resources(retired_slot);\n            clear_slot(retired_slot);\n            return;\n        });\n    };\n\n    bool process_exiting = case process.get_state(pid) of {\n        Some(state) -> case state of { ProcessState::Exiting(_) -> true; _ -> false; };\n        None -> false;\n    };\n    if (process_exiting) {\n        finish_process_exit(pid);\n        return;\n    }\n\n    cleanup_stack_resources(retired_slot);\n    case g_threads[retired_slot] of {\n        Some(t) -> ({ t.state = ThreadState::Zombie(code); });\n        None -> _;\n    };\n    bool has_joiner = case g_threads[retired_slot] of {\n        Some(t) -> case t.joiner_tid of { Some(_) -> true; None -> false; };\n        None -> false;\n    };\n    wake_joiner(retired_slot, code);\n    if (has_joiner) {\n        clear_slot(retired_slot);\n        process.release_thread(pid);\n    }\n}\n\n/**\n * Installs the caller as the target's sole joiner, or reaps a Zombie immediately.\n * The caller and target must be distinct TCBs owned by the same process.\n * @param target_tid Stable TID to wait for.\n * @return Ok(Completed(code)) for immediate Zombie reap, Ok(Waiting) after\n *         blocking the caller, or Err for invalid ownership/self/double join.\n */\nexport Result<JoinOutcome, ThreadError> join_thread(i32 target_tid) {\n    i32 caller_slot = g_current_thread_slot;\n    i32 caller_tid = case current_tid() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::InvalidTid(target_tid)); });\n    };\n    if (caller_tid == target_tid) { return Err(ThreadError::JoinSelf); }\n    i32 target_slot = case slot_for_tid(target_tid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::InvalidTid(target_tid)); });\n    };\n    Pid pid = case current_pid() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::InvalidTid(target_tid)); });\n    };\n    bool same_owner = case owner_pid_at(target_slot) of { Some(owner) -> owner == pid; None -> false; };\n    if (!same_owner) { return Err(ThreadError::InvalidTid(target_tid)); }\n    case g_threads[target_slot] of {\n        Some(target) -> ({\n            case target.state of {\n                ThreadState::Zombie(code) -> ({\n                    i32 exit_code = code; // `code` names the field clear_slot() wipes\n                    clear_slot(target_slot);\n                    process.release_thread(pid);\n                    return Ok(JoinOutcome::Completed(exit_code));\n                });\n                _ -> ({\n                    bool already = case target.joiner_tid of { Some(_) -> true; None -> false; };\n                    if (already) { return Err(ThreadError::AlreadyJoined(target_tid)); }\n                    target.joiner_tid = Some(caller_tid);\n                    JoinWait wait = JoinWait { target_tid: target_tid };\n                    case g_threads[caller_slot] of {\n                        Some(caller) -> ({ caller.state = ThreadState::Blocked(WaitReason::Join(wait)); });\n                        None -> ({ return Err(ThreadError::InvalidTid(caller_tid)); });\n                    };\n                    return Ok(JoinOutcome::Waiting);\n                });\n            };\n        });\n        None -> ({ return Err(ThreadError::InvalidTid(target_tid)); });\n    };\n}\n\n/**\n * Validates a futex word, rechecks its value, and blocks the current TCB.\n * The effective key is the caller's PID plus addr; no kernel pointer is retained.\n * @param addr Aligned readable/writable user virtual word address.\n * @param expected Value that must still be present before blocking.\n * @param timeout_ticks Relative timeout; zero means no timeout.\n * @param now Current scheduler tick used to form an absolute deadline.\n * @return Ok(false) after publishing the wait, or Err(WouldBlock/BadAddress/etc.).\n */\nexport Result<bool, ThreadError> futex_wait(i32 addr, i32 expected, i32 timeout_ticks, i32 now) {\n    Pid pid = case current_pid() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::BadAddress(addr)); });\n    };\n    if ((addr & 3) || timeout_ticks < 0) { return Err(ThreadError::BadAddress(addr)); }\n    i32 pdbr = case process.get_pdbr(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    if (!mmu.user_range_has_flags(pdbr, addr, 4, mmu.PTE_WRITABLE)) {\n        return Err(ThreadError::BadAddress(addr));\n    }\n    i32 value = case mmu.read_user_word(pdbr, addr) of {\n        Some(word) -> word;\n        None -> ({ return Err(ThreadError::BadAddress(addr)); });\n    };\n    if (value != expected) { return Err(ThreadError::WouldBlock); }\n    i32 deadline = 0;\n    if (timeout_ticks > 0) {\n        deadline = now + timeout_ticks;\n        note_due(deadline);\n    }\n    i32 sequence = g_next_wait_sequence;\n    g_next_wait_sequence++;\n    if (g_next_wait_sequence <= 0) { g_next_wait_sequence = 1; }\n    FutexWait wait = FutexWait { addr: addr, deadline_tick: deadline, sequence: sequence };\n    case g_threads[g_current_thread_slot] of {\n        Some(t) -> ({ t.state = ThreadState::Blocked(WaitReason::Futex(wait)); });\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    return Ok(false);\n}\n\n/**\n * Wakes FIFO waiters sharing the caller's (PID, address) futex key.\n * @param addr Aligned readable/writable user virtual word address.\n * @param count Maximum number of wait registrations to consume.\n * @return Ok(number woken), or Err for an invalid address/count or exiting process.\n */\nexport Result<i32, ThreadError> futex_wake(i32 addr, i32 count) {\n    Pid pid = case current_pid() of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::BadAddress(addr)); });\n    };\n    if ((addr & 3) || count < 0) { return Err(ThreadError::BadAddress(addr)); }\n    i32 pdbr = case process.get_pdbr(pid) of {\n        Some(value) -> value;\n        None -> ({ return Err(ThreadError::ProcessExiting); });\n    };\n    if (!mmu.user_range_has_flags(pdbr, addr, 4, mmu.PTE_WRITABLE)) {\n        return Err(ThreadError::BadAddress(addr));\n    }\n    i32 woken = 0;\n    while (woken < count) {\n        i32 best_slot = -1;\n        i32 best_sequence = 0x7FFFFFFF;\n        i32 i = 0;\n        while (i < g_thread_slot_high_water) {\n            case g_threads[i] of {\n                Some(t) -> ({\n                    bool owner_matches = case t.owner of { User(owner) -> owner == pid; Kernel -> false; };\n                    if (owner_matches) {\n                        case t.state of {\n                            Blocked(reason) -> ({\n                                case reason of {\n                                    Futex(wait) -> ({\n                                        if (wait.addr == addr && wait.sequence < best_sequence) {\n                                            best_sequence = wait.sequence;\n                                            best_slot = i;\n                                        }\n                                    });\n                                    _ -> _;\n                                };\n                            });\n                            _ -> _;\n                        };\n                    }\n                });\n                None -> _;\n            };\n            i++;\n        }\n        if (best_slot < 0) { break; }\n        case g_threads[best_slot] of {\n            Some(t) -> ({\n                t.wake_result = 0;\n                if (t.saved_kernel_sp != 0) {\n                    irq_frame.set_syscall_return(t.saved_kernel_sp, SyscallStatus::Ok, 0);\n                }\n                t.state = ThreadState::Runnable;\n                g_ready_epoch++;\n            });\n            None -> _;\n        };\n        woken++;\n    }\n    return Ok(woken);\n}\n\n/**\n * Wakes the TCBs whose sleep, futex or notification deadline falls due by\n * `now`: a sleeper becomes Runnable, a futex waiter Runnable with TimedOut,\n * a notification waiter Runnable with no bits. Most calls find\n * nothing due and return before looking at a slot; the others look at each\n * slot once, and note the next deadline still to come.\n * @param now Current scheduler tick.\n */\nexport void wake_due(i32 now) {\n    bool due = case g_next_due of { Some(tick) -> tick <= now; None -> false; };\n    if (!due) { return; }\n    g_next_due = None;\n    i32 slot = 0;\n    while (slot < g_thread_slot_high_water) {\n        case g_threads[slot] of {\n            Some(t) -> ({\n                case t.state of {\n                    Blocked(reason) -> ({\n                        case reason of {\n                            Sleep(wait) -> ({\n                                if (wait.deadline_tick <= now) {\n                                    t.state = ThreadState::Runnable;\n                                    g_ready_epoch++;\n                                }\n                                else { note_due(wait.deadline_tick); }\n                            });\n                            Futex(wait) -> ({\n                                if (wait.deadline_tick != 0 && wait.deadline_tick <= now) {\n                                    t.wake_result = wait.addr;\n                                    if (t.saved_kernel_sp != 0) {\n                                        irq_frame.set_syscall_return(t.saved_kernel_sp, SyscallStatus::TimedOut, wait.addr);\n                                    }\n                                    t.state = ThreadState::Runnable;\n                                    g_ready_epoch++;\n                                } else if (wait.deadline_tick != 0) {\n                                    note_due(wait.deadline_tick);\n                                }\n                            });\n                            Notification(wait) -> ({\n                                if (wait.deadline_tick != 0 && wait.deadline_tick <= now) {\n                                    t.notification_armed = t.notification_armed & (~wait.mask);\n                                    t.wake_result = 0;\n                                    if (wait.syscall && t.saved_kernel_sp != 0) {\n                                        irq_frame.set_syscall_return(t.saved_kernel_sp, SyscallStatus::Ok, 0);\n                                    }\n                                    t.state = ThreadState::Runnable;\n                                    g_ready_epoch++;\n                                } else if (wait.deadline_tick != 0) {\n                                    note_due(wait.deadline_tick);\n                                }\n                            });\n                            _ -> _;\n                        };\n                    });\n                    _ -> _;\n                };\n            });\n            None -> _;\n        };\n        slot++;\n    }\n}\n","system/MyKernel/src/mm/frames.unsafe.mln":"namespace frames;\n\nimport mem from \"mem.mln\";\nimport heap from \"heap.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport { Option } from \"@std/core/option.mln\";\n\n// Physical page frames: page tables, and every page a process maps. They are\n// the RAM above the kernel heap, up to the region the boot stack lives in at\n// the top, a 4 KiB page at a time. The kernel reaches them through its identity\n// mapping of the same range (mmu.mln).\n//\n// A free frame's first word names the next free one, so the free list needs no\n// memory of its own. Frames never handed out yet come from `g_next` upward.\n\nconst i32 FRAME_BYTES = 4096;\n/** Where the frames end: mmu's boot-stack region starts here. */\nexport const i32 POOL_END = 0x1F000000;\n\ni32 g_first = 0;       // the first frame\ni32 g_next = 0;        // the first frame never handed out\ni32 g_free = 0;        // the first free frame handed back, or zero\ni32 g_free_count = 0;  // how many are on that list\n\n/** Places the pool after the heap, the first time a frame is wanted. */\nvoid ensure_ready() {\n    if (g_first != 0) { return; }\n    g_first = (heap.end() + FRAME_BYTES - 1) & ~(FRAME_BYTES - 1);\n    g_next = g_first;\n    g_free = 0;\n    g_free_count = 0;\n}\n\n/**\n * Takes a frame. Its contents are whatever was there.\n * @return Some(physical address, 4 KiB aligned), or None when every frame is in use.\n */\nexport Option<i32> alloc() {\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    ensure_ready();\n    if (g_free != 0) {\n        i32 frame = g_free;\n        g_free = mem.read_word(frame);\n        g_free_count--;\n        return Some(frame);\n    }\n    if (g_next >= POOL_END) { return None; }\n    i32 frame = g_next;\n    g_next = g_next + FRAME_BYTES;\n    return Some(frame);\n}\n\n/**\n * Hands a frame back.\n * @param frame A frame alloc returned and nobody uses any more.\n * @return Whether it was one: aligned and inside the pool.\n */\nexport bool free(i32 frame) {\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    ensure_ready();\n    if ((frame & (FRAME_BYTES - 1)) != 0 || frame < g_first || frame >= g_next) { return false; }\n    mem.write_word(frame, g_free);\n    g_free = frame;\n    g_free_count++;\n    return true;\n}\n\n/** @return Frames in the pool. */\nexport i32 total() {\n    ensure_ready();\n    return (POOL_END - g_first) / FRAME_BYTES;\n}\n\n/** @return Frames free now: never handed out, or handed back. */\nexport i32 available() {\n    ensure_ready();\n    return (POOL_END - g_next) / FRAME_BYTES + g_free_count;\n}\n","system/MyKernel/src/mm/heap.unsafe.mln":"namespace heap;\n\nimport { heap_image_end } from \"heap_sym.masm\";\nimport debug from \"@kernel/debug/debug.mln\";\n\n// First-fit allocator over the region between the loaded image (`_end`, from\n// heap_image_end()) and _end + HEAP_SIZE, with an address-ordered free list and\n// coalescing of physically-adjacent free blocks.\n//\n// Every block is laid out as an 8-byte header followed by its payload:\n//   word[h + 0] = size   (payload bytes, not counting the header)\n//   word[h + 4] = next   (address of the next FREE block header, 0 = none)\n// The free list is kept sorted by address so free() can merge neighbours.\n// A block's physical end is  h + HDR_SIZE + size.\n\nimport kernel_config from \"@kernel/kernel/kernel_config.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport int32 from \"@std/core/int32.mln\";\nimport { AllocationError } from \"@std/memory/allocator.mln\";\nimport { Drop } from \"@std/core/drop.mln\";\n\ni32 HDR_SIZE = 8;\ni32 ALIGN = 4;\n\ni32 g_free_head = 0;\n\n/**\n * Reads a 32-bit word from a physical/virtual memory address.\n * @param addr Memory address to read.\n * @return 32-bit word value.\n */\ni32 read_word(i32 addr) {\n    i32 *p = (i32 *)addr;\n    return *p;\n}\n\n/**\n * Writes a 32-bit word to a physical/virtual memory address.\n * @param addr Memory address to write.\n * @param value 32-bit word value to store.\n */\nvoid write_word(i32 addr, i32 value) {\n    i32 *p = (i32 *)addr;\n    *p = value;\n}\n\n/**\n * Rounds an integer up to the 4-byte heap alignment boundary.\n * @param n Size in bytes to align.\n * @return 4-byte aligned size.\n */\ni32 align_up(i32 n) {\n    return (n + (ALIGN - 1)) & ~(ALIGN - 1);\n}\n\n/**\n * Reads the payload size stored in a block header.\n * @param h Address of the block header.\n * @return Payload size in bytes, excluding the header.\n */\ni32 block_size(i32 h) { return read_word(h + 0); }\n/**\n * Reads the next free block address stored in a block header.\n * @param h Address of the block header.\n * @return Address of the next free block header, or 0 if there is none.\n */\ni32 block_next(i32 h) { return read_word(h + 4); }\n/**\n * Writes the payload size into a block header.\n * @param h Address of the block header.\n * @param v Payload size in bytes, excluding the header.\n */\nvoid set_size(i32 h, i32 v) { write_word(h + 0, v); }\n/**\n * Writes the next-free-block pointer into a block header.\n * @param h Address of the block header.\n * @param v Address of the next free block header, or 0 if there is none.\n */\nvoid set_next(i32 h, i32 v) { write_word(h + 4, v); }\n\ni32 g_heap_base = 0;\n\n/**\n * Calculates the address immediately after a block's header and payload.\n * @param h Address of the block header.\n * @return End-exclusive address of the block.\n */\ni32 block_end(i32 h) {\n    return h + HDR_SIZE + block_size(h);\n}\n\n/**\n * Initializes the kernel heap manager starting after the loaded kernel image.\n *\n * Sets up a single free block spanning the configured heap region, beginning\n * at the aligned end of the loaded kernel image.\n */\nexport void init() {\n    i32 base = heap_image_end();\n    base = align_up(base);\n\n    // One big free block spanning the whole heap region.\n    set_size(base, kernel_config.HEAP_SIZE - HDR_SIZE);\n    set_next(base, 0);\n    g_free_head = base;\n    g_heap_base = base;\n}\n\n/**\n * Allocates a contiguous memory block of at least `size` bytes from the kernel heap.\n *\n * Uses first-fit allocation and splits remaining space when viable.\n * The caller must provide the required exclusion when heap locking is enabled.\n * @param size Requested allocation size in bytes.\n * @return `Ok(pointer)` on success, or `Err(InvalidSize|OutOfMemory)`.\n */\nResult<i32, AllocationError> alloc_unlocked(i32 size) {\n    if (size <= 0 || size > int32.MAX - (ALIGN - 1)) {\n        return Err(AllocationError::InvalidSize);\n    }\n    size = align_up(size);\n\n    i32 prev = 0;\n    i32 cur = g_free_head;\n\n    while (cur != 0) {\n        i32 cur_size = block_size(cur);\n        i32 cur_next = block_next(cur);\n\n        if (cur_size >= size) {\n            // Split if the remainder can hold another header + a little payload.\n            i32 remainder = cur_size - size;\n            if (remainder >= HDR_SIZE + ALIGN) {\n                i32 split = cur + HDR_SIZE + size;\n                set_size(split, remainder - HDR_SIZE);\n                set_next(split, cur_next);\n                set_size(cur, size);\n                cur_next = split;\n            }\n\n            // Unlink cur from the free list.\n            if (prev == 0) {\n                g_free_head = cur_next;\n            } else {\n                set_next(prev, cur_next);\n            }\n            return Ok(cur + HDR_SIZE);\n        }\n\n        prev = cur;\n        cur = cur_next;\n    }\n\n    return Err(AllocationError::OutOfMemory);\n}\n\n/**\n * Returns a previously allocated block to the free list.\n *\n * Maintains address order in the free list and coalesces with adjacent free neighbours.\n * The caller must provide the required exclusion when heap locking is enabled.\n * @param ptr Pointer to payload memory to free (no-op if 0).\n */\nvoid free_unlocked(i32 ptr) {\n    if (ptr != 0 && g_heap_base != 0) {\n        if (ptr < g_heap_base || ptr >= g_heap_base + kernel_config.HEAP_SIZE) {\n            debug.printf(\"heap: free of a pointer outside the heap: %x\\n\", ptr);\n            debug.panic(\"heap: bad free\");\n        }\n    }\n    if (ptr != 0) {\n        i32 block = ptr - HDR_SIZE;\n\n        // Find the insertion point: prev < block < cur, by address.\n        i32 prev = 0;\n        i32 cur = g_free_head;\n        while (cur != 0 && cur < block) {\n            prev = cur;\n            cur = block_next(cur);\n        }\n\n        // Link block into the ordered list between prev and cur.\n        set_next(block, cur);\n        if (prev == 0) {\n            g_free_head = block;\n        } else {\n            set_next(prev, block);\n        }\n\n        // Merge forward: block is immediately before cur.\n        if (cur != 0 && block_end(block) == cur) {\n            set_size(block, block_size(block) + HDR_SIZE + block_size(cur));\n            set_next(block, block_next(cur));\n        }\n\n        // Merge backward: prev is immediately before block.\n        if (prev != 0 && block_end(prev) == block) {\n            set_size(prev, block_size(prev) + HDR_SIZE + block_size(block));\n            set_next(prev, block_next(block));\n        }\n    }\n}\n\n// The heap is shared by every task and by syscalls (which run in a\n// process's context on the timer's schedule), so the free list is walked\n// and rewritten with interrupts off once the scheduler is live: a tick\n// landing inside alloc() on one task while another task -- or a syscall\n// handler -- allocates would leave two blocks overlapping. Before\n// enable_locking() (boot, interrupts still off) the sections run bare, so\n// they cannot switch interrupts on early.\nbool g_locking = false;\n\n/**\n * Enables interrupt protection around public heap allocation and free operations.\n *\n * Call once the scheduler is live. This only enables heap protection; it does\n * not itself enable hardware interrupts.\n */\nexport void enable_locking() { g_locking = true; }\n\n/** @return The first address past the heap: where the physical frames begin (frames.mln). */\nexport i32 end() {\n    if (g_heap_base == 0) { return align_up(heap_image_end()) + kernel_config.HEAP_SIZE; }\n    return g_heap_base + kernel_config.HEAP_SIZE;\n}\n\n/**\n * Allocates a block from the kernel heap.\n *\n * Uses first-fit allocation and splits a free block when the remainder can hold\n * another header and payload. Once heap locking is enabled, interrupts are\n * disabled for the allocator's free-list updates and restored to their prior\n * state afterward.\n * @param size Requested allocation size in bytes.\n * @return `Ok(pointer)` on success, or `Err(InvalidSize|OutOfMemory)`.\n */\nexport Result<i32, AllocationError> alloc(i32 size) {\n    if (!g_locking) { return alloc_unlocked(size); }\n    bool was = irq.save_disable();\n    defer irq.restore(was);\n    return alloc_unlocked(size);\n}\n\n/**\n * Returns a previously allocated block to the kernel heap.\n *\n * Inserts the block into the address-ordered free list and merges adjacent free\n * blocks. A null pointer is a no-op. Once heap locking is enabled, interrupts\n * are disabled during the free-list update and restored to their prior state.\n * @param ptr Pointer to the allocated payload, or 0.\n */\nexport void free(i32 ptr) {\n    if (!g_locking) { free_unlocked(ptr); return; }\n    bool was = irq.save_disable();\n    defer irq.restore(was);\n    free_unlocked(ptr);\n}\n\n/**\n * A kernel heap allocation owned by one binding: it is freed when the owner\n * goes out of scope, on every return path including `?`, unless keep() hands\n * it on first.\n * @property addr Payload address, or 0 for no allocation.\n */\nexport struct HeapBlock {\n    i32 addr;\n};\n\nexport impl Drop for HeapBlock {\n    void (borrow Self self) drop() {\n        free(self.addr);\n        self.addr = 0;\n    }\n}\n\n/**\n * Gives up ownership, so the allocation outlives this owner.\n * @return The payload address, now the caller's to free.\n */\nexport i32 (borrow HeapBlock self) keep() {\n    i32 addr = self.addr;\n    self.addr = 0;\n    return addr;\n}\n","system/MyOS/src/apps/tasks.dom.mln":"namespace tasks;\n\nimport app from \"@app/app.mln\";\nimport { App, View } from \"@app/app.mln\";\nimport elements from \"@app/elements.mln\";\nimport ui from \"@app/ui.mln\";\nimport { app, icon, timer } from \"@app/annotations.mln\";\nimport process from \"@std/hosted/process.mln\";\nimport { ProcStats, ProcInfo, ProcActivity, CpuTimes } from \"@contracts/myos/process-args.contract.mln\";\nimport str from \"@std/text/str.mln\";\nimport { Text } from \"@std/text/text.mln\";\nimport { Option } from \"@std/core/option.mln\";\n\n// Task Manager: what is running and what it costs, read once a second. It only\n// shows: a process controls nothing but its own children, so it ends nothing.\n//\n// CPU time is counted in timer clock units (256 a tick), charged to whatever\n// ran each time the scheduler switches threads. A share is the time something\n// took between two readings over all the time between them. The graph keeps a\n// minute of shares: the whole CPU filled, and the selected row as a line over it.\n//\n// The list is a table because a tab moves to the next column: the nth tab on a\n// line goes to n tab stops from its start, so the header and every row put the\n// same number of tabs before a column (see `cell`).\n\nconst i32 SAMPLES = 60;    // one a second: a minute across the graph\nconst i32 OS_SERIES = 16;  // series 0..15 follow processes\nconst i32 CPU_SERIES = 17;\nconst i32 OS_KEY = 0;      // the OS's own row: no process has pid 0\nconst i32 NO_KEY = -1;\n\n// Where each column starts, in tab stops from the start of the line.\nconst i32 COL_PID = 7;\nconst i32 COL_THREADS = 9;\nconst i32 COL_CPU = 12;\nconst i32 COL_MEMORY = 15;\nconst i32 COL_STATE = 19;\n\n/**\n * The Task Manager's state.\n * @property last The previous reading: shares are what changed since.\n * @property keys What each series follows: a pid, OS_KEY, or NO_KEY when free.\n * @property counts How many samples each series has, up to SAMPLES.\n * @property samples Each series' shares, oldest first, SAMPLES apart.\n * @property row_keys What each row of the list shows, top first.\n * @property row_count Rows in the list.\n * @property rows The list's rows.\n * @property header The column titles over the list.\n * @property selected The selected row.\n * @property selected_key What the selected row shows; it stays selected as rows move.\n * @property fill The whole CPU's series, as the graph takes it.\n * @property line The selected row's series.\n * @property cpu The CPU's share now.\n * @property chosen The selected row's name and share now.\n * @property summary The status line.\n */\n@app(name = \"Task Manager\", single)\n@icon(\"tasks\")\nstruct Tasks {\n    ProcStats last;\n    i32 keys[18];\n    i32 counts[18];\n    u8 samples[1080];\n    i32 row_keys[17];\n    i32 row_count;\n    Text<1024> rows;\n    Text<96> header;\n    Option<i32> selected;\n    i32 selected_key;\n    Text<256> fill;\n    Text<256> line;\n    Text<32> cpu;\n    Text<48> chosen;\n    Text<96> summary;\n};\n\nimpl App for Tasks {\n    Self start() {\n        Tasks t = Tasks { selected_key: NO_KEY };\n        i32 i = 0;\n        while (i < OS_SERIES) { t.keys[i] = NO_KEY; i++; }\n        t.keys[OS_SERIES] = OS_KEY;\n        cell(&t.header, \"Name\", COL_PID);\n        cell(&t.header, \"PID\", COL_THREADS);\n        cell(&t.header, \"Threads\", COL_CPU);\n        cell(&t.header, \"CPU\", COL_MEMORY);\n        cell(&t.header, \"Memory\", COL_STATE);\n        t.header.append(\"State\");\n        t.last = process.stats();\n        t.show();\n        return t;\n    }\n\n    View (Self t) view() {\n        return <Window title=\"Task Manager\" w={560} h={500}>\n            <Label text={t.cpu} x={16} y={12} bold={1} testId=\"cpu-share\" />\n            <Label text={t.chosen} x={160} y={12} color={ui.GRAPH_SECOND} testId=\"selected-share\" />\n            <Graph x={16} y={40} w={528} h={120} samples={60} fill={t.fill} line={t.line} anchor={ui.GROW_W} testId=\"cpu-graph\" />\n            <Label text={t.header} x={28} y={174} color={ui.TEXT_SECONDARY} />\n            <List name=\"processes\" items={t.rows} selected={t.selected} x={16} y={196} w={528} h={236}\n                  capacity={1024} anchor={ui.GROW_W | ui.GROW_H} onChange={t.select} testId=\"process-list\" />\n            <Label text={t.summary} x={16} y={444} color={ui.TEXT_SECONDARY} anchor={ui.PIN_BOTTOM} testId=\"tasks-summary\" />\n        <\/Window>;\n    }\n}\n\n/** Takes a reading and shows what changed since the last one. */\n@timer(1000)\nvoid (borrow Tasks t) tick() {\n    ProcStats now = process.stats();\n    i32 span = now.cpu.total - t.last.cpu.total;\n    if (span > 0) {\n        t.record(CPU_SERIES, share(span - (now.cpu.idle - t.last.cpu.idle), span));\n        t.record(OS_SERIES, share(now.cpu.kernel - t.last.cpu.kernel, span));\n        i32 i = 0;\n        while (i < now.count) {\n            ProcInfo p = now.procs[i];\n            case t.series_for(p.pid) of {\n                Some(series) -> ({ t.record(series, share(p.cpu_time - t.time_before(p.pid), span)); });\n                None -> _;\n            };\n            i++;\n        }\n    }\n    t.last = now;\n    t.forget_ended();\n    t.show();\n}\n\n/**\n * Selects a row: its series becomes the line over the graph.\n * @param row The row.\n */\nvoid (borrow Tasks t) select(i32 row) {\n    if (row < 0 || row >= t.row_count) { return; }\n    t.selected_key = t.row_keys[row];\n    t.show();\n}\n\n// --- series ------------------------------------------------------------------\n\n/**\n * A share of the time between two readings.\n * @param part The time something took, in timer clock units.\n * @param span All the time between the readings, in the same units.\n * @return Percent, 0 to 100.\n */\ni32 share(i32 part, i32 span) {\n    if (span <= 0 || part <= 0) { return 0; }\n    // A second is 256000 units; halve both until part * 100 fits.\n    while (part > 20000000) {\n        part = part / 2;\n        span = span / 2;\n    }\n    if (span <= 0) { return 100; }\n    i32 percent = (part * 100 + span / 2) / span;\n    return percent > 100 ? 100 : percent;\n}\n\n/**\n * The series following a process, taking a free one for a new process.\n * @param pid The process.\n * @return The series, or None when all are taken.\n */\nOption<i32> (borrow Tasks t) series_for(i32 pid) {\n    i32 i = 0;\n    while (i < OS_SERIES) {\n        if (t.keys[i] == pid) { return Some(i); }\n        i++;\n    }\n    i = 0;\n    while (i < OS_SERIES) {\n        if (t.keys[i] == NO_KEY) {\n            t.keys[i] = pid;\n            t.counts[i] = 0;\n            return Some(i);\n        }\n        i++;\n    }\n    return None;\n}\n\n/**\n * The time a process had run at the last reading; zero for one started since.\n * @param pid The process.\n * @return Its time then, in timer clock units.\n */\ni32 (borrow Tasks t) time_before(i32 pid) {\n    i32 i = 0;\n    while (i < t.last.count) {\n        ProcInfo p = t.last.procs[i];\n        if (p.pid == pid) { return p.cpu_time; }\n        i++;\n    }\n    return 0;\n}\n\n/** Frees the series of processes the last reading no longer has. */\nvoid (borrow Tasks t) forget_ended() {\n    i32 i = 0;\n    while (i < OS_SERIES) {\n        if (t.keys[i] != NO_KEY && !t.has_pid(t.keys[i])) { t.keys[i] = NO_KEY; }\n        i++;\n    }\n}\n\n/**\n * @param pid A process.\n * @return Whether the last reading has it.\n */\nbool (borrow Tasks t) has_pid(i32 pid) {\n    i32 i = 0;\n    while (i < t.last.count) {\n        ProcInfo p = t.last.procs[i];\n        if (p.pid == pid) { return true; }\n        i++;\n    }\n    return false;\n}\n\n/**\n * Adds a share to a series, dropping its oldest when it is full.\n * @param series The series.\n * @param percent The share.\n */\nvoid (borrow Tasks t) record(i32 series, i32 percent) {\n    i32 base = series * SAMPLES;\n    i32 count = t.counts[series];\n    if (count == SAMPLES) {\n        i32 k = 1;\n        while (k < SAMPLES) {\n            t.samples[base + k - 1] = t.samples[base + k];\n            k++;\n        }\n        count = SAMPLES - 1;\n    }\n    t.samples[base + count] = (u8)percent;\n    t.counts[series] = count + 1;\n}\n\n/**\n * The latest share of a series.\n * @param series The series.\n * @return Percent, zero before the first.\n */\ni32 (borrow Tasks t) latest(i32 series) {\n    i32 count = t.counts[series];\n    if (count == 0) { return 0; }\n    return (i32)t.samples[series * SAMPLES + count - 1];\n}\n\n/**\n * A series as the graph takes it.\n * @param series The series.\n * @return Its shares apart by spaces.\n */\nText<256> (borrow Tasks t) series_text(i32 series) {\n    Text<256> out = Text<256> {};\n    i32 i = 0;\n    while (i < t.counts[series]) {\n        if (i > 0) { out.append(\" \"); }\n        Text<12> number = ((i32)t.samples[series * SAMPLES + i]).to_string();\n        out.append(number.as_str());\n        i++;\n    }\n    return out;\n}\n\n/**\n * The series a row's key follows.\n * @param key A pid or OS_KEY.\n * @return The series, or None for a process without one.\n */\nOption<i32> (borrow Tasks t) series_of(i32 key) {\n    i32 i = 0;\n    while (i <= OS_SERIES) {\n        if (t.keys[i] == key) { return Some(i); }\n        i++;\n    }\n    return None;\n}\n\n// --- the table -----------------------------------------------------------------\n\n/**\n * Appends a cell and the tabs that bring the line to the next column.\n * @param line The line so far.\n * @param text The cell.\n * @param next The tab stop the next column starts at.\n */\nvoid cell(borrow Text<96> line, str text, i32 next) {\n    line.append(text);\n    while (tabs_in(line.as_str()) < next) { line.append(\"\\t\"); }\n}\n\n/**\n * @param text A line.\n * @return The tabs in it.\n */\ni32 tabs_in(str text) {\n    i32 count = 0;\n    i32 i = 0;\n    while (i < text.length) {\n        if (text.byte(i) == '\\t') { count++; }\n        i++;\n    }\n    return count;\n}\n\n/**\n * @param value A number.\n * @param unit What follows it.\n * @return Both as one cell.\n */\nText<24> number_cell(i32 value, str unit) {\n    Text<24> out = Text<24> {};\n    Text<12> digits = value.to_string();\n    out.append(digits.as_str());\n    out.append(unit);\n    return out;\n}\n\n/**\n * @param pages A number of 4 KiB pages.\n * @return It in megabytes, to a tenth.\n */\nText<24> megabytes(i32 pages) {\n    i32 tenths = (pages * 4 * 10 + 512) / 1024;\n    Text<24> out = number_cell(tenths / 10, \".\");\n    i32 digit = tenths % 10;\n    Text<12> tenth = digit.to_string();\n    out.append(tenth.as_str());\n    out.append(\" MB\");\n    return out;\n}\n\n/**\n * @param count How many.\n * @param one What one is called.\n * @param many What more are called.\n * @return The count and the word that goes with it.\n */\nText<24> count_of(i32 count, str one, str many) {\n    Text<24> out = number_cell(count, \" \");\n    if (count == 1) { out.append(one); } else { out.append(many); }\n    return out;\n}\n\n/**\n * @param activity What a process is doing.\n * @return It in a word.\n */\nstr activity_name(ProcActivity activity) {\n    return case activity of {\n        ProcActivity::Starting -> \"starting\";\n        ProcActivity::Running -> \"running\";\n        ProcActivity::Waiting -> \"waiting\";\n        ProcActivity::Exiting -> \"exiting\";\n        ProcActivity::Ended -> \"ended\";\n    };\n}\n\n/**\n * Adds a row to the list.\n * @param key What it shows: a pid or OS_KEY.\n * @param line Its text.\n */\nvoid (borrow Tasks t) add_row(i32 key, str line) {\n    if (t.row_count > 0) { t.rows.append(\"\\n\"); }\n    t.rows.append(line);\n    t.row_keys[t.row_count] = key;\n    if (key == t.selected_key) { t.selected = Some(t.row_count); }\n    t.row_count = t.row_count + 1;\n}\n\n/** Rebuilds what the window shows from the last reading and the shares. */\nvoid (borrow Tasks t) show() {\n    ProcStats now = t.last;\n    t.rows.clear();\n    t.row_count = 0;\n    t.selected = None;\n    Text<96> line = Text<96> {};\n\n    cell(&line, \"MyOS\", COL_PID);\n    cell(&line, \"-\", COL_THREADS);\n    Text<24> kernel_threads = number_cell(now.cpu.kernel_threads, \"\");\n    cell(&line, kernel_threads.as_str(), COL_CPU);\n    Text<24> os_share = number_cell(t.latest(OS_SERIES), \"%\");\n    cell(&line, os_share.as_str(), COL_MEMORY);\n    cell(&line, \"-\", COL_STATE);\n    line.append(\"kernel\");\n    t.add_row(OS_KEY, line.as_str());\n\n    i32 threads = now.cpu.kernel_threads;\n    i32 live = 0;\n    i32 i = 0;\n    while (i < now.count) {\n        ProcInfo p = now.procs[i];\n        line.clear();\n        if (p.name.is_empty()) { cell(&line, \"?\", COL_PID); }\n        else { cell(&line, p.name.as_str(), COL_PID); }\n        Text<24> pid = number_cell(p.pid, \"\");\n        cell(&line, pid.as_str(), COL_THREADS);\n        Text<24> count = number_cell(p.threads, \"\");\n        cell(&line, count.as_str(), COL_CPU);\n        i32 percent = case t.series_of(p.pid) of { Some(series) -> t.latest(series); None -> 0; };\n        Text<24> cpu = number_cell(percent, \"%\");\n        cell(&line, cpu.as_str(), COL_MEMORY);\n        Text<24> memory = number_cell(p.pages * 4, \" KB\");\n        cell(&line, memory.as_str(), COL_STATE);\n        line.append(activity_name(p.activity));\n        t.add_row(p.pid, line.as_str());\n        threads = threads + p.threads;\n        if (p.activity != ProcActivity::Ended) { live++; }\n        i++;\n    }\n\n    t.cpu.clear();\n    t.cpu.append(\"CPU \");\n    Text<24> total = number_cell(t.latest(CPU_SERIES), \"%\");\n    t.cpu.append(total.as_str());\n    t.fill = t.series_text(CPU_SERIES);\n\n    t.chosen.clear();\n    t.line.clear();\n    case t.selected of {\n        Some(row) -> ({\n            case t.series_of(t.selected_key) of {\n                Some(series) -> ({\n                    t.line = t.series_text(series);\n                    Text<24> name = t.row_name(row);\n                    t.chosen.append(name.as_str());\n                    t.chosen.append(\" \");\n                    Text<24> mine = number_cell(t.latest(series), \"%\");\n                    t.chosen.append(mine.as_str());\n                });\n                None -> _;\n            };\n        });\n        None -> _;\n    };\n\n    t.summary.clear();\n    Text<24> processes = count_of(live, \"process\", \"processes\");\n    t.summary.append(processes.as_str());\n    t.summary.append(\", \");\n    Text<24> thread_count = count_of(threads, \"thread\", \"threads\");\n    t.summary.append(thread_count.as_str());\n    t.summary.append(\", \");\n    Text<24> used = megabytes(now.total_pages - now.free_pages);\n    t.summary.append(used.as_str());\n    t.summary.append(\" of \");\n    Text<24> total = megabytes(now.total_pages);\n    t.summary.append(total.as_str());\n    t.summary.append(\" in use\");\n}\n\n/**\n * The name in a row: its text up to the first tab.\n * @param row The row.\n * @return The name.\n */\nText<24> (borrow Tasks t) row_name(i32 row) {\n    str rows = t.rows.as_str();\n    i32 start = 0;\n    i32 line = 0;\n    while (line < row) {\n        while (start < rows.length && rows.byte(start) != '\\n') { start++; }\n        start++;\n        line++;\n    }\n    i32 end = start;\n    while (end < rows.length && rows.byte(end) != '\\t' && rows.byte(end) != '\\n') { end++; }\n    Text<24> name = Text<24> {};\n    case rows.slice(start, end) of { Some(view) -> ({ name.append(view); }); None -> _; };\n    return name;\n}\n\ni32 main() { return app.run<Tasks>(); }\n","system/MyOS/src/ipc/channel.unsafe.mln":"/**\n * The UI server's inbound side of the UI protocol.\n *\n * Receives application requests across a shared kernel IPC channel.\n * Each request carries the sender's reply channel handle; `serve()` processes\n * all queued requests on the compositor task pass and sends replies back.\n * Requests enter this channel via the OS_CALL gateway, which copies user-space\n * memory into kernel-owned buffers.\n */\nnamespace request_channel;\n\nimport ipc from \"@kernel/kernel/ipc.mln\";\nimport { ChannelId } from \"@kernel/kernel/ipc.mln\";\nimport { Request, RequestDomain, RequestStatus, TransportSignal } from \"@contracts/myapp/message.contract.mln\";\nimport ui_protocol from \"@os/ui/protocol.mln\";\nimport shell_protocol from \"@os/shell/protocol.mln\";\nimport app_events from \"events.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport scheduler from \"@kernel/kernel/scheduler.mln\";\nimport { KernelSignal } from \"@kernel/kernel/thread.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\n\nChannelId g_requests = ChannelId(0);   // apps -> server\n\n// Request's wire order is intentionally isolated here. Gateway and protocol\n// code should use the named Request fields, not positional word offsets.\nenum RequestWord {\n    DOMAIN = 0,\n    OP,\n    OWNER,\n    A0,\n    A1,\n    A2,\n    A3,\n    A4,\n    A5,\n    S0,\n    S1,\n    RESULT_OUT,\n    RESULT_SIZE,\n    S0_LEN,\n    S1_LEN,\n    REPLY_CHANNEL,\n}\n\nexport const i32 REQUEST_WORD_COUNT = RequestWord::REPLY_CHANNEL;\n\n/**\n * Clears a full IPC message before populating its meaningful words.\n * @param words Destination message buffer with at least MSG_WORDS entries.\n */\nvoid clear_message(i32 *words) {\n    i32 word = 0;\n    while (word < ipc.MSG_WORDS) {\n        words[word] = 0;\n        word++;\n    }\n}\n\n/**\n * Decodes the 15-word Request prefix of an IPC message into named fields.\n * @param words Source wire words.\n * @param request Destination Request structure.\n */\nexport void decode_request_words(i32 *words, Request *request) {\n    request->domain = words[RequestWord::DOMAIN];\n    request->op = words[RequestWord::OP];\n    request->owner = words[RequestWord::OWNER];\n    request->a0 = words[RequestWord::A0];\n    request->a1 = words[RequestWord::A1];\n    request->a2 = words[RequestWord::A2];\n    request->a3 = words[RequestWord::A3];\n    request->a4 = words[RequestWord::A4];\n    request->a5 = words[RequestWord::A5];\n    request->s0 = (char*)words[RequestWord::S0];\n    request->s1 = (char*)words[RequestWord::S1];\n    request->result_out = words[RequestWord::RESULT_OUT];\n    request->result_size = words[RequestWord::RESULT_SIZE];\n    request->s0_len = words[RequestWord::S0_LEN];\n    request->s1_len = words[RequestWord::S1_LEN];\n}\n\n/**\n * Encodes a Request into the fixed-size IPC message and appends its reply channel.\n * @param request Request to encode.\n * @param reply_channel Channel that should receive the response.\n * @param words Destination message buffer with at least MSG_WORDS entries.\n */\nvoid encode_request_words(Request *request, ChannelId reply_channel, i32 *words) {\n    clear_message(words);\n    words[RequestWord::DOMAIN] = request->domain;\n    words[RequestWord::OP] = request->op;\n    words[RequestWord::OWNER] = request->owner;\n    words[RequestWord::A0] = request->a0;\n    words[RequestWord::A1] = request->a1;\n    words[RequestWord::A2] = request->a2;\n    words[RequestWord::A3] = request->a3;\n    words[RequestWord::A4] = request->a4;\n    words[RequestWord::A5] = request->a5;\n    words[RequestWord::S0] = (i32)request->s0;\n    words[RequestWord::S1] = (i32)request->s1;\n    words[RequestWord::RESULT_OUT] = request->result_out;\n    words[RequestWord::RESULT_SIZE] = request->result_size;\n    words[RequestWord::S0_LEN] = request->s0_len;\n    words[RequestWord::S1_LEN] = request->s1_len;\n    words[RequestWord::REPLY_CHANNEL] = (i32)reply_channel;\n}\n\n/**\n * Initializes the server-side request receiving channel and outbound event system.\n */\nexport void init() {\n    if (g_requests == ChannelId(0)) {\n        Option<ChannelId> channel = ipc.create();\n        case channel of {\n            Some(value) -> ({ g_requests = value; });\n            None -> ({ debug.panic(\"request_channel: IPC channel table exhausted\"); });\n        };\n    }\n    app_events.init();\n}\n\n/**\n * Enqueues a request into the global UI server request channel.\n *\n * Encodes a Request into the 24-word IPC message. Words 0..12 carry the\n * Request and word 13 carries the caller's reply channel handle.\n *\n * @param request Request to enqueue.\n * @param reply_channel Channel that should receive the response.\n * @return True if successfully queued, false if request ring is full.\n */\nexport bool submit(Request *request, ChannelId reply_channel) {\n    i32 words[24];\n    encode_request_words(request, reply_channel, &words[0]);\n    if (!ipc.send(g_requests, &words[0])) { return false; }\n    scheduler.notify_armed(KernelSignal::SERVICE);   // the server task answers it\n    return true;\n}\n\n/**\n * Processes and answers all queued UI and application requests.\n *\n * Runs on the UI server / compositor task. Dispatches requests to `ui_protocol`\n * or `shell_protocol` based on `domain`, and sends the result word to the caller's\n * reply channel.\n *\n * @return True if this pass answered at least one request.\n */\nexport bool serve() {\n    bool served = false;\n    i32 w[24];\n    while (ipc.recv(g_requests, &w[0])) {\n        // A successful receive makes at least one slot available. Failed\n        // submitters armed this bit before returning to user space.\n        scheduler.notify_armed(TransportSignal::REQUEST_SPACE);\n        served = true;\n        Request m;\n        decode_request_words(&w[0], &m);\n        i32 r[24];\n        clear_message(&r[0]);\n        r[0] = RequestStatus::INVALID_DOMAIN;\n        if (m.domain == RequestDomain::UI) { r[0] = ui_protocol.handle(&m); }\n        if (m.domain == RequestDomain::APP) { r[0] = shell_protocol.handle(&m); }\n        ChannelId reply_channel = ChannelId(w[RequestWord::REPLY_CHANNEL]);\n        if (!ipc.send(reply_channel, &r[0])) {\n            debug.panic(\"request_channel: reply channel full\");\n        }\n        scheduler.notify_pid(Pid(m.owner), TransportSignal::REPLY);\n    }\n    return served;\n}\n","system/MyOS/src/ipc/events.unsafe.mln":"/**\n * The server's outbound side of the UI protocol: events for applications.\n *\n * Dispatches UI events (Event contract) to per-process kernel IPC channels.\n * The DOM, widgets, and shell push events here on the UI server task whenever\n * an owned node is modified or triggered; applications retrieve them via POLL.\n *\n * An owner is a PID. Events for an owner without an active channel binding are dropped.\n */\nnamespace app_events;\n\nimport ipc from \"@kernel/kernel/ipc.mln\";\nimport { ChannelId } from \"@kernel/kernel/ipc.mln\";\nimport { EventKind, TransportSignal } from \"@contracts/myapp/message.contract.mln\";\nimport ui_event from \"@os/ui/events.mln\";\nimport { UiEventKind } from \"@os/ui/events.mln\";\nimport { NodeId } from \"@contracts/ui/widget.contract.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\nimport { ShellEventKind } from \"@os/shell/events.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport str from \"@std/text/str.mln\";\nimport scheduler from \"@kernel/kernel/scheduler.mln\";\n\ni32 OWNERS_MAX = 16;\n/**\n * Event-routing binding between one app process and its kernel IPC channel.\n * @property owner Process using this binding; None means the record is free.\n * @property channel Channel ID to which this owner's outgoing events are queued.\n */\nstruct EventBinding {\n    Option<Pid> owner;\n    ChannelId channel;\n};\nEventBinding event_bindings[16];\n\n/**\n * Queues a UI-domain event for its owning application.\n *\n * The UI and wire enums use the same values for these event kinds. Keep them\n * aligned; NONE and all other values are dropped.\n *\n * @param owner Process ID owning the target UI node.\n * @param id UI node ID.\n * @param kind Event type (UiEventKind enum).\n * @param arg Event-specific numeric argument (e.g. checkbox state, timer ticks).\n */\nvoid forward_ui_event(Pid owner, NodeId id, i32 kind, i32 arg) {\n    if (kind == UiEventKind::CLICK ||\n        kind == UiEventKind::CHANGE ||\n        kind == UiEventKind::ACTIVATE ||\n        kind == UiEventKind::TIMER ||\n        kind == UiEventKind::CARET) {\n        push(owner, (i32)id, kind, arg, 0, \"\");\n    }\n}\n\n/**\n * Initializes the application event dispatcher.\n *\n * Registers `forward_ui_event` as the sink for low-level UI events.\n */\nexport void init() { ui_event.set_sink(forward_ui_event); }\n\n/**\n * Adapts and enqueues a shell policy notification to the application wire contract.\n *\n * Translates ShellEventKind (KEY, CLOSE, OPEN) into wire EventKind and pushes\n * to the channel. Their numeric values differ because the wire enum also\n * contains UI events, so each shell variant must be mapped explicitly.\n *\n * @param owner Process ID owning the target window.\n * @param id Window or control node ID.\n * @param kind Shell event type (ShellEventKind enum).\n * @param arg Numeric argument (e.g. key code or modifiers).\n * @param token Correlation token or modifier flags.\n * @param text Optional text payload (e.g. file path on OPEN).\n */\nexport void push_shell(Pid owner, i32 id, i32 kind, i32 arg, i32 token, str text) {\n    if (kind == ShellEventKind::KEY) {\n        push(owner, id, EventKind::KEY, arg, token, text);\n    } else if (kind == ShellEventKind::CLOSE) {\n        push(owner, id, EventKind::CLOSE, arg, token, text);\n    } else if (kind == ShellEventKind::OPEN) {\n        push(owner, id, EventKind::OPEN, arg, token, text);\n    }\n}\n\n/**\n * Binds an IPC channel to a process owner ID for routing outbound events.\n *\n * @param owner Process ID.\n * @param channel Kernel IPC channel handle.\n */\nexport void bind(Pid owner, ChannelId channel) {\n    Option<i32> free = None;\n    i32 i = 0;\n    while (i < OWNERS_MAX) {\n        case event_bindings[i].owner of {\n            Some(bound) -> ({ if (bound == owner) { event_bindings[i].channel = channel; return; } });\n            None -> ({ if (free.is_none()) { free = Some(i); } });\n        };\n        i++;\n    }\n    case free of {\n        Some(slot) -> ({\n            event_bindings[slot].owner = Some(owner);\n            event_bindings[slot].channel = channel;\n        });\n        None -> _;\n    };\n}\n\n/**\n * Removes a process owner's event binding, so nothing is queued for its pid.\n *\n * @param owner Process ID.\n */\nexport void unbind(Pid owner) {\n    i32 i = 0;\n    while (i < OWNERS_MAX) {\n        case event_bindings[i].owner of {\n            Some(bound) -> ({ if (bound == owner) { event_bindings[i].owner = None; return; } });\n            None -> _;\n        };\n        i++;\n    }\n}\n\n/**\n * Retrieves the bound IPC channel handle for a given process owner.\n *\n * @param owner Process ID.\n * @return Some(channel) if bound, or None if this owner has no event channel.\n */\nOption<ChannelId> channel_of(Pid owner) {\n    i32 i = 0;\n    while (i < OWNERS_MAX) {\n        case event_bindings[i].owner of {\n            Some(bound) -> ({ if (bound == owner) { return Some(event_bindings[i].channel); } });\n            None -> _;\n        };\n        i++;\n    }\n    return None;\n}\n\ni32 dropped_count = 0;   // events lost to a full channel (an app that stopped polling)\n\n/**\n * Queues an event for a process owner.\n *\n * For TIMER events, suppresses redundant ticks if an earlier tick is already pending\n * in the channel (ensuring slow apps do not build up unbound backlogs).\n * Drops and counts the event if the destination channel ring is full.\n *\n * @param owner Process ID of recipient.\n * @param id UI node ID.\n * @param kind EventKind enum.\n * @param arg Numeric argument.\n * @param token Correlation token or secondary argument.\n * @param text Optional text copied into the queued event's inline payload.\n */\nexport void push(Pid owner, i32 id, i32 kind, i32 arg, i32 token, str text) {\n    Option<ChannelId> bound = channel_of(owner);\n    ChannelId ch = case bound of {\n        Some(value) -> value;\n        None -> ({ return; });\n    };\n    if (kind == EventKind::TIMER) {\n        if (ipc.has(ch, id, kind)) { return; }\n    }\n    i32 w[24];\n    w[0] = (i32)owner;\n    w[1] = id;\n    w[2] = kind;\n    w[3] = arg;\n    w[4] = token;\n    char *inline_text = (char*)(&w[5]);\n    i32 text_i = 0;\n    while (text_i < 64) {\n        i32 c = 0;\n        if (text_i < 63) { c = text.byte(text_i); }\n        inline_text[text_i] = (char)c;\n        text_i++;\n    }\n    if (!ipc.send(ch, &w[0])) {\n        dropped_count++;\n        return;\n    }\n    scheduler.notify_pid(owner, TransportSignal::EVENT);\n}\n","system/MyOS/src/ipc/gateway.unsafe.mln":"/**\n * User/kernel boundary gateway for application request/event transport.\n *\n * Copies pointers, strings, and output buffers across page tables into kernel-owned\n * memory. Ensures the service task sees only validated, kernel-resident data.\n */\nnamespace request_gateway;\n\nimport mem from \"@kernel/mm/mem.mln\";\nimport ipc from \"@kernel/kernel/ipc.mln\";\nimport { ChannelId } from \"@kernel/kernel/ipc.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport str from \"@std/text/str.mln\";\nimport heap from \"@kernel/mm/heap.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport user_memory from \"@os/syscall/user_memory.mln\";\nimport { UserAddress } from \"@std/core/address.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\nimport request_channel from \"channel.mln\";\nimport app_events from \"events.mln\";\nimport { Request, RequestDomain, TransportSignal } from \"@contracts/myapp/message.contract.mln\";\nimport { UiOp } from \"@contracts/myapp/ui.contract.mln\";\nimport { UiError } from \"@contracts/ui/widget.contract.mln\";\nimport scheduler from \"@kernel/kernel/scheduler.mln\";\nimport process from \"@kernel/kernel/process.mln\";\n\ni32 S0_CAP = 1024;\ni32 S1_CAP = 128;\ni32 OUT_CAP = 4096;\n// A server writes a typed Result through the staged pointer at its full\n// size, whatever result_size the caller asked to have copied back, so the\n// buffer must hold the largest one: Result<Option<i32>, UiError> (48 bytes;\n// see check_result_capacity). At 32 bytes every UI result overflowed into the\n// next heap block.\ni32 RESULT_CAP = 64;\n\n// Keep the transport state for one process together. The old parallel\n// arrays made it easy to update one table and forget its companion table.\n/**\n * Per-process channels and kernel staging buffers for the request gateway.\n * @property reply_ch IPC channel for replies sent to this process.\n * @property event_ch IPC channel for events sent to this process.\n * @property events_bound True while app_events routes this slot's owner to event_ch.\n * @property s0 Kernel copy of the first request string argument.\n * @property s1 Kernel copy of the second request string argument.\n * @property out Kernel staging buffer for request output bytes.\n * @property out_user User-space address that receives staged output.\n * @property out_cap Capacity of the output staging buffer in bytes.\n * @property result Kernel address of the typed Result value returned to the user.\n * @property result_user User-space address that receives the typed Result value.\n * @property result_size Size in bytes of the staged typed Result value.\n */\nstruct GatewaySlot {\n    ChannelId reply_ch;\n    ChannelId event_ch;\n    bool events_bound;\n    i32 s0;\n    i32 s1;\n    i32 out;\n    UserAddress out_user;\n    i32 out_cap;\n    i32 result;\n    UserAddress result_user;\n    i32 result_size;\n};\n\nGatewaySlot gateway_slots[16];\n\n/** Stops the kernel if a typed request result outgrows its staging buffer. */\nvoid check_result_capacity() {\n    if (sizeof(Result<Option<i32>, UiError>) > RESULT_CAP) {\n        debug.panic(\"request_gateway: RESULT_CAP is smaller than a UI request result\");\n    }\n}\n\n/**\n * Allocates kernel heap memory or panics if allocation fails.\n *\n * @param n Number of bytes to allocate.\n * @return Memory address of allocated block.\n */\ni32 alloc_or_panic(i32 n) {\n    return case heap.alloc(n) of {\n        Ok(pointer) -> pointer;\n        Err(_) -> ({ debug.panic(\"request_gateway: out of memory\"); 0; });\n    };\n}\n\n/**\n * Reads the fixed-width Request wire record and decodes it into named fields.\n * @param user_request User-space address of a 15-word Request.\n * @param request Destination Request structure.\n */\nvoid read_user_request(UserAddress user_request, Request *request) {\n    i32 words[15];\n    i32 word = 0;\n    while (word < request_channel.REQUEST_WORD_COUNT) {\n        words[word] = user_memory.read_word(user_request.plus(word * 4));\n        word++;\n    }\n    request_channel.decode_request_words(&words[0], request);\n}\n\n/**\n * Copies user-owned string arguments into this process's kernel staging buffers.\n * @param slot_index Gateway slot belonging to the caller.\n * @param request Request whose s0/s1 currently contain user addresses.\n */\nvoid copy_request_strings(i32 slot_index, Request *request) {\n    char *s0 = (char*)gateway_slots[slot_index].s0;\n    char *s1 = (char*)gateway_slots[slot_index].s1;\n    user_memory.copy_in_view(UserAddress((i32)request->s0), request->s0_len, s0, S0_CAP);\n    user_memory.copy_in_view(UserAddress((i32)request->s1), request->s1_len, s1, S1_CAP);\n    request->s0 = s0;\n    request->s1 = s1;\n}\n\n/**\n * Redirects operation output pointers to kernel staging buffers and remembers\n * the original user destinations for the reply path.\n * @param slot_index Gateway slot belonging to the caller.\n * @param request Request to update before it crosses into the server task.\n */\nvoid stage_request_outputs(i32 slot_index, Request *request) {\n    gateway_slots[slot_index].out_user = UserAddress(0);\n    gateway_slots[slot_index].result_user = UserAddress(0);\n\n    if (request->domain == RequestDomain::UI && request->op == UiOp::TEXT_COPY) {\n        gateway_slots[slot_index].out_user = UserAddress(request->a1);\n        gateway_slots[slot_index].out_cap = request->a2;\n        if (gateway_slots[slot_index].out_cap > OUT_CAP) {\n            gateway_slots[slot_index].out_cap = OUT_CAP;\n        }\n        request->a1 = gateway_slots[slot_index].out;\n        request->a2 = gateway_slots[slot_index].out_cap;\n    }\n\n    if (request->result_out != 0 && request->result_size > 0) {\n        gateway_slots[slot_index].result_user = UserAddress(request->result_out);\n        gateway_slots[slot_index].result_size = request->result_size;\n        if (gateway_slots[slot_index].result_size < 0) {\n            gateway_slots[slot_index].result_size = 0;\n        }\n        if (gateway_slots[slot_index].result_size > RESULT_CAP) {\n            gateway_slots[slot_index].result_size = RESULT_CAP;\n        }\n        request->result_out = gateway_slots[slot_index].result;\n        request->result_size = gateway_slots[slot_index].result_size;\n    }\n}\n\n/**\n * Lazily initializes per-process IPC reply/event channels and staging buffers.\n *\n * A slot keeps its channels and buffers from one holder of the pid to the next.\n * Its event channel is bound to the process in `app_events` for each holder.\n *\n * @param pid Process ID.\n * @return `true` when the PID has a gateway slot; `false` when it is invalid.\n */\nbool ready(Pid pid) {\n    i32 i = case process.slot_of(pid) of {\n        Some(v) -> v;\n        None -> ({ return false; });\n    };\n    if (gateway_slots[i].reply_ch == ChannelId(0)) {\n        Option<ChannelId> reply_channel = ipc.create();\n        Option<ChannelId> event_channel = ipc.create();\n        case reply_channel of {\n            Some(value) -> ({ gateway_slots[i].reply_ch = value; });\n            None -> ({ debug.panic(\"request_gateway: IPC reply channel table exhausted\"); });\n        };\n        case event_channel of {\n            Some(value) -> ({ gateway_slots[i].event_ch = value; });\n            None -> ({ debug.panic(\"request_gateway: IPC event channel table exhausted\"); });\n        };\n        gateway_slots[i].s0 = alloc_or_panic(S0_CAP);\n        gateway_slots[i].s1 = alloc_or_panic(S1_CAP);\n        gateway_slots[i].out = alloc_or_panic(OUT_CAP);\n        check_result_capacity();\n        gateway_slots[i].result = alloc_or_panic(RESULT_CAP);\n    }\n    if (!gateway_slots[i].events_bound) {\n        app_events.bind(pid, gateway_slots[i].event_ch);\n        gateway_slots[i].events_bound = true;\n    }\n    return true;\n}\n\n/**\n * Handles OS_CALL REQUEST: validates and submits a UI/App request from a user process.\n *\n * Decodes the user Request into its named fields, copies string arguments to\n * kernel staging buffers, redirects output buffers, and queues it to\n * `request_channel`.\n *\n * @param pid Process ID of the caller.\n * @param user_request Virtual address of user Request structure (13 words).\n * @return true when queued; false when the shared request channel is full.\n *         A full channel is transient and may be retried. The PID comes from\n *         the current-process syscall context and must be valid.\n */\nexport bool request(Pid pid, UserAddress user_request) {\n    if (!ready(pid)) { debug.panic(\"request_gateway: invalid caller PID\"); }\n    i32 i = case process.slot_of(pid) of {\n        Some(v) -> v;\n        None -> ({ debug.panic(\"request_gateway: PID slot disappeared\"); return false; });\n    };\n    Request request;\n    read_user_request(user_request, &request);\n    request.owner = (i32)pid;\n    copy_request_strings(i, &request);\n    stage_request_outputs(i, &request);\n    if (!request_channel.submit(&request, gateway_slots[i].reply_ch)) {\n        scheduler.arm_notification(TransportSignal::REQUEST_SPACE);\n        return false;\n    }\n    scheduler.disarm_notification(TransportSignal::REQUEST_SPACE);\n    return true;\n}\n\n/**\n * Handles OS_CALL REPLY: retrieves a response to a previously submitted request.\n *\n * Checks the process's reply channel, copies any buffered string results back\n * to user memory space, and writes the return scalar into `user_out`.\n *\n * @param pid Process ID.\n * @param user_out Destination virtual address in user space for the return scalar.\n * @return True if a reply was received.\n */\nexport bool reply(Pid pid, UserAddress user_out) {\n    i32 i = case process.slot_of(pid) of {\n        Some(v) -> v;\n        None -> ({ debug.panic(\"request_gateway: invalid reply PID\"); return false; });\n    };\n    if (gateway_slots[i].reply_ch == ChannelId(0)) { return false; }\n    i32 r[24];\n    if (!ipc.recv(gateway_slots[i].reply_ch, &r[0])) {\n        scheduler.arm_notification(TransportSignal::REPLY);\n        return false;\n    }\n    scheduler.disarm_notification(TransportSignal::REPLY);\n    if ((i32)gateway_slots[i].out_user != 0) {\n        i32 n = str.len((char*)gateway_slots[i].out) + 1;\n        if (n > gateway_slots[i].out_cap) { n = gateway_slots[i].out_cap; }\n        user_memory.copy_out(gateway_slots[i].out_user, (char*)gateway_slots[i].out, n);\n        gateway_slots[i].out_user = UserAddress(0);\n    }\n    if ((i32)gateway_slots[i].result_user != 0 && gateway_slots[i].result_size > 0) {\n        user_memory.copy_out(gateway_slots[i].result_user, (char*)gateway_slots[i].result, gateway_slots[i].result_size);\n    }\n    gateway_slots[i].result_user = UserAddress(0);\n    gateway_slots[i].result_size = 0;\n    user_memory.write_word(user_out, r[0]);\n    return true;\n}\n\n/**\n * Handles OS_CALL POLL: polls for queued events addressed to this process.\n *\n * If an event is pending, populates the user Event struct and copies any\n * associated text payload into user memory.\n *\n * @param pid Process ID.\n * @param user_event Pointer to an Event with its own inline text storage.\n * @return True if an event was dequeued.\n */\nexport bool poll(Pid pid, UserAddress user_event) {\n    if (!ready(pid)) { debug.panic(\"request_gateway: invalid poll PID\"); }\n    i32 i = case process.slot_of(pid) of {\n        Some(v) -> v;\n        None -> ({ debug.panic(\"request_gateway: PID slot disappeared\"); return false; });\n    };\n    i32 w[24];\n    if (!ipc.recv(gateway_slots[i].event_ch, &w[0])) {\n        scheduler.arm_notification(TransportSignal::EVENT);\n        return false;\n    }\n    scheduler.disarm_notification(TransportSignal::EVENT);\n    user_memory.write_word(user_event, w[0]);\n    user_memory.write_word(user_event.plus(4), w[1]);\n    user_memory.write_word(user_event.plus(8), w[2]);\n    user_memory.write_word(user_event.plus(12), w[3]);\n    user_memory.write_word(user_event.plus(16), w[4]);\n    // Words 5..20 contain the event-owned, NUL-terminated 64-byte payload.\n    user_memory.copy_out(user_event.plus(20), (char*)(&w[5]), 64);\n    user_memory.write_byte(user_event.plus(83), 0);\n    return true;\n}\n\n/**\n * Leaves a process's gateway slot as a new holder of the pid must find it.\n *\n * Stops routing events to it, drains pending replies and events, and clears\n * the staging buffers a reply copies out of.\n *\n * @param pid Process ID of terminated process.\n */\nexport void process_gone(Pid pid) {\n    i32 i = case process.slot_of(pid) of { Some(v) -> v; None -> ({ return; }); };\n    app_events.unbind(pid);\n    gateway_slots[i].events_bound = false;\n    if (gateway_slots[i].reply_ch == ChannelId(0)) { return; }\n    i32 w[24];\n    while (ipc.recv(gateway_slots[i].reply_ch, &w[0])) { }\n    while (ipc.recv(gateway_slots[i].event_ch, &w[0])) { }\n    gateway_slots[i].out_user = UserAddress(0);\n    gateway_slots[i].result_user = UserAddress(0);\n    gateway_slots[i].result_size = 0;\n    mem.write_byte(gateway_slots[i].out, 0);\n    i32 at = 0;\n    while (at < RESULT_CAP) {\n        mem.write_byte(gateway_slots[i].result + at, 0);\n        at++;\n    }\n}\n","system/MyOS/src/proc/stats.unsafe.mln":"/**\n * What PROC_STATS reports: every process, what it is doing and what it costs,\n * and where the CPU's time went.\n *\n * The kernel keeps the numbers; this module adds the one thing it cannot know,\n * the name each process was started under, and reads it all at once.\n */\nnamespace proc_stats;\n\nimport { Option } from \"@std/core/option.mln\";\nimport { Text } from \"@std/text/text.mln\";\nimport str from \"@std/text/str.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport kernel_config from \"@kernel/kernel/kernel_config.mln\";\nimport mmu from \"@kernel/mm/mmu.mln\";\nimport frames from \"@kernel/mm/frames.mln\";\nimport process from \"@kernel/kernel/process.mln\";\nimport { ProcessState } from \"@kernel/kernel/process.mln\";\nimport scheduler from \"@kernel/kernel/scheduler.mln\";\nimport thread from \"@kernel/kernel/thread.mln\";\nimport { ThreadState } from \"@kernel/kernel/thread.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\nimport { ProcStats, ProcInfo, ProcActivity, CpuTimes } from \"@contracts/myos/process-args.contract.mln\";\n\n/**\n * The name a process slot's process was started under.\n * @property pid The process it was given for: a slot's next process has none\n *           until it is named, rather than the last one's.\n * @property name The name.\n */\nstruct ProcName {\n    i32 pid;\n    Text<16> name;\n};\n\nProcName g_names[16];\n\n/**\n * Remembers the name a process was started under: the last part of its path,\n * up to an extension. A longer name is cut.\n * @param pid The process just started.\n * @param path The path it was started from.\n */\nexport void name_process(Pid pid, str path) {\n    i32 slot = case process.slot_of(pid) of { Some(value) -> value; None -> ({ return; }); };\n    i32 start = 0;\n    i32 i = 0;\n    while (i < path.length) {\n        if (path.byte(i) == '/') { start = i + 1; }\n        i++;\n    }\n    i32 end = path.length;\n    i = start;\n    while (i < path.length) {\n        if (path.byte(i) == '.') { end = i; }\n        i++;\n    }\n    ProcName named = ProcName { pid: (i32)pid, name: Text<16> {} };\n    case path.slice(start, end) of {\n        Some(name) -> ({ named.name.append(name); });\n        None -> _;\n    };\n    g_names[slot] = named;\n}\n\n/**\n * Reads every process, the CPU's time and the free memory, with interrupts off\n * so the numbers are from one moment.\n * @param out Where they go; `count` says how many processes there were.\n */\nexport void fill(borrow ProcStats out) {\n    bool was_enabled = irq.save_disable();\n    defer irq.restore(was_enabled);\n    // The time up to now first, so the counts and the total meet.\n    scheduler.charge_elapsed();\n    out.cpu = CpuTimes {\n        total: scheduler.cpu_total(),\n        idle: scheduler.idle_time(),\n        kernel: scheduler.kernel_time(),\n        kernel_threads: live_kernel_threads(),\n    };\n    out.total_pages = frames.total();\n    out.free_pages = frames.available();\n    out.count = 0;\n    i32 slot = 0;\n    while (slot < kernel_config.MAX_PROCS) {\n        case process.pid_at(slot) of {\n            Some(pid) -> ({\n                out.procs[out.count] = process_info(pid, slot);\n                out.count++;\n            });\n            None -> _;\n        };\n        slot++;\n    }\n}\n\n/**\n * One process.\n * @param pid The process.\n * @param slot Its process slot, where its name is.\n * @return What PROC_STATS says of it.\n */\nProcInfo process_info(Pid pid, i32 slot) {\n    i32 parent = case process.parent_of(pid) of {\n        Some(held) -> case held of { Some(owner) -> (i32)owner; None -> 0; };\n        None -> 0;\n    };\n    ProcInfo p = ProcInfo {\n        pid: (i32)pid,\n        parent: parent,\n        activity: process_activity(pid),\n        threads: process.live_thread_count(pid).unwrap_or(0),\n        cpu_time: process.cpu_time(pid).unwrap_or(0),\n        pages: mmu.count_user_pages(process.get_pdbr(pid).unwrap_or(0)),\n        name: Text<16> {},\n    };\n    ProcName named = g_names[slot];\n    if (named.pid == (i32)pid) { p.name.append(named.name.as_str()); }\n    return p;\n}\n\n/**\n * @param pid A process.\n * @return What it is doing.\n */\nProcActivity process_activity(Pid pid) {\n    ProcessState state = case process.get_state(pid) of {\n        Some(value) -> value;\n        None -> ({ return ProcActivity::Ended; });\n    };\n    return case state of {\n        ProcessState::Loading -> ProcActivity::Starting;\n        ProcessState::Alive -> process_runs(pid) ? ProcActivity::Running : ProcActivity::Waiting;\n        ProcessState::Exiting(_) -> ProcActivity::Exiting;\n        _ -> ProcActivity::Ended;\n    };\n}\n\n/**\n * @param pid A process.\n * @return Whether one of its threads is running or ready to.\n */\nbool process_runs(Pid pid) {\n    i32 slot = 0;\n    while (slot < thread.high_water()) {\n        bool mine = case thread.owner_pid_at(slot) of { Some(owner) -> owner == pid; None -> false; };\n        if (mine && thread_is_ready(slot)) { return true; }\n        slot++;\n    }\n    return false;\n}\n\n/**\n * @param slot A thread slot.\n * @return Whether its thread is running or ready to.\n */\nbool thread_is_ready(i32 slot) {\n    return case thread.state_at(slot) of {\n        Some(state) -> case state of {\n            ThreadState::Runnable -> true;\n            ThreadState::Running -> true;\n            _ -> false;\n        };\n        None -> false;\n    };\n}\n\n/** @return The OS's own threads that have not ended. */\ni32 live_kernel_threads() {\n    i32 count = 0;\n    i32 slot = 0;\n    while (slot < thread.high_water()) {\n        bool kernel = case thread.owner_pid_at(slot) of { Some(_) -> false; None -> thread.occupied(slot); };\n        bool live = case thread.state_at(slot) of {\n            Some(state) -> case state of {\n                ThreadState::Exiting(_) -> false;\n                ThreadState::Zombie(_) -> false;\n                _ -> true;\n            };\n            None -> false;\n        };\n        if (kernel && live) { count++; }\n        slot++;\n    }\n    return count;\n}\n","system/MyOS/src/syscall/router.unsafe.mln":"/**\n * Single registration point and dispatcher for OS_CALL system calls.\n *\n * Domain syscall endpoints and the UI request gateway handle user-memory\n * copying before invoking MyOS implementations.\n */\nnamespace os_call_router;\n\nimport syscall from \"@kernel/kernel/syscall.mln\";\nimport debug from \"@kernel/debug/debug.mln\";\nimport { OsService, OsServiceError, LogArgs } from \"@contracts/myos/services.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport user_memory from \"user_memory.mln\";\nimport { copy_in_text } from \"user_memory.mln\";\nimport { UserAddress } from \"@std/core/address.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\nimport request_gateway from \"@os/ipc/gateway.mln\";\nimport fs_syscall from \"@os/fs/syscall.mln\";\nimport process_syscall from \"@os/proc/syscall.mln\";\nimport console from \"@os/proc/console.mln\";\nimport request_channel from \"@os/ipc/channel.mln\";\nimport app_events from \"@os/ipc/events.mln\";\nimport app from \"@os/shell/app.mln\";\nimport { Text } from \"@std/text/text.mln\";\n\nText<128> g_log_line;\n\n/**\n * Dispatches an OS_CALL request to the corresponding boundary endpoint.\n *\n * Routes IPC requests, filesystem calls, process lifecycle calls, and debug\n * logging based on the service identifier.\n *\n * @param pid Process ID of the caller.\n * @param service Service code identifying the requested operation (OsService enum).\n * @param args Virtual address of argument struct or scalar argument in caller's memory space.\n * @return Ok(service status/result), or Err(UnknownService).\n */\nResult<i32, OsServiceError> handle(Pid pid, i32 service, UserAddress args) {\n    if (service == OsService::REQUEST) {\n        if (request_gateway.request(pid, args)) { return Ok(1); }\n        return Ok(0);\n    }\n    if (service == OsService::REPLY) {\n        if (request_gateway.reply(pid, args)) { return Ok(1); }\n        return Ok(0);\n    }\n    if (service == OsService::POLL) {\n        if (request_gateway.poll(pid, args)) { return Ok(1); }\n        return Ok(0);\n    }\n    if (service >= OsService::FS_OPEN && service <= OsService::FS_IS_DIR) {\n        fs_syscall.handle(pid, service, args)?;\n        return Ok(0);\n    }\n    if (service >= OsService::PROC_SPAWN && service <= OsService::PROC_ARGS) {\n        return process_syscall.handle(pid, service, args);\n    }\n    if (service == OsService::LOG) {\n        LogArgs request;\n        user_memory.copy_in(args, (char*)(&request), sizeof(request));\n        copy_in_text<128>(UserAddress((i32)request.text), request.length, &g_log_line);\n        debug.printf(\"[pid %d] \", (i32)pid);\n        debug.println(g_log_line.as_str());\n        return Ok(0);\n    }\n    return Err(OsServiceError::UnknownService(service));\n}\n\n/**\n * Releases what the layers above the console hold for a process that has ended.\n *\n * The order matters. Its last requests can still be queued, and each would\n * make a node or a reply under its pid after this ran, for the next holder to\n * find: answer them first, so the nodes are swept and the replies drained.\n *\n * @param pid Process that has ended; no thread of it can run again.\n */\nvoid release_process(Pid pid) {\n    request_channel.serve();\n    app.process_gone(pid);\n    request_gateway.process_gone(pid);\n    fs_syscall.process_gone(pid);\n}\n\n/**\n * Initializes the OS service router.\n *\n * Sets up the shell's event sink and the process teardown, and registers\n * `handle` as the OS_CALL handler with the kernel syscall subsystem.\n */\nexport void init() {\n    app.set_event_sink(app_events.push_shell);\n    console.set_process_gone_sink(release_process);\n    syscall.set_os_handler(handle);\n}\n","system/MyOS/src/ui/dom/dom_hit_test.mln":"namespace dom_hit_test;\n\nimport dom from \"dom.mln\";\nimport dom_menu from \"dom_menu.mln\";\nimport { NodeRow } from \"dom_model.mln\";\nimport { Blob } from \"@std/memory/blob.mln\";\nimport { NodeState, Children } from \"dom.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { NodeId } from \"@contracts/ui/widget.contract.mln\";\n\n// Read-only pointer-to-node lookup. The DOM owns the tree and its state;\n// this module owns the traversal policy used by input dispatch and automation.\n\n// Whether a point is inside a row's rectangle; an empty one holds nothing.\nbool row_contains(borrow NodeRow n, i32 px, i32 py) {\n    if (n.w == 0 || n.h == 0) { return false; }\n    return px >= n.x && py >= n.y && px < n.x + n.w && py < n.y + n.h;\n}\n\n// The topmost visible, hit-testable node within a row's subtree. Children are\n// walked as rows, so a subtree costs one lookup per node.\nOption<NodeId> hit_row(borrow NodeRow n, i32 px, i32 py) {\n    if (!(n.state & NodeState::VISIBLE)) { return None; }\n\n    bool inside = row_contains(&n, px, py);\n    Option<NodeId> found = None;\n    if (inside) {\n        if (n.state & NodeState::HIT_TESTABLE) { found = Some(n.id); }\n    }\n\n    // Children of a clipping container cannot be hit outside its bounds.\n    if (!inside) {\n        if (dom.clips_children(&n)) { return None; }\n    }\n\n    for (NodeId child_id in dom.children(n.id)) {\n        Option<NodeId> hit = hit_row(&dom.row_of(child_id), px, py);\n        if (hit.is_some()) { found = hit; }\n    }\n    return found;\n}\n\n// The topmost visible, hit-testable node within an optional node's subtree.\nOption<NodeId> hit_test(Option<NodeId> node, i32 px, i32 py) {\n    return case dom.row_in(node) of {\n        Some(n) -> hit_row(&n, px, py);\n        None -> None;\n    };\n}\n\n/** Finds the topmost interactive UI node at a display position. */\nexport Option<NodeId> find_at(i32 x, i32 y) {\n    Option<NodeId> menu = dom_menu.menu_id();\n    Option<NodeId> menu_hit = hit_test(menu, x, y);\n    if (menu_hit.is_some()) { return menu_hit; }\n\n    Option<NodeId> taskbar = dom.taskbar_id();\n    Option<NodeId> taskbar_hit = hit_test(taskbar, x, y);\n    if (taskbar_hit.is_some()) { return taskbar_hit; }\n\n    Option<NodeId> found = None;\n    for (NodeId child_id in dom.children(dom.desktop_id())) {\n        if (!dom.holds(taskbar, child_id) && !dom.holds(menu, child_id)) {\n            Option<NodeId> hit = hit_row(&dom.row_of(child_id), x, y);\n            if (hit.is_some()) { found = hit; }\n        }\n    }\n    return found;\n}\n","system/MyOS/src/ui/dom/dom_model.model.mln":"namespace dom_model;\n\nimport { Blob } from \"@std/memory/blob.mln\";\nimport { NodeId } from \"@contracts/ui/widget.contract.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\n\n// The DOM's nodes. One tree holds the OS object model and the UI; the\n// children relation is the tree, and sibling order is paint order. The model\n// keeps ids as words; dom.mln turns them into NodeId. A stale one reaches no row.\nentity Node max 512 {\n    NodeId id;\n    i32 serial;      // when it was created: ids are reused, so order goes by this\n    u16 kind;\n    u16 role;        // ROLE_* ; 0 = none\n    u16 x;           // bounds in display pixels (UI nodes only, else 0)\n    u16 y;\n    u16 w;\n    u16 h;\n    u16 state;       // STATE_* bitmask\n    u16 style;       // STYLE_* bitmask\n    u16 padding;     // NODE_COLUMN/ROW inset, in display pixels\n    u16 gap;         // NODE_COLUMN/ROW gap between children, in display pixels\n    u16 cap;         // TextInput: buffer capacity in bytes\n    u16 len;         // TextInput: current text length\n    u16 cursor;      // TextInput: caret position (0..len)\n    u16 radius;      // Panel corner radius, display pixels\n    u16 scroll;      // TextArea/List: first visible row; Terminal: rows back from the end;\n                     // TextInput: display pixels its text is shifted left\n    Option<i32> sel; // List: selected row; Menu: hovered row; TextInput, TextArea and\n                     // Terminal: where a selection starts, the other end being\n                     // `cursor` (Terminal: `sel_end`); None = nothing selected\n    u16 sx;          // Window: bounds saved by maximize_window\n    u16 sy;\n    u16 sw;\n    u16 sh;\n    u16 sel_end;     // Terminal: where a selection made with the mouse ends\n    u16 edit;        // Terminal: the caret in the typed line, in bytes from its start\n    u16 icon;        // Window: its app's icon (Icon), for the taskbar\n    Blob name;\n    Blob text;       // display text / accessible name / edit buffer\n    Blob test_id;    // stable automation identity\n    fn(Option<Pid> owner, NodeId id, i32 arg) -> void on_click;\n    i32 background_color; // NODE_BOX fill colour (0 is valid black)\n    i32 border_color;     // NODE_BOX border colour\n    Option<i32> color;    // foreground/text colour; None = theme default\n    fn(Option<Pid> owner, NodeId id, i32 arg) -> void on_change;\n    fn(Option<Pid> owner, NodeId id, i32 arg) -> void on_tick;\n    i32 interval;         // Timer period in scheduler ticks\n    i32 next_due;         // Timer: tick at which it next fires\n    Option<Pid> owner;    // app process this node belongs to; None = system\n    fn(Option<Pid> owner, NodeId id, i32 arg) -> void on_close;\n}\n\nNode has many Node as children / parent, ordered;\n","system/MyOS/src/ui/dom/dom_render.mln":"namespace dom_render;\nimport debug from \"@kernel/debug/debug.mln\";\nimport blob from \"@std/memory/blob.mln\";\nimport graphics from \"@os/ui/graphics.mln\";\nimport theme from \"@os/ui/theme.mln\";\nimport str from \"@std/text/str.mln\";\nimport dom_menu from \"dom_menu.mln\";\nimport dom_graph from \"dom_graph.mln\";\nimport { Samples } from \"dom_graph.mln\";\nimport dom_text_edit from \"dom_text_edit.mln\";\nimport dom_terminal from \"dom_terminal.mln\";\nimport dom_scroll from \"dom_scroll.mln\";\nimport icons from \"@os/ui/icons.mln\";\nimport dom_window_chrome from \"dom_window_chrome.mln\";\nimport dom from \"dom.mln\";\nimport { NodeRow } from \"dom_model.mln\";\nimport { Blob } from \"@std/memory/blob.mln\";\nimport { NodeKind, NodeRole, NodeState, NodeStyle, Children } from \"dom.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Text } from \"@std/text/text.mln\";\nimport { NodeId } from \"@contracts/ui/widget.contract.mln\";\n\n// --- renderer ---------------------------------------------------------------------------------\n// Walk the UI subtree and paint each node with graphics.*. The renderer and\n// the window manager are one: z-order is sibling order (later siblings on\n// top), and hover/pressed/focus looks come from the node's state bitmask.\n// Colours and metrics come from theme.mln.\n//\n// Theme values are fetched into locals before use because a cross-package\n// call nested inside another package's argument list does not resolve.\n\n/**\n * Resolves foreground text color for a node, returning fallback if unset.\n * @param n DOM Node row.\n * @param fallback Default RGB color if the node has none.\n * @return Resolved RGB color.\n */\nexport i32 node_fg(borrow NodeRow n, i32 fallback) {\n    return case n.color of { Some(color) -> color; None -> fallback; };\n}\n\n/**\n * Renders a WINDOW node including drop shadow, title bar, chrome buttons, resize grip, and border.\n * @param n Window node row.\n */\nexport void draw_window(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 state = n.state;\n    i32 active = state & NodeState::FOCUSED;\n    i32 hovered = state & NodeState::HOVERED;\n\n    i32 r = theme.WINDOW_RADIUS * s;\n    i32 tb = theme.TITLEBAR_H * s;\n\n    // Shadow first, then the body over it.\n    i32 shadow = theme.SHADOW_SIZE * s;\n    i32 shadow_off = theme.SHADOW_OFFSET * s;\n    i32 shadow_a = theme.SHADOW_ALPHA;\n    if (!active) { shadow_a = theme.SHADOW_ALPHA_INACTIVE; }\n    graphics.draw_shadow(x, y, w, h, r, shadow, shadow_off, shadow_a);\n\n    i32 bg = theme.WINDOW_BG;\n    graphics.fill_round_rect(x, y, w, h, r, bg);\n\n    // Title bar: rounded on top, squared off where it meets the content.\n    i32 tb_top = theme.TITLEBAR_TOP;\n    i32 tb_bottom = theme.TITLEBAR_BOTTOM;\n    if (!active) {\n        tb_top = theme.TITLEBAR_INACTIVE;\n        tb_bottom = tb_top;\n    }\n    graphics.push_clip(x, y, w, tb);\n    graphics.fill_round_rect(x, y, w, tb + r, r, tb_top);\n    graphics.fill_gradient_v(x + r, y, w - 2 * r, tb, tb_top, tb_bottom);\n    graphics.fill_gradient_v(x, y + r, r, tb - r, tb_top, tb_bottom);\n    graphics.fill_gradient_v(x + w - r, y + r, r, tb - r, tb_top, tb_bottom);\n    graphics.pop_clip();\n    i32 divider = theme.TITLEBAR_DIVIDER;\n    graphics.blend_rect(x, y + tb - s, w, s, divider);\n\n    // Title-bar buttons: close, minimize, maximize discs; their glyphs\n    // (x, -, +) appear while the pointer is over the window.\n    i32 cy = dom_window_chrome.button_cy(&n);\n    i32 cr = dom_window_chrome.button_radius();\n    i32 ring = theme.CLOSE_BUTTON_RING;\n    i32 g = theme.CLOSE_GLYPH;\n    i32 k = cr / 2;\n    i32 buttons = dom_window_chrome.button_count(&n);\n    i32 which = 1;\n    while (which <= buttons) {\n        i32 bx = dom_window_chrome.button_cx(&n, which);\n        i32 face = theme.CLOSE_BUTTON;\n        if (which == 2) { face = theme.MINIMIZE_BUTTON; }\n        if (which == 3) { face = theme.MAXIMIZE_BUTTON; }\n        if (!active) { face = theme.CLOSE_BUTTON_INACTIVE; }\n        graphics.fill_disc(bx, cy, cr, face);\n        graphics.draw_round_rect(bx - cr, cy - cr, 2 * cr, 2 * cr, cr, s, ring);\n        if (hovered != 0) {\n            if (which == 1) {\n                graphics.draw_line(bx - k, cy - k, bx + k, cy + k, g);\n                graphics.draw_line(bx + k, cy - k, bx - k, cy + k, g);\n                graphics.draw_line(bx - k + 1, cy - k, bx + k + 1, cy + k, g);\n                graphics.draw_line(bx + k + 1, cy - k, bx - k + 1, cy + k, g);\n            }\n            if (which == 2) {\n                graphics.fill_rect(bx - k, cy - s / 2, 2 * k + 1, s + 1, g);\n            }\n            if (which == 3) {\n                graphics.fill_rect(bx - k, cy - s / 2, 2 * k + 1, s + 1, g);\n                graphics.fill_rect(bx - s / 2, cy - k, s + 1, 2 * k + 1, g);\n            }\n        }\n        which++;\n    }\n\n    // Resize grip: three short diagonal lines in the bottom-right corner. A\n    // dialog keeps its size.\n    if (!dom.is_dialog(&n)) {\n        i32 grip = theme.TEXT_DISABLED;\n        i32 gx = x + w - 4 * s;\n        i32 gy = y + h - 4 * s;\n        i32 d = 4 * s;\n        while (d <= 12 * s) {\n            graphics.draw_line(gx - d, gy, gx, gy - d, grip);\n            d = d + 4 * s;\n        }\n    }\n\n    // Title, centred, kept clear of the buttons.\n    if (n.text.is_live()) {\n        i32 title_color = theme.TEXT_PRIMARY;\n        if (!active) { title_color = theme.TEXT_SECONDARY; }\n        i32 th = graphics.text_height(1, s);\n        i32 inset = 2 * (dom_window_chrome.button_cx(&n, 3) - x);\n        graphics.push_clip(x + inset, y, w - 2 * inset, tb);\n        str label_1 = n.text.as_str();\n        graphics.draw_label_centered(x, y + (tb - th) / 2, w, label_1, title_color, 1, s);\n        graphics.pop_clip();\n    }\n\n    // Border last so it sits over the title bar edge.\n    i32 border = theme.WINDOW_BORDER;\n    if (!active) { border = theme.WINDOW_BORDER_INACTIVE; }\n    graphics.draw_round_rect(x, y, w, h, r, s, border);\n}\n\n/**\n * Renders a BUTTON node with hover, press, focus ring, and primary styling.\n * @param n Button node row.\n */\nexport void draw_button(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 state = n.state;\n    i32 style = n.style;\n    i32 r = theme.BUTTON_RADIUS * s;\n\n    i32 face = theme.BUTTON_FACE;\n    i32 label = theme.TEXT_PRIMARY;\n    i32 border = theme.BUTTON_BORDER;\n    if (style & NodeStyle::PRIMARY) {\n        face = theme.ACCENT;\n        label = theme.ON_ACCENT;\n        border = theme.ACCENT_PRESSED;\n        if (state & NodeState::PRESSED) { face = theme.ACCENT_PRESSED; }\n        else if (state & NodeState::HOVERED) { face = theme.ACCENT_HOVER; }\n    } else {\n        if (state & NodeState::PRESSED) { face = theme.BUTTON_FACE_PRESSED; }\n        else if (state & NodeState::HOVERED) { face = theme.BUTTON_FACE_HOVER; }\n    }\n    label = node_fg(&n, label);\n\n    graphics.fill_round_rect(x, y, w, h, r, face);\n    graphics.draw_round_rect(x, y, w, h, r, s, border);\n    if (state & NodeState::FOCUSED) {\n        // Keyboard focus ring just outside the button.\n        i32 ring = theme.ACCENT;\n        graphics.draw_round_rect(x - 2 * s, y - 2 * s, w + 4 * s, h + 4 * s, r + 2 * s, s, ring);\n    }\n    if (n.text.is_live()) {\n        i32 th = graphics.text_height(0, s);\n        graphics.push_clip(x, y, w, h);\n        str label_2 = n.text.as_str();\n        graphics.draw_label_centered(x, y + (h - th) / 2, w, label_2, label, 0, s);\n        graphics.pop_clip();\n    }\n}\n\n// --- TextArea / List / Menu rendering ---\n// All three are rows of text inside a rounded box; the list and menu add a\n// selection/hover highlight, the text area a caret.\n\n/**\n * Copies a slice of text bytes into a bounded Text for safe rendering.\n * @param buf Source text buffer.\n * @param start Start byte offset in source.\n * @param llen Number of bytes to copy.\n * @return A bounded NUL-terminated copy of the requested line.\n */\nexport Text<160> copy_line(Blob buf, i32 start, i32 llen) {\n    Text<160> out = Text<160> {};\n    out.clear();\n    i32 i = 0;\n    while (i < llen) {\n        if (!out.push((u8)buf.at(start + i))) { break; }\n        i++;\n    }\n    return out;\n}\n\n/**\n * Renders the background card and border for multi-row container controls.\n * @param n DOM Node row.\n * @param focused Non-zero if control has keyboard focus.\n */\nexport void draw_rows_box(borrow NodeRow n, i32 focused) {\n    i32 s = dom.ui_scale();\n    i32 r = theme.INPUT_RADIUS * s;\n    i32 bg = theme.INPUT_BG;\n    graphics.fill_round_rect(n.x, n.y, n.w, n.h, r, bg);\n    i32 border = theme.INPUT_BORDER;\n    i32 bw = s;\n    if (focused != 0) {\n        border = theme.INPUT_BORDER_FOCUS;\n        bw = 2 * s;\n    }\n    graphics.draw_round_rect(n.x, n.y, n.w, n.h, r, bw, border);\n}\n\n/**\n * Draws a box's scroll thumb when not all its rows fit (dom_scroll).\n * @param n TextArea, List or Terminal node row.\n * @param color The thumb's ARGB colour.\n */\nvoid draw_scroll_thumb(borrow NodeRow n, i32 color) {\n    case dom_scroll.bar_of(&n) of {\n        Some(b) -> ({\n            graphics.blend_rect(dom_scroll.thumb_left(b), dom_scroll.thumb_top(b),\n                                3 * dom.ui_scale(), dom_scroll.thumb_length(b), color);\n        });\n        None -> _;\n    };\n}\n\n/**\n * Renders a multi-line TEXT_AREA node, including text lines and cursor caret.\n * @param n TextArea node row.\n */\nexport void draw_text_area(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 state = n.state;\n    i32 focused = state & NodeState::FOCUSED;\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 pad = 8 * s;\n    i32 lh = graphics.text_height(0, s);\n    draw_rows_box(&n, focused);\n\n    i32 fg = theme.TEXT_PRIMARY;\n    fg = node_fg(&n, fg);\n    bool ro = dom_text_edit.is_readonly(&n);\n    Blob buf = n.text;\n    i32 len = n.len;\n    graphics.push_clip(x + s, y + s, w - 2 * s, h - 2 * s);\n    // Rows: lines, or lines broken to fit with NodeStyle::WRAP (dom_text_edit).\n    str text = n.text.as_str();\n    i32 rows = dom_text_edit.visible_lines(&n);\n    i32 first = n.scroll;\n    i32 start = dom_text_edit.row_start(&n, first);\n    i32 row = 0;\n    bool selecting = focused != 0 && dom_text_edit.has_selection(&n);\n    i32 sel_from = dom_text_edit.selection_start(&n);\n    i32 sel_to = dom_text_edit.selection_end(&n);\n    bool has_caret = false;\n    i32 caret_x = 0;\n    i32 caret_y = 0;\n    while (row < rows) {\n        i32 end = dom_text_edit.row_end(&n, text, start);\n        i32 llen = end - start;\n        i32 ty = y + pad + row * lh;\n        Text<160> line = copy_line(buf, start, llen);\n        str label_3 = line.as_str();\n        if (selecting && sel_from <= end && sel_to > start) {\n            // The part of this row inside the selection; a selected line break\n            // shows as a little more after the row's text.\n            i32 a = sel_from > start ? sel_from - start : 0;\n            i32 b = sel_to < end ? sel_to - start : llen;\n            i32 sel_left = x + pad + graphics.text_width_n(label_3, a, 0, s);\n            i32 sel_right = x + pad + graphics.text_width_n(label_3, b, 0, s);\n            if (sel_to > end && end < len) { sel_right = sel_right + 4 * s; }\n            if (sel_right > sel_left) { graphics.fill_rect(sel_left, ty, sel_right - sel_left, lh, theme.SELECTION); }\n        }\n        graphics.draw_label(x + pad, ty, label_3, fg, 0, s);\n        // The caret is in this row up to its end, unless a wrapped row breaks\n        // there: then it starts the next row.\n        i32 cur = n.cursor;\n        bool line_end = end >= len || text.byte(end) == '\\n';\n        if (cur >= start && (cur < end || cur == end && line_end)) {\n            str label_4 = line.as_str();\n            caret_x = x + pad + graphics.text_width_n(label_4, cur - start, 0, s);\n            caret_y = ty;\n            has_caret = true;\n        }\n        if (end >= len) { break; }\n        start = dom_text_edit.next_row_start(text, end);\n        row++;\n    }\n    if (focused != 0) {\n        if (!ro) {\n            if (has_caret) {\n                i32 caret = theme.CARET;\n                graphics.fill_rect(caret_x, caret_y + s, s, lh - 2 * s, caret);\n            }\n        }\n    }\n    graphics.pop_clip();\n    draw_scroll_thumb(&n, theme.SCROLL_THUMB);\n    // Empty editable area: placeholder from the node name.\n    if (len == 0) {\n        if (!ro) {\n            if (n.name.is_live()) {\n                i32 ph = theme.INPUT_PLACEHOLDER;\n                str label_5 = n.name.as_str();\n                graphics.draw_label(x + pad, y + pad, label_5, ph, 0, s);\n            }\n        }\n    }\n}\n\n/**\n * Renders a TERMINAL: its text on a grid of fixed-width cells, long lines\n * wrapped at the grid's width, the end in view unless it is scrolled back, and\n * a block caret after the typed line while it has the keyboard.\n * @param n Terminal node row.\n */\nexport void draw_terminal(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 pad = dom_terminal.PAD * s;\n    i32 cell = graphics.mono_cell_width(s);\n    i32 lh = graphics.mono_line_height(s);\n    i32 cols = dom_terminal.columns(&n);\n    i32 rows = dom_terminal.visible_rows(&n);\n    graphics.fill_rect(n.x, n.y, n.w, n.h, theme.TERMINAL_BG);\n\n    str text = n.text.as_str();\n    i32 total = dom_terminal.row_count(text, cols);\n    i32 first = total - rows - n.scroll;\n    if (first < 0) { first = 0; }\n    i32 left = n.x + pad;\n    i32 top = n.y + pad;\n    bool selecting = dom_terminal.has_selection(&n);\n    i32 sel_from = dom_terminal.selection_start(&n);\n    i32 sel_to = dom_terminal.selection_end(&n);\n    graphics.push_clip(n.x, n.y, n.w, n.h);\n    // `row` counts the rows of the whole text; the visible ones are first..first+rows.\n    i32 row = 0;\n    i32 start = 0;\n    bool done = false;\n    while (!done) {\n        i32 end = start;\n        while (end < text.length && text.byte(end) != '\\n') { end++; }\n        bool last = end >= text.length;\n        i32 count = dom_terminal.line_rows(end - start, last, cols);\n        i32 k = 0;\n        while (k < count && row + k - first < rows) {\n            i32 at = row + k - first;\n            i32 a = start + k * cols;\n            i32 b = a + cols;\n            if (b > end) { b = end; }\n            if (at >= 0 && a < b) {\n                if (selecting && sel_from < b && sel_to > a) {\n                    i32 lo = sel_from > a ? sel_from : a;\n                    i32 hi = sel_to < b ? sel_to : b;\n                    graphics.fill_rect(left + (lo - a) * cell, top + at * lh, (hi - lo) * cell, lh,\n                                       theme.TERMINAL_SELECTION);\n                }\n                Option<str> part = text.slice(a, b);\n                str piece = case part of { Some(view) -> view; None -> \"\"; };\n                graphics.draw_mono(left, top + at * lh, piece, theme.TERMINAL_TEXT, s);\n            }\n            k++;\n        }\n        row = row + count;\n        if (last || row - first >= rows) {\n            done = true;\n        } else {\n            start = end + 1;\n        }\n    }\n    // The caret is in the typed line, on the last line of the text, which\n    // takes the last rows; a caret over a byte shows it through.\n    if ((n.state & NodeState::FOCUSED) != 0) {\n        i32 line_start = text.length;\n        while (line_start > 0 && text.byte(line_start - 1) != '\\n') { line_start--; }\n        i32 caret = dom_terminal.caret_byte(&n);\n        i32 offset = caret - line_start;\n        i32 at = total - dom_terminal.line_rows(text.length - line_start, true, cols) + offset / cols - first;\n        if (at >= 0 && at < rows) {\n            i32 column = offset % cols;\n            graphics.fill_rect(left + column * cell, top + at * lh, cell, lh, theme.TERMINAL_CARET);\n            if (caret < text.length) {\n                Option<str> under = text.slice(caret, caret + 1);\n                str glyph = case under of { Some(view) -> view; None -> \"\"; };\n                graphics.draw_mono(left + column * cell, top + at * lh, glyph, theme.TERMINAL_BG, s);\n            }\n        }\n    }\n    graphics.pop_clip();\n    draw_scroll_thumb(&n, theme.SCROLL_THUMB_ON_DARK);\n}\n\n/**\n * Renders a MENU_BUTTON: its title, on a highlight while the pointer is over it.\n * @param n MenuButton node row.\n */\nexport void draw_menu_button(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    if ((n.state & NodeState::HOVERED) != 0) {\n        graphics.fill_round_rect(n.x, n.y, n.w, n.h, 4 * s, theme.MENU_BUTTON_HOVER);\n    }\n    if (n.name.is_live()) {\n        i32 th = graphics.text_height(0, s);\n        str title = n.name.as_str();\n        graphics.draw_label_centered(n.x, n.y + (n.h - th) / 2, n.w, title, theme.TEXT_PRIMARY, 0, s);\n    }\n}\n\n/**\n * Renders text rows for List or Menu controls, highlighting the row in `sel`.\n * @param n DOM Node row.\n * @param hl_color Background RGB color for highlight.\n * @param hl_fg Foreground text RGB color for highlight.\n */\nexport void draw_rows(borrow NodeRow n, i32 hl_color, i32 hl_fg) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 pad = 8 * s;\n    i32 lh = graphics.text_height(0, s);\n    i32 fg = theme.TEXT_PRIMARY;\n    fg = node_fg(&n, fg);\n    Blob buf = n.text;\n    i32 len = n.len;\n    i32 r = theme.BUTTON_RADIUS * s;\n    graphics.push_clip(x + s, y + s, w - 2 * s, h - 2 * s);\n    defer graphics.pop_clip();\n    i32 rows = dom_text_edit.visible_lines(&n);\n    i32 first = n.scroll;\n    i32 start = dom_text_edit.line_start(&n, first);\n    i32 row = 0;\n    while (row < rows) {\n        if (start >= len) { break; }\n        i32 llen = dom_text_edit.line_len_at(&n, start);\n        i32 ty = y + pad + row * lh;\n        i32 color = fg;\n        bool highlighted = case n.sel of {\n            Some(index) -> first + row == index;\n            None -> false;\n        };\n        if (highlighted) {\n            graphics.fill_round_rect(x + 4 * s, ty - s, w - 8 * s, lh + 2 * s, r, hl_color);\n            color = hl_fg;\n        }\n        Text<160> line = copy_line(buf, start, llen);\n        str label_6 = line.as_str();\n        i32 tx = x + pad + 4 * s;\n        i32 icon = dom_text_edit.row_icon(label_6);\n        i32 skip = 0;\n        if (icon != 0) {\n            icons.draw(icon, tx, ty + (lh - icons.SIZE * s) / 2, s);\n            tx = tx + dom_text_edit.ROW_ICON_W * s;\n            skip = 1;\n        }\n        str shown = case label_6.slice(skip, label_6.length) of { Some(view) -> view; None -> \"\"; };\n        graphics.draw_label(tx, ty, shown, color, 0, s);\n        start = start + llen + 1;\n        row = row + 1;\n    }\n}\n\n/**\n * Renders a GRAPH: a card with lines at each quarter, the first series filled\n * under an accent line and the second as a line over it. The samples span the\n * width newest-right, so a series still filling up starts partway across.\n * @param n Graph node row.\n */\nexport void draw_graph(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    draw_rows_box(&n, 0);\n    i32 pad = 8 * s;\n    i32 left = n.x + pad;\n    i32 top = n.y + pad;\n    i32 w = n.w - 2 * pad;\n    i32 h = n.h - 2 * pad;\n    if (w <= 0 || h <= 0) { return; }\n    i32 k = 1;\n    while (k < 4) {\n        graphics.blend_rect(left, top + h * k / 4, w, s, theme.GRAPH_GRID);\n        k++;\n    }\n    i32 cap = n.cap;\n    Samples samples = Samples {};\n    dom_graph.parse_series(dom_graph.series_text(&n, 0), cap, &samples);\n    draw_series(&samples, cap, left, top, w, h, true, theme.ACCENT);\n    dom_graph.parse_series(dom_graph.series_text(&n, 1), cap, &samples);\n    draw_series(&samples, cap, left, top, w, h, false, theme.GRAPH_SECOND);\n}\n\n/**\n * Draws one series of a graph as a line, two pixels thick at UI scale 1.\n * @param v The samples, oldest first.\n * @param cap How many samples span the width.\n * @param left Left of the plot area.\n * @param top Top of the plot area: 100%.\n * @param w Width of the plot area.\n * @param h Height of the plot area.\n * @param filled Whether to fill the area under the line.\n * @param color Line colour.\n */\nvoid draw_series(borrow Samples v, i32 cap, i32 left, i32 top, i32 w, i32 h, bool filled, i32 color) {\n    i32 thickness = 2 * dom.ui_scale();\n    i32 bottom = top + h;\n    i32 first = cap - v.count; // where the oldest sample goes\n    i32 i = 0;\n    while (i + 1 < v.count) {\n        i32 x0 = left + w * (first + i) / (cap - 1);\n        i32 x1 = left + w * (first + i + 1) / (cap - 1);\n        i32 y0 = bottom - h * v.values[i] / 100;\n        i32 y1 = bottom - h * v.values[i + 1] / 100;\n        if (filled) {\n            i32 x = x0;\n            while (x < x1) {\n                i32 y = y0 + (y1 - y0) * (x - x0) / (x1 - x0);\n                if (y < bottom) { graphics.blend_rect(x, y, 1, bottom - y, theme.GRAPH_FILL); }\n                x++;\n            }\n        }\n        i32 t = 0;\n        while (t < thickness) {\n            graphics.draw_line(x0, y0 - t, x1, y1 - t, color);\n            t++;\n        }\n        i++;\n    }\n}\n\n/**\n * Renders a LIST control showing item rows and selected item highlight.\n * @param n List node row.\n */\nexport void draw_list(borrow NodeRow n) {\n    i32 state = n.state;\n    i32 focused = state & NodeState::FOCUSED;\n    draw_rows_box(&n, focused);\n    i32 hl = theme.ACCENT;\n    i32 hl_fg = theme.ON_ACCENT;\n    if (!focused) {\n        hl = theme.BUTTON_FACE_PRESSED;\n        hl_fg = theme.TEXT_PRIMARY;\n    }\n    draw_rows(&n, hl, hl_fg);\n    draw_scroll_thumb(&n, theme.SCROLL_THUMB);\n}\n\n/**\n * Renders a floating popup MENU control with drop shadow and hovered item highlight.\n * @param n Menu node row.\n */\nexport void draw_menu(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 r = theme.BUTTON_RADIUS * s;\n    graphics.draw_shadow(n.x, n.y, n.w, n.h, r, 8 * s, 3 * s, 70);\n    i32 bg = theme.PANEL_BG;\n    graphics.fill_round_rect(n.x, n.y, n.w, n.h, r, bg);\n    i32 border = theme.WINDOW_BORDER;\n    graphics.draw_round_rect(n.x, n.y, n.w, n.h, r, s, border);\n    i32 hl = theme.ACCENT;\n    i32 hl_fg = theme.ON_ACCENT;\n    draw_rows(&n, hl, hl_fg);\n}\n\n/**\n * Renders a static TEXT node with left or centered alignment.\n * @param n Text node row.\n */\nexport void draw_text_node(borrow NodeRow n) {\n    if (!n.text.is_live()) { return; }\n    i32 s = dom.ui_scale();\n    i32 color = theme.TEXT_PRIMARY;\n    color = node_fg(&n, color);\n    i32 bold = 0;\n    if (dom.text_bold(&n)) { bold = 1; }\n    i32 style = n.style;\n    if (style & NodeStyle::CENTER) {\n        str label_7 = n.text.as_str();\n        graphics.draw_label_centered(n.x, n.y, n.w, label_7, color, bold, s);\n    } else {\n        str label_8 = n.text.as_str();\n        graphics.draw_label(n.x, n.y, label_8, color, bold, s);\n    }\n}\n\n/**\n * Renders a single-line TEXT_INPUT control with placeholder or text and blinking caret.\n * @param n TextInput node row.\n */\nexport void draw_text_input(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 state = n.state;\n    i32 focused = state & NodeState::FOCUSED;\n    i32 r = theme.INPUT_RADIUS * s;\n    i32 pad = theme.INPUT_PADDING_X * s;\n\n    i32 bg = theme.INPUT_BG;\n    graphics.fill_round_rect(x, y, w, h, r, bg);\n    i32 border = theme.INPUT_BORDER;\n    i32 bw = s;\n    if (focused != 0) {\n        border = theme.INPUT_BORDER_FOCUS;\n        bw = 2 * s;\n    }\n    graphics.draw_round_rect(x, y, w, h, r, bw, border);\n\n    i32 th = graphics.text_height(0, s);\n    i32 ty = y + (h - th) / 2;\n    // Text wider than the field slides left to keep the caret in view.\n    i32 left = x + pad - dom_text_edit.input_scroll(&n);\n    graphics.push_clip(x + pad / 2, y, w - pad, h);\n    defer graphics.pop_clip();\n    if (focused != 0 && dom_text_edit.has_selection(&n)) {\n        str all = n.text.as_str();\n        i32 sel_left = left + graphics.text_width_n(all, dom_text_edit.selection_start(&n), 0, s);\n        i32 sel_right = left + graphics.text_width_n(all, dom_text_edit.selection_end(&n), 0, s);\n        graphics.fill_rect(sel_left, ty, sel_right - sel_left, th, theme.SELECTION);\n    }\n    if (n.len == 0) {\n        if (n.name.is_live()) {\n            i32 ph = theme.INPUT_PLACEHOLDER;\n            str label_9 = n.name.as_str();\n            graphics.draw_label(x + pad, ty, label_9, ph, 0, s);\n        }\n    } else {\n        i32 fg = theme.TEXT_PRIMARY;\n        fg = node_fg(&n, fg);\n        str label_10 = n.text.as_str();\n        graphics.draw_label(left, ty, label_10, fg, 0, s);\n    }\n    if (focused != 0) {\n        i32 cur = n.cursor;\n        str label_11 = n.text.as_str();\n        i32 caret_x = left + graphics.text_width_n(label_11, cur, 0, s);\n        i32 caret = theme.CARET;\n        graphics.fill_rect(caret_x, ty + s, s, th - 2 * s, caret);\n    }\n}\n\n/**\n * Renders a CHECKBOX control with box, checkmark, and label text.\n * @param n Checkbox node row.\n */\nexport void draw_checkbox(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 h = n.h;\n    i32 state = n.state;\n    i32 checked = state & NodeState::CHECKED;\n    i32 box = theme.CHECKBOX_SIZE * s;\n    i32 r = theme.CHECKBOX_RADIUS * s;\n    i32 by = y + (h - box) / 2;\n\n    i32 face = theme.CHECKBOX_BG;\n    i32 border = theme.CHECKBOX_BORDER;\n    if (checked) {\n        face = theme.ACCENT;\n        border = theme.ACCENT_PRESSED;\n        if (state & NodeState::PRESSED) { face = theme.ACCENT_PRESSED; }\n        else if (state & NodeState::HOVERED) { face = theme.ACCENT_HOVER; }\n    } else {\n        if (state & NodeState::PRESSED) { face = theme.BUTTON_FACE_PRESSED; }\n        else if (state & NodeState::HOVERED) { face = theme.BUTTON_FACE_HOVER; }\n    }\n    graphics.fill_round_rect(x, by, box, box, r, face);\n    graphics.draw_round_rect(x, by, box, box, r, s, border);\n    if (state & NodeState::FOCUSED) {\n        i32 ring = theme.ACCENT;\n        graphics.draw_round_rect(x - 2 * s, by - 2 * s, box + 4 * s, box + 4 * s, r + 2 * s, s, ring);\n    }\n    if (checked) {\n        // Check mark: two strokes, drawn s+1 times side by side for weight.\n        i32 white = theme.ON_ACCENT;\n        i32 x0 = x + box * 25 / 100;\n        i32 y0 = by + box * 52 / 100;\n        i32 x1 = x + box * 43 / 100;\n        i32 y1 = by + box * 70 / 100;\n        i32 x2 = x + box * 76 / 100;\n        i32 y2 = by + box * 30 / 100;\n        i32 k = 0;\n        while (k < s + 1) {\n            graphics.draw_line(x0, y0 + k, x1, y1 + k, white);\n            graphics.draw_line(x1, y1 + k, x2, y2 + k, white);\n            k++;\n        }\n    }\n    if (n.text.is_live()) {\n        i32 fg = theme.TEXT_PRIMARY;\n        fg = node_fg(&n, fg);\n        i32 th = graphics.text_height(0, s);\n        str label_12 = n.text.as_str();\n        graphics.draw_label(x + box + 8 * s, y + (h - th) / 2, label_12, fg, 0, s);\n    }\n}\n\n/**\n * Renders a rounded card PANEL container.\n * @param n Panel node row.\n */\nexport void draw_panel(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 bg = theme.PANEL_BG;\n    i32 border = theme.PANEL_BORDER;\n    i32 r = n.radius;\n    graphics.fill_round_rect(n.x, n.y, n.w, n.h, r, bg);\n    graphics.draw_round_rect(n.x, n.y, n.w, n.h, r, s, border);\n}\n\n// --- taskbar ---\n// The bar lists every window on the desktop but dialogs (click to activate),\n// oldest first, with a launcher button at the left. Entries are laid out\n// arithmetically at draw and hit time rather than as child nodes, so the bar\n// never has to be rebuilt when windows come and go; they narrow when there\n// are more than fit at full width.\n\n/**\n * The window the taskbar lists after the one created `after`: each window on\n * the desktop but a dialog, oldest first. A node id is reused, so the order\n * goes by NodeRow.serial.\n * @param after The serial of the last window listed, or 0 for the first.\n * @return The next window, if any.\n */\nexport Option<NodeId> next_window_after(i32 after) {\n    Option<NodeId> best = None;\n    i32 best_serial = 0;\n    for (NodeId child_id in dom.children(dom.desktop_id())) {\n        borrow NodeRow c = dom.row_of(child_id);\n        if (c.kind == NodeKind::WINDOW && !dom.is_dialog(&c) && c.serial > after) {\n            if (best.is_none() || c.serial < best_serial) {\n                best = Some(child_id);\n                best_serial = c.serial;\n            }\n        }\n    }\n    return best;\n}\n\n// Apps started that have no window yet: the taskbar shows each after the\n// windows, dimmed, until its window comes or it ends. The shell says which.\n\n/**\n * An app the taskbar shows as starting.\n * @property key Whatever the shell knows it by: its process.\n * @property icon Its icon (Icon).\n * @property label Its name.\n */\nstruct Starting {\n    i32 key;\n    i32 icon;\n    Text<32> label;\n};\n\nconst i32 STARTING_MAX = 4;\nStarting g_starting[4];\ni32 g_starting_count = 0;\n\nvoid damage_taskbar() {\n    case dom.row_in(dom.taskbar_id()) of {\n        Some(bar) -> ({ dom.damage_row(&bar); });\n        None -> _;\n    };\n}\n\n/**\n * Shows an app on the taskbar as starting, until forget_starting.\n * @param key What the shell knows it by.\n * @param label Its name.\n * @param icon Its icon (Icon).\n */\nexport void note_starting(i32 key, str label, i32 icon) {\n    if (g_starting_count >= STARTING_MAX) { return; }\n    Starting entry = Starting { key: key, icon: icon, label: Text<32> {} };\n    entry.label.append(label);\n    g_starting[g_starting_count] = entry;\n    g_starting_count++;\n    damage_taskbar();\n}\n\n/**\n * Takes a starting app off the taskbar: its window came, or it ended.\n * @param key What the shell knows it by.\n */\nexport void forget_starting(i32 key) {\n    i32 i = 0;\n    while (i < g_starting_count) {\n        if (g_starting[i].key == key) {\n            i32 j = i;\n            while (j + 1 < g_starting_count) {\n                g_starting[j] = g_starting[j + 1];\n                j++;\n            }\n            g_starting_count--;\n            damage_taskbar();\n            return;\n        }\n        i++;\n    }\n}\n\n// How many windows the taskbar lists.\ni32 taskbar_window_count() {\n    i32 count = 0;\n    i32 after = 0;\n    while (1) {\n        NodeId win = case next_window_after(after) of { Some(id) -> id; None -> ({ break; }); };\n        after = dom.row_of(win).serial;\n        count++;\n    }\n    return count;\n}\n\n/**\n * The width of each taskbar entry when `count` share a bar `bar_w` wide: the\n * full width while they fit, narrower after that.\n * @param count Windows listed.\n * @param bar_w The taskbar's width in display pixels.\n * @return Entry width in display pixels.\n */\nexport i32 taskbar_entry_width(i32 count, i32 bar_w) {\n    i32 s = dom.ui_scale();\n    i32 full = theme.TASKBAR_ENTRY_W * s;\n    if (count <= 0) { return full; }\n    i32 gap = 6 * s;\n    i32 room = bar_w - taskbar_entry_x(0, full) - 8 * s;\n    i32 fit = (room + gap) / count - gap;\n    if (fit < 24 * s) { fit = 24 * s; }\n    return fit < full ? fit : full;\n}\n\n/**\n * Computes the X offset of a taskbar entry from the bar's left edge.\n * @param index 0-based window index.\n * @param width Entry width (taskbar_entry_width).\n * @return Offset in display pixels.\n */\nexport i32 taskbar_entry_x(i32 index, i32 width) {\n    i32 s = dom.ui_scale();\n    i32 launcher = theme.TASKBAR_LAUNCHER_W * s;\n    return 8 * s + launcher + 8 * s + index * (width + 6 * s);\n}\n\n/**\n * Renders the desktop taskbar: the launcher button and an entry per window.\n * @param n Taskbar node row.\n */\nexport void draw_taskbar(borrow NodeRow n) {\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n\n    i32 bg = theme.TASKBAR_BG;\n    graphics.blend_rect(x, y, w, h, bg);\n    i32 edge = theme.TASKBAR_EDGE;\n    graphics.blend_rect(x, y, w, s, edge);\n\n    // Launcher: accent dot + \"MyOS\".\n    i32 accent = theme.ACCENT;\n    i32 on_dark = theme.TEXT_ON_DARK;\n    i32 lx = x + 8 * s;\n    i32 lw = theme.TASKBAR_LAUNCHER_W * s;\n    i32 er = theme.TASKBAR_ENTRY_RADIUS * s;\n    i32 entry_bg = theme.TASKBAR_ENTRY;\n    graphics.fill_round_rect(lx, y + 6 * s, lw, h - 12 * s, er, entry_bg);\n    graphics.fill_disc(lx + 16 * s, y + h / 2, 6 * s, accent);\n    i32 th_b = graphics.text_height(1, s);\n    graphics.draw_label(lx + 30 * s, y + (h - th_b) / 2, \"MyOS\", on_dark, 1, s);\n\n    // One entry per window, in creation order, so raising a window does not\n    // shuffle the bar; then the apps still starting.\n    i32 ew = taskbar_entry_width(taskbar_window_count() + g_starting_count, w);\n    i32 active_bg = theme.TASKBAR_ENTRY_ACTIVE;\n    i32 dim = theme.TEXT_ON_DARK_DIM;\n    i32 th = graphics.text_height(0, s);\n    i32 index = 0;\n    i32 after = 0;\n    while (1) {\n        NodeId win = case next_window_after(after) of { Some(id) -> id; None -> ({ break; }); };\n        borrow NodeRow c = dom.row_of(win);\n        i32 ex = x + taskbar_entry_x(index, ew);\n        i32 ebg = entry_bg;\n        i32 fg = dim;\n        bool active = dom.holds(dom.active_window_id(), win);\n        if (active) { ebg = active_bg; fg = on_dark; }\n        graphics.fill_round_rect(ex, y + 6 * s, ew, h - 12 * s, er, ebg);\n        if (active) {\n            graphics.fill_round_rect(ex + 10 * s, y + h - 9 * s, ew - 20 * s, 2 * s, s, accent);\n        }\n        graphics.push_clip(ex + 10 * s, y, ew - 20 * s, h);\n        i32 tx = ex + 12 * s;\n        if (c.icon != 0) {\n            icons.draw(c.icon, ex + 10 * s, y + (h - icons.SIZE * s) / 2, s);\n            tx = ex + 32 * s;\n        }\n        if (c.text.is_live()) {\n            str label_13 = c.text.as_str();\n            graphics.draw_label(tx, y + (h - th) / 2, label_13, fg, 0, s);\n        }\n        graphics.pop_clip();\n        index = index + 1;\n        after = c.serial;\n    }\n    i32 k = 0;\n    while (k < g_starting_count) {\n        Starting entry = g_starting[k];\n        i32 ex = x + taskbar_entry_x(index, ew);\n        graphics.draw_round_rect(ex, y + 6 * s, ew, h - 12 * s, er, s, entry_bg);\n        graphics.push_clip(ex + 10 * s, y, ew - 20 * s, h);\n        icons.draw(entry.icon, ex + 10 * s, y + (h - icons.SIZE * s) / 2, s);\n        str name = entry.label.as_str();\n        graphics.draw_label(ex + 32 * s, y + (h - th) / 2, name, dim, 0, s);\n        graphics.pop_clip();\n        index = index + 1;\n        k++;\n    }\n}\n\n/** Target identified by hit-testing a pointer position on the taskbar. */\nexport enum TaskbarTarget {\n    Miss,\n    Launcher,\n    Window(NodeId),\n}\n\n/**\n * Hit tests display point (px, py) on the taskbar to identify what was clicked.\n * @param px Screen X coordinate.\n * @param py Screen Y coordinate.\n * @return TaskbarTarget (Miss, Launcher, or Window(id)).\n */\nexport TaskbarTarget taskbar_target_at(i32 px, i32 py) {\n    borrow NodeRow n = case dom.row_in(dom.taskbar_id()) of { Some(row) -> row; None -> ({ return TaskbarTarget::Miss; }); };\n    i32 s = dom.ui_scale();\n    i32 x = n.x;\n    i32 lx = x + 8 * s;\n    i32 lw = theme.TASKBAR_LAUNCHER_W * s;\n    if (px >= lx) {\n        if (px < lx + lw) { return TaskbarTarget::Launcher; }\n    }\n    i32 ew = taskbar_entry_width(taskbar_window_count(), n.w);\n    i32 index = 0;\n    i32 after = 0;\n    while (1) {\n        NodeId win = case next_window_after(after) of { Some(id) -> id; None -> ({ break; }); };\n        i32 ex = x + taskbar_entry_x(index, ew);\n        if (px >= ex) {\n            if (px < ex + ew) { return TaskbarTarget::Window(win); }\n        }\n        index++;\n        after = dom.row_of(win).serial;\n    }\n    return TaskbarTarget::Miss;\n}\n\n// What the launcher button does; the shell installs it.\nvoid no_launcher() { }\nfn() -> void g_launcher = no_launcher;\n\n/**\n * Registers an application launcher callback for the taskbar launcher button.\n * @param handler Function pointer to launcher callback: fn().\n */\nexport void set_launcher(fn() -> void handler) { g_launcher = handler; }\n\n/**\n * Returns the callback for the taskbar launcher button.\n * @return The callback set_launcher installed, or one that does nothing.\n */\nexport fn() -> void launcher_handler() { return g_launcher; }\n\n/**\n * Dispatches node drawing to the kind-specific drawing routine.\n * @param n DOM Node row to render.\n */\nexport void draw_node(borrow NodeRow n) {\n    i32 kind = n.kind;\n    i32 x = n.x;\n    i32 y = n.y;\n    i32 w = n.w;\n    i32 h = n.h;\n    i32 scale = dom.ui_scale();\n\n    if (kind == NodeKind::TEXT_AREA) {\n        draw_text_area(&n);\n    } else if (kind == NodeKind::LIST) {\n        draw_list(&n);\n    } else if (kind == NodeKind::GRAPH) {\n        draw_graph(&n);\n    } else if (kind == NodeKind::TERMINAL) {\n        draw_terminal(&n);\n    } else if (kind == NodeKind::MENU_BUTTON) {\n        draw_menu_button(&n);\n    } else if (kind == NodeKind::MENU) {\n        draw_menu(&n);\n    } else if (kind == NodeKind::BOX) {\n        graphics.fill_rect(x, y, w, h, n.background_color);\n        graphics.draw_rect_scaled(x, y, w, h, n.border_color, scale);\n    } else if (kind == NodeKind::WINDOW) {\n        draw_window(&n);\n    } else if (kind == NodeKind::BUTTON) {\n        draw_button(&n);\n    } else if (kind == NodeKind::TEXT) {\n        draw_text_node(&n);\n    } else if (kind == NodeKind::TEXT_INPUT) {\n        draw_text_input(&n);\n    } else if (kind == NodeKind::CHECKBOX) {\n        draw_checkbox(&n);\n    } else if (kind == NodeKind::SEPARATOR) {\n        i32 sep = theme.SEPARATOR;\n        graphics.blend_rect(x, y, w, h, sep);\n    } else if (kind == NodeKind::PANEL) {\n        draw_panel(&n);\n    } else if (kind == NodeKind::TASKBAR) {\n        draw_taskbar(&n);\n    }\n    // Structural nodes (root/system/process/...) draw nothing.\n}\n\n/**\n * Checks if a node's full extent intersects the current paint damage rectangle.\n * @param n DOM Node row.\n * @return True if node overlaps damage area or full repaint active, false otherwise.\n */\nexport bool node_in_damage(borrow NodeRow n) {\n    return dom.node_intersects_paint(&n);\n}\n\n/**\n * Recursively renders a DOM row and its descendants respecting damage clipping.\n * @param n DOM Node row to render.\n */\nexport void render(borrow NodeRow n) {\n    if (!(n.state & NodeState::VISIBLE)) { return; }\n\n    bool in_damage = node_in_damage(&n);\n    if (in_damage) {\n        draw_node(&n);\n    }\n\n    // Children are visited regardless: a child can overlap the damage region\n    // even when its parent does not -- unless the parent clips them, in\n    // which case an off-damage parent means off-damage children.\n    bool clip = dom.clips_children(&n);\n    if (clip) {\n        if (!in_damage) { return; }\n        graphics.push_clip(n.x, n.y, n.w, n.h);\n    }\n    for (NodeId child_id in dom.children(n.id)) {\n        render(&dom.row_of(child_id));\n    }\n    if (clip) { graphics.pop_clip(); }\n}\n\n/**\n * Paints the desktop background gradient, all desktop child windows, taskbar, and active menu.\n */\nexport void paint_desktop() {\n    i32 top = theme.DESKTOP_TOP;\n    i32 bottom = theme.DESKTOP_BOTTOM;\n    i32 dw = graphics.display_width();\n    i32 dh = graphics.display_height();\n    graphics.fill_gradient_v(0, 0, dw, dh, top, bottom);\n\n    Option<NodeId> taskbar = dom.taskbar_id();\n    Option<NodeId> menu = dom_menu.menu_id();\n    for (NodeId child_id in dom.children(dom.desktop_id())) {\n        if (!dom.holds(taskbar, child_id) && !dom.holds(menu, child_id)) {\n            render(&dom.row_of(child_id));\n        }\n    }\n    case dom.row_in(taskbar) of { Some(row) -> render(&row); None -> _; };\n    case dom.row_in(menu) of { Some(row) -> render(&row); None -> _; };\n}\n\n/**\n * Performs an unconditional full screen repaint of the desktop. It covers all\n * damage queued before it starts; damage added while it paints stays queued.\n */\nexport void render_all() {\n    dom.clear_damage();\n    dom.select_full_paint();\n    graphics.clear_clip();\n    paint_desktop();\n}\n\n/**\n * Repaints only damaged regions using clip rectangles, falling back to full repaint if empty.\n */\nexport void render_scene() {\n    if (dom.damage_count() == 0) {\n        render_all();\n        return;\n    }\n\n    // Paint each damaged rectangle under its own clip. The rectangles are\n    // taken off the queue as the paint begins, so anything damaged while\n    // painting (a process's console output arrives on its own task) waits\n    // for the next frame rather than extending this loop or being dropped.\n    i32 count = dom.take_damage();\n    i32 i = 0;\n    while (i < count) {\n        dom.select_damage(i);\n        graphics.set_clip(dom.paint_x(), dom.paint_y(), dom.paint_width(), dom.paint_height());\n        paint_desktop();\n        i++;\n    }\n    dom.select_full_paint();\n    graphics.clear_clip();\n}\n\n","system/MyOS/src/ui/protocol.unsafe.mln":"/**\n * The UI server's request-side handler of the UI protocol.\n *\n * Executes application UI requests against the desktop DOM.\n * Automatically sets the DOM current owner to the requesting process so that\n * any newly created nodes, windows, or dialogs belong to that application.\n */\nnamespace ui_protocol;\n\nimport str from \"@std/text/str.mln\";\nimport { Option } from \"@std/core/option.mln\";\nimport { Pid } from \"@contracts/process/control.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport { NodeId, UiError } from \"@contracts/ui/widget.contract.mln\";\nimport dom from \"dom/dom.mln\";\nimport { NodeKind, NodeStyle } from \"dom/dom.mln\";\nimport dom_widgets from \"dom/dom_widgets.mln\";\nimport dom_focus from \"dom/dom_focus.mln\";\nimport dom_list from \"dom/dom_list.mln\";\nimport dom_graph from \"dom/dom_graph.mln\";\nimport dom_text_edit from \"dom/dom_text_edit.mln\";\nimport dom_terminal from \"dom/dom_terminal.mln\";\nimport irq from \"@kernel/arch/irq.mln\";\nimport protocol_elements from \"protocol_elements.mln\";\nimport { NodeRow } from \"dom/dom_model.mln\";\nimport { Blob } from \"@std/memory/blob.mln\";\nimport { Request, RequestStatus } from \"@contracts/myapp/message.contract.mln\";\nimport { UiOp } from \"@contracts/myapp/ui.contract.mln\";\n\nbool writes_typed_result(i32 op) {\n    if (op == UiOp::TEXT_COPY) { return true; }\n    return op >= UiOp::CREATE_WINDOW && op <= UiOp::APPEND_CHILD;\n}\n\n// The operations return their results; this is where one leaves for the\n// result the gateway staged, since the request crosses as words.\nRequestStatus answer<T>(Request *m, T value) {\n    T *out = (T*)m->result_out;\n    *out = value;\n    return RequestStatus::OK;\n}\n\n// Copies a view into a staged NUL-terminated buffer; a longer view is cut.\n// The buffer is the wire's: the view is what the operations return.\nResult<i32, UiError> staged(Result<str, UiError> view, char *out, i32 cap) {\n    str text = view?;\n    if (cap <= 0) { return Err(UiError::InvalidCapacity(cap)); }\n    i32 n = text.length;\n    if (n > cap - 1) { n = cap - 1; }\n    i32 i = 0;\n    while (i < n) { out[i] = text.data[i]; i++; }\n    out[n] = (char)0;\n    return Ok(n);\n}\n\n/**\n * Executes a single UI protocol request within the caller's owner scope.\n *\n * Temporarily switches the active DOM owner to `m->owner` during execution,\n * ensuring proper resource ownership for windows and child elements.\n *\n * @param m Pointer to Request structure.\n * @return Request dispatch status. Typed operation results use Request.result_out.\n */\nexport RequestStatus handle(Request *m) {\n    Option<Pid> outer = dom.current_owner();\n    dom.set_current_owner(Some(Pid(m->owner)));\n    defer dom.set_current_owner(outer);\n    return run_request(m);\n}\n\n/**\n * Dispatches an unpacked UI request to the corresponding internal handler.\n *\n * @param m Pointer to Request structure.\n * @return Request dispatch status.\n */\nRequestStatus run_request(Request *m) {\n    i32 op = m->op;\n    NodeId id = NodeId(m->a0);   // what a0 means to the operations that take a node\n    if (writes_typed_result(op) && m->result_out == 0) {\n        return RequestStatus::MISSING_RESULT;\n    }\n    if (op == UiOp::SET_TEXT)       { set_text(id, m->s0); return RequestStatus::OK; }\n    if (op == UiOp::TEXT_COPY) {\n        return answer<Result<i32, UiError>>(m, staged(text_of(id), (char*)m->a1, m->a2));\n    }\n    if (op == UiOp::SET_CHECKED)    { set_checked(id, m->a1); return RequestStatus::OK; }\n    if (op == UiOp::INPUT_SET)      { input_set(id, m->s0); return RequestStatus::OK; }\n    if (op == UiOp::AREA_APPEND)    { area_append(id, m->s0); return RequestStatus::OK; }\n    if (op == UiOp::LIST_SET_ITEMS) { list_set_items(id, m->s0); return RequestStatus::OK; }\n    if (op == UiOp::LIST_SELECT)    { dom_list.list_select(id, m->a1); return RequestStatus::OK; }\n    if (op == UiOp::GRAPH_SET)      { dom_graph.graph_set(id, m->a1, str.from_c(m->s0)); return RequestStatus::OK; }\n    if (op == UiOp::ADD_STYLE)      { add_style(id, m->a1); return RequestStatus::OK; }\n    if (op == UiOp::TEXT_EDIT)      { dom_widgets.text_edit(id, m->a1); return RequestStatus::OK; }\n    if (op == UiOp::FOCUS)          { focus(id); return RequestStatus::OK; }\n    if (op == UiOp::SEND_KEY)       { send_key(m->a0, m->a1, m->a2); return RequestStatus::OK; }\n    if (op >= UiOp::CREATE_WINDOW && op <= UiOp::APPEND_CHILD) {\n        return answer<Result<NodeId, UiError>>(m, protocol_elements.create(m));\n    }\n    return RequestStatus::INVALID_OPERATION;\n}\n\n// --- text -------------------------------------------------------------------------------------\n\n/**\n * Sets the displayed text of a node.\n *\n * @param id UI node ID.\n * @param s Text string to set.\n */\nvoid set_text(NodeId id, char *s) { dom.set_text(id, str.from_c(s)); }\n\n/**\n * Reads a node's text.\n *\n * @param id UI node ID.\n * @return Ok(a view of the text), or Err for an invalid node.\n */\nResult<str, UiError> text_of(NodeId id) {\n    borrow NodeRow n = dom.require_row(id)?;\n    return Ok(n.text.as_str());\n}\n\n// --- widgets --------------------------------------------------------------------------------\n\n/**\n * Sets the checked state of a checkbox node.\n *\n * @param id UI node ID.\n * @param on 1 to check, 0 to uncheck.\n */\nvoid set_checked(NodeId id, i32 on) { dom.set_checked(id, on); }\n\n/**\n * Sets the value of a text input or a text area.\n *\n * @param id UI node ID.\n * @param s Input text.\n */\nvoid input_set(NodeId id, char *s) { dom_text_edit.set_input_text(id, str.from_c(s)); }\n\n/**\n * Appends text to a multi-line text area with IRQ protection.\n *\n * Temporarily disables interrupts to prevent race conditions with user-process\n * stdout syscall writes into the same text area buffer.\n *\n * @param id UI node ID.\n * @param s Text to append.\n */\nvoid area_append(NodeId id, char *s) {\n    i32 was = irq.save_disable();\n    defer irq.restore(was);\n    bool terminal = case dom.kind_of(id) of { Some(kind) -> kind == NodeKind::TERMINAL; None -> false; };\n    if (terminal) { dom_terminal.write(id, str.from_c(s)); }\n    else { dom_text_edit.append_text(id, str.from_c(s)); }\n}\n\n/**\n * Replaces the items of a List or a MenuButton with newline-separated strings.\n *\n * @param id UI node ID.\n * @param items Newline-separated item string.\n */\nvoid list_set_items(NodeId id, char *items) {\n    bool menu = case dom.kind_of(id) of { Some(kind) -> kind == NodeKind::MENU_BUTTON; None -> false; };\n    if (menu) { dom.set_text(id, str.from_c(items)); }\n    else { dom_list.list_set_items(id, str.from_c(items)); }\n}\n\n/**\n * Adds NodeStyle bits an app may set: how a node follows its window's size,\n * a TextArea's wrapping, and whether it reports its caret.\n *\n * @param id UI node ID.\n * @param bits NodeStyle bits; any others are ignored.\n */\nvoid add_style(NodeId id, i32 bits) {\n    i32 allowed = NodeStyle::GROW_W | NodeStyle::GROW_H | NodeStyle::PIN_BOTTOM\n        | NodeStyle::WRAP | NodeStyle::REPORT_CARET;\n    dom.add_style(id, bits & allowed);\n}\n\n// --- focus and windows ------------------------------------------------------------------------\n\n/**\n * Sets input focus to a specific control node.\n *\n * @param id UI node ID.\n */\nvoid focus(NodeId id) { dom_focus.set_focus(id); }\n\n// --- keys ---------------------------------------------------------------------------------------\n\n/**\n * Dispatches a simulated key event to the focused widget.\n *\n * @param type Event type (1 = key down, 3 = character input).\n * @param code Key code or character code.\n * @param mods Active modifier keys (shift, ctrl, alt).\n */\nvoid send_key(i32 type, i32 code, i32 mods) { dom_widgets.dispatch_key_event(type, code, mods); }\n","toolchain/MyStdLib/hosted/process.unsafe.mln":"namespace process;\n\n// Generic process control for hosted MyLang programs. UI-specific stdout\n// binding remains in MyAppFramework's terminal integration.\n\nimport myos_service from \"@std/platform/myos/service.mln\";\nimport { OsService } from \"@contracts/myos/services.contract.mln\";\nimport { Result } from \"@std/core/result.mln\";\nimport { SpawnError } from \"@contracts/process/spawn.contract.mln\";\nimport { SyscallFailure, ProcessSignal } from \"@contracts/myos/syscall.contract.mln\";\nimport { sys_wait_notification } from \"@std/platform/myos/syscall.masm\";\nimport { Pid, ProcessControlError, ProcessControlStatus, ProcessExitStatus } from \"@contracts/process/control.contract.mln\";\nimport { ProcSpawnArgs, ProcExitedArgs, ProcReapArgs, ProcFeedArgs, ProcStatsArgs, ProcStats, ProcInfo, CpuTimes, ProcActivity, ProcArgsArgs } from \"@contracts/myos/process-args.contract.mln\";\nimport myos_process_args from \"@contracts/myos/process-args.contract.mln\";\nimport { Text } from \"@std/text/text.mln\";\n\n/** Reads a service that answers in its status word, as PROC_FEED does.\n * @param pid Process the request named.\n * @param reply What the service call returned.\n * @return Ok(_), or Err(InvalidPid) when the OS refused or never answered.\n */\nexport Result<_, ProcessControlError> control_result(Pid pid, Result<i32, SyscallFailure> reply) {\n    bool accepted = case reply of {\n        Ok(word) -> word == (i32)ProcessControlStatus::Accepted;\n        Err(_) -> false;\n    };\n    if (accepted) { return Ok(_); }\n    return Err(ProcessControlError::InvalidPid(pid));\n}\n\n/** Start an executable process, as a child of this one. It writes where this\n * process writes, and on a terminal it takes the lines typed there until it ends.\n * @param path Executable path, or a name looked up in /bin then /apps.\n * @return New process ID, or the detailed spawn error.\n */\n@safe\nexport Result<Pid, SpawnError> spawn(str path) { return spawn_with(path, \"\"); }\n\n/** Start an executable process with arguments, as spawn does.\n * @param path Executable path, or a name looked up in /bin then /apps.\n * @param arguments What it reads with args(): the rest of a command line.\n * @return New process ID, or the detailed spawn error.\n */\n@safe\nexport Result<Pid, SpawnError> spawn_with(str path, str arguments) {\n    Result<Pid, SpawnError> result;\n    ProcSpawnArgs<Result<Pid, SpawnError>> args = ProcSpawnArgs<Result<Pid, SpawnError>> {\n        path: path.data, path_length: path.length, args: arguments.data, args_length: arguments.length,\n        stdout_node: 0, result_out: &result\n    };\n    myos_service.call(OsService::PROC_SPAWN, (i32)(&args));\n    return result;\n}\n\n/** What this process was started with after its name, e.g. \"hello\" for\n * `echo hello` typed in sh; empty for nothing.\n * @return The arguments, at most ARGS_MAX bytes.\n */\n@safe\nexport Text<128> args() {\n    Text<128> text = Text<128> {};\n    char buffer[128];\n    ProcArgsArgs request = ProcArgsArgs { out: &buffer[0], capacity: myos_process_args.ARGS_MAX };\n    i32 length = case myos_service.call(OsService::PROC_ARGS, (i32)(&request)) of {\n        Ok(value) -> value;\n        Err(_) -> 0;\n    };\n    i32 i = 0;\n    while (i < length) {\n        text.push((u8)buffer[i]);\n        i++;\n    }\n    return text;\n}\n\n/** Check whether a process has exited.\n * @param pid Process ID to query.\n * @return True if exited, false if still running, or a process-control error.\n */\n@safe\nexport Result<bool, ProcessControlError> has_exited(Pid pid) {\n    Result<bool, ProcessControlError> result;\n    ProcExitedArgs<Result<bool, ProcessControlError>> args = ProcExitedArgs<Result<bool, ProcessControlError>> {\n        pid: (i32)pid, result_out: &result\n    };\n    myos_service.call(OsService::PROC_EXITED, (i32)(&args));\n    return result;\n}\n\n/** Reap an exited process and retrieve its typed termination status.\n * @param pid Process ID to reap.\n * @return Application exit code or kernel termination reason, or a process-control error.\n */\n@safe\nexport Result<ProcessExitStatus, ProcessControlError> reap(Pid pid) {\n    Result<ProcessExitStatus, ProcessControlError> result;\n    ProcReapArgs<Result<ProcessExitStatus, ProcessControlError>> args = ProcReapArgs<Result<ProcessExitStatus, ProcessControlError>> {\n        pid: (i32)pid, result_out: &result\n    };\n    myos_service.call(OsService::PROC_REAP, (i32)(&args));\n    return result;\n}\n\n/** Waits for a child to end, then reaps it. The thread sleeps meanwhile: an\n * unfinished has_exited arms ProcessSignal::CHILD, and the child's end raises it.\n * @param pid The child.\n * @return Its exit status, or Err(InvalidPid) when pid names no child of this process.\n */\n@safe\nexport Result<ProcessExitStatus, ProcessControlError> wait(Pid pid) {\n    while (!has_exited(pid)?) {\n        i32 woken = 0;\n        sys_wait_notification(ProcessSignal::CHILD, &woken);\n    }\n    return reap(pid);\n}\n\n/** Send an input line to a process.\n * @param pid Recipient process ID.\n * @param line Line to deliver.\n * @return Ok(_), or Err(InvalidPid) when pid names no child of this process.\n */\n@safe\nexport Result<_, ProcessControlError> feed_line(Pid pid, str line) {\n    ProcFeedArgs args = ProcFeedArgs { pid: (i32)pid, line: line.data, line_length: line.length };\n    return control_result(pid, myos_service.call(OsService::PROC_FEED, (i32)(&args)));\n}\n\n/** Read every process, what it is doing and what it costs, and where the\n * CPU's time went. Any process may ask, about every process: it changes nothing.\n * @return The numbers. Times are in timer clock units (256 a tick) since boot\n *         and wrap; compare two readings to see what share of the time\n *         between them each one took.\n */\n@safe\nexport ProcStats stats() {\n    ProcStats result = ProcStats {};\n    ProcStatsArgs args = ProcStatsArgs { result_out: &result };\n    myos_service.call(OsService::PROC_STATS, (i32)(&args));\n    return result;\n}\n"};
